export default {"meta": {"version": "1.0", "modules_count": 6, "chapters_count": 20, "questions_count": 293}, "modules": [{"code": "recruitment", "name": "招聘与面试", "icon": "🎯", "description": "从岗位需求分析、简历筛选、结构化面试到录用决策的全流程招聘技能。", "sort_order": 1}, {"code": "performance", "name": "绩效管理", "icon": "📊", "description": "KPI/OKR 设定、绩效面谈与评估流程设计的系统方法。", "sort_order": 2}, {"code": "compensation", "name": "薪酬福利", "icon": "💰", "description": "薪酬结构设计、岗位价值评估与福利体系规划。", "sort_order": 3}, {"code": "employee-relations", "name": "员工关系", "icon": "🤝", "description": "员工入职管理、沟通协调、冲突处理与离职管理的全生命周期关系维护。", "sort_order": 4}, {"code": "training", "name": "培训与人才发展", "icon": "📚", "description": "培训需求分析、培训计划制定与人才梯队建设。", "sort_order": 5}, {"code": "labor-law", "name": "劳动法与合规", "icon": "⚖️", "description": "劳动合同、工时休假、解除终止与劳动争议处理等劳动法合规要点。", "sort_order": 6}], "chapters": [{"id": 1, "module_code": "recruitment", "title": "第一章 岗位需求分析", "summary": "招聘的起点：明确岗位职责与任职资格，避免凭感觉招人。", "content": "# 岗位需求分析\n\n## 案例引入：林晓的第一份 JD（先思考，再看下文）\n\n莱茵科技 CEO 王总宣布新开「智能手表产品线」，产品总监陈工找到刚入职的 HR 专员林晓：\"帮我招几个能干的人，Q3 要出样机。\"\n\n林晓知道，\"能干\"不是标准。可她手里只有陈工的三句话——\"要能干的人\"\"懂硬件\"\"能扛事\"。\n\n> **思考：如果你是林晓，你会从哪里开始？你会问陈工哪些问题，才能把\"能干的人\"变成一份可执行的招聘标准？**\n>\n> （先自己想想，学完本章再看林晓是怎么做的。）\n\n## 带着问题学\n\n> 本章的知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 为什么说岗位需求分析是招聘的起点？\n> 2. 一份合格的 JD 应该包含哪些要素？\n> 3. 如何把模糊的用人要求变成\"行为化任职资格\"？\n\n---\n\n招聘的第一步不是发广告，而是**搞清楚到底需要一个什么样的人**。岗位需求分析（Job Analysis）决定了后续所有环节的方向。\n\n## 一、为什么需求分析如此重要\n\n- **避免人岗错配**：需求不清，招来的人大概率不合适\n- **提高招聘效率**：标准清晰，简历筛选和面试更有针对性\n- **降低用人风险**：明确任职资格，减少试用期不合格带来的成本\n\n## 二、JD 的构成要素\n\n一份合格的 JD（岗位说明书）通常包含：\n\n| 要素 | 说明 | 示例 |\n|---|---|---|\n| 岗位职责 | 该岗位要完成的核心工作 | 负责月度招聘计划的制定与执行 |\n| 任职资格 | 硬性要求（学历、经验、证书） | 本科及以上，3 年招聘经验 |\n| 能力素质 | 软性要求（沟通、抗压） | 优秀的沟通协调能力 |\n| 汇报关系 | 向谁汇报、带不带人 | 汇报对象：HR 经理 |\n| 关键绩效 | 岗位的核心产出指标 | 每月到岗率 ≥ 90% |\n\n## 三、需求分析的方法\n\n1. **工作分析法**：观察/访谈在岗优秀员工，梳理关键任务\n2. **问卷调研**：向用人部门收集岗位信息\n3. **对标法**：参考同行业同类岗位的任职标准\n\n## 四、常见误区\n\n- ❌ 把 JD 写得\"既要又要\"，要求过高导致无人可招\n- ❌ 用人部门口头描述，不落成书面标准\n- ❌ 任职资格与岗位实际工作脱节（如文员岗要求硕士）\n\n> **小结**：需求分析做扎实，招聘就成功了一半。记住：**先定标准，再找对人**。\n\n---\n\n## 进阶视角：从岗位分析到胜任力模型\n\n- **德斯勒（《人力资源管理》）框架**：岗位分析（Job Analysis）是一切 HR 职能的基石——薪酬定级、绩效指标、培训需求都以它为依据。需求分析不是招聘部的事，而是\"以岗定人\"的专业工程。\n- **诺伊（《人力资源管理：赢得竞争优势》）战略视角**：岗位需求必须**向上对齐组织战略**——同样的\"销售经理\"岗，在进攻型战略与防守型战略下的能力要求完全不同。先问\"这个岗位为哪个战略目标服务\"，再写任职资格。\n- **胜任力模型（Competency Model）**：从\"经验年限\"进阶到\"行为胜任力\"——用可观察的行为描述（如\"能在资源受限时独立推动跨部门协作\"）替代模糊的\"沟通能力强\"。\n\n> **进阶思考**：写 JD 前先问三个问题——① 这个岗位解决什么业务问题？② 优秀者与平庸者的行为差异是什么？③ 未来一年这个岗位的职责会如何演化？\n\n---\n\n## 案例复盘：那份扎实的 JD\n\n林晓没有直接发招聘广告，而是约陈工做了一次**工作分析**：梳理产品线未来一年的目标——Q3 完成样机、Q4 量产；确认两个核心岗位——硬件工程师与产品经理的关键任务；又访谈了公司两位在岗的优秀硬件工程师，提炼出\"能在资源受限时独立推进调试\"这样的**行为化任职资格**。\n\n一周后，林晓交付了一份包含职责、任职资格、关键绩效指标的 JD。陈工看完说：\"原来我要的是这样的人。\"三个月后复盘，正是这份扎实的 JD，让产品线候选人的整体质量明显高于公司以往招聘——**先定标准，再找对人**，林晓的招聘生涯从这份 JD 开始。\n\n> **对照思考**：你开头的方案与林晓的做法差在哪里？\"工作分析\"\"行为化任职资格\"这两个概念，是否正好解释了你和她之间的差距？\n\n---\n\n## 费曼自检\n\n合上本章，尝试**用自己的话**（尽量不用术语）向一位不懂 HR 的朋友解释：\"岗位需求分析到底在分析什么？为什么它决定了招聘的成败？\"\n\n讲不清楚的地方，就是你需要回去重读的地方。\n", "sort_order": 0}, {"id": 2, "module_code": "recruitment", "title": "第二章 结构化面试", "summary": "用统一的题目和标准评估候选人，让面试更客观、更有效。", "content": "# 结构化面试\n\n## 案例引入：被 STAR 追问拦下的人（先思考，再看下文）\n\n莱茵科技硬件工程师岗位进入面试阶段。林晓作为第一轮面试官，遇到一位候选人：聊得特别投缘，自称\"我这个人抗压能力很强\"\"调试经验特别丰富\"。\n\n可当林晓想深入了解他过去的具体做法时，对方的回答开始变得模糊：\"当时情况比较复杂\"\"反正最后搞定了\"。\n\n> **思考：如果你是林晓，你会怎么继续这场面试？你会相信这位\"聊得来\"的候选人，还是需要找到某种更可靠的判断依据？**\n\n## 带着问题学\n\n> 本章的知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 结构化面试与非结构化面试的根本区别是什么？\n> 2. 如何用 STAR 法则追问出候选人的真实行为？\n> 3. 面试官常见的认知偏差有哪些？如何规避？\n\n---\n\n## 一、什么是结构化面试\n\n结构化面试是指**对所有候选人使用相同的题目、相同的评分标准**的面试方法。相比随意发问的非结构化面试，它的信度和效度显著更高，也是企业面试的主流方法。\n\n## 二、核心工具：STAR 法则\n\n行为面试中，用 **STAR** 法则挖掘候选人的真实行为：\n\n| 字母 | 含义 | 追问示例 |\n|---|---|---|\n| **S** | Situation 情境 | \"当时是什么背景？\" |\n| **T** | Task 任务 | \"你的任务/目标是什么？\" |\n| **A** | Action 行动 | \"你具体做了什么？\" |\n| **R** | Result 结果 | \"结果如何？有什么数据？\" |\n\n> 关键技巧：**追问细节**。听到\"我负责沟通协调\"这种概括性回答时，务必追问\"你具体是怎么做的？\"——只有具体行为才能预测未来表现。\n\n## 三、常见题型\n\n- **行为题**：请举例说明你过去如何解决一次冲突\n- **情境题**：如果客户突然取消合作，你会怎么处理\n- **专业题**：如何制定一个月的招聘计划\n\n## 四、面试官的常见偏差与规避\n\n| 偏差 | 表现 | 规避方法 |\n|---|---|---|\n| 首因效应 | 凭第一印象下结论 | 按评分表逐项打分 |\n| 光环效应 | 某一方面优秀就全面认可 | 多维度独立评估 |\n| 近因效应 | 被最后回答影响 | 面试结束当场记录评分 |\n\n> **小结**：结构化面试 = 标准题目 + STAR 追问 + 维度评分。面试官要克制主观判断，让行为证据说话。\n\n---\n\n## 前沿视角：结构化面试的效度研究（数据思维）\n\n- **学术实证（Schmidt & Hunter 元分析）**：结构化面试对工作绩效的预测效度（约 0.5）**显著高于**非结构化面试（约 0.3）。这不是观点之争，而是数据结论——这也是全球标杆企业坚持结构化面试的根本原因。\n- **Google 的实践（《重新定义团队》）**：Google 人才官博克团队用数据验证了面试设计——行为面试题 + 结构化评分，比\"凭感觉聊得好\"的面试有效得多。他们甚至测量了\"面试官人数\"与\"录取质量\"的关系：**4 人面试达到收益平衡点，更多面试官收益递减**。\n- **给我们的启示**：训练自己\"把主观印象翻译成可观察行为证据\"的能力——每一条评分都要能指向候选人在面试中说出的具体行为。\n\n> **进阶思考**：你上一次面试，有多少条评分依据是\"候选人的具体行为\"，而不是\"我的感觉\"？\n\n---\n\n## 案例复盘：数据替团队做了决定\n\n林晓没有凭感觉放水。她为这个岗位设计了统一的**结构化面试**：两道行为题（\"请举例说明你如何解决一次硬件调试瓶颈\"）、两道专业题，所有候选人同一套题。\n\n面对那位\"聊得来\"的候选人，她用 STAR 逐一追问：\"当时的情境是什么？\"\"你的任务是什么？\"\"你具体做了什么？\"——对方的回答始终停留在\"我很强\"的概括层，给不出具体行为细节。林晓在评分表的行为维度记下低分。\n\n第二轮技术面、第三轮交叉面，面试官按统一评分表独立打分。最终结果：那位\"聊得来\"的候选人行为维度普遍低分，止步二轮。**数据替团队做了决定**——不是林晓的喜好，而是结构化评分表的证据。\n\n> **对照思考**：你开头会相信他吗？STAR 追问与统一评分表，是不是就是帮你抵御\"聊得来\"偏差的工具？\n\n---\n\n## 费曼自检\n\n合上本章，用你自己的话向朋友解释：\"为什么同样一场面试，结构化面试比闲聊式面试更能预测一个人的工作表现？\"\n\n如果只能讲出\"因为题目一样\"，说明你还没抓住**行为证据**这个核心——回去重读 STAR 部分。\n", "sort_order": 1}, {"id": 3, "module_code": "recruitment", "title": "第三章 面试评估与录用决策", "summary": "多维度评估候选人，科学决策，让每一次录用都对得起公司。", "content": "# 面试评估与录用决策\n\n## 案例引入：评估会议上的分歧（先思考，再看下文）\n\n莱茵科技产品线招聘进入终审，五位候选人。林晓组织了**评估会议**：HR + 产品总监 + 两位技术面试官。\n\n会上出现分歧：A 候选人专业分全场最高，技术面试官力推；但林晓发现 A 在两次面试中都对产品方向兴趣平平，甚至说过\"先拿 Offer 再考虑\"。而 B 候选人各项均衡，对智能手表场景的理解明显更深。\n\n> **思考：如果你是会议主持人，你会支持 A（专业最强）还是 B（匹配更稳）？你的依据是什么？** 如何让这场会议不变成\"谁嗓门大听谁的\"？\n\n## 带着问题学\n\n> 本章的知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 科学的录用决策应该依据什么，而不是什么？\n> 2. 面试评估通常包含哪些维度？如何分配权重？\n> 3. 背景调查应该在什么时候、对什么人做？\n\n---\n\n面试结束不等于招聘结束——**科学评估**才是录用的关键环节。\n\n## 一、建立评估维度\n\n| 维度 | 考察内容 | 权重建议 |\n|---|---|---|\n| 专业能力 | 岗位所需知识与技能 | 40% |\n| 工作经验 | 相关经历与成果 | 25% |\n| 综合素质 | 沟通、学习、抗压能力 | 20% |\n| 动机价值观 | 稳定性、文化匹配度 | 15% |\n\n## 二、评估工具\n\n1. **面试评分表**：每位面试官按维度独立打分，避免互相影响\n2. **多人面试**：建议 2-3 位面试官（HR + 用人部门 + 交叉面试），汇总意见\n3. **评估会议**：面试后 24 小时内召开，趁记忆新鲜讨论\n\n## 三、录用决策流程\n\n1. **汇总评分**：加权计算各维度得分\n2. **对比候选人**：横向对比，关注差距而非绝对值\n3. **背景调查**：核实关键经历（通常仅对拟录用者进行）\n4. **薪资沟通**：基于岗位薪酬带宽与候选人预期协商\n5. **发放 Offer**：书面 Offer 明确岗位、薪资、入职时间与条款\n\n## 四、常见误区\n\n- ❌ 面试官凭感觉拍板，不做书面评估\n- ❌ 只招\"最优秀\"的，不考虑匹配度与稳定性\n- ❌ 跳过背景调查直接录用\n\n> **小结**：录用决策 = 多维度评分 + 多人共识 + 背景核实。**招对一个人，胜过招十个**。\n\n---\n\n## 实战视角：高人才密度与人才契约\n\n- **奈飞的人才理念（《奈飞文化手册》）**：招聘是**管理者最重要的工作**。奈飞奉行\"高人才密度\"——只留 A 类人才，宁可岗位空着，也不为填坑降低标准。其逻辑是：一个顶级人才的产出可以数倍于平庸者，且会提升周围所有人的标准。\n- **联盟视角（《联盟》霍夫曼）**：把雇佣关系看作**员工与公司之间的联盟**——录用时明确\"任期计划\"（这段合作里，公司要什么、员工要什么），让招聘从\"一次性交易\"变成\"有契约的合作\"。\n- **对录用决策的启示**：① 标准宁可高不可低（人才密度思维）；② 决策时多想\"这个人两年后能否成为团队的中坚\"，而非\"现在能不能顶上来\"；③ 把\"试用期不合格\"当作流程成本而非管理失败。\n\n> **进阶思考**：如果你只能招聘 10 个人，你会招 10 个\"够用\"的人，还是 7 个顶尖的人 + 3 个有潜力的新人？\n\n---\n\n## 案例复盘：对证据的核对，而不是投票\n\n林晓没有让会议变成投票或比嗓门。她带着**评分表**主持会议：每位面试官独立填写了多维度评分（专业能力/经验/综合素质/动机价值观），会议只做一件事——**核对证据**。\n\n\"为什么 A 的动机分低？\"——因为他在两次面试中均未表现出对产品方向的热情，这是可记录的面试证据，不是印象。\"B 的专业分为什么不突出？\"——硬件深度略逊，但足以胜任当前岗位且成长快。\n\n随后，背景调查确认 B 的上段经历与项目成果属实。会议结论：录用 B。三个月后，B 成为产品线硬件组骨干，而林晓在评估表底部写下一行字：**\"录用决策 = 证据 + 共识，而不是感觉。\"**\n\n> **对照思考**：你开头选 A 还是 B？\"多维度评分表 + 证据核对\"这套机制，是否比\"凭感觉拍板\"更让人信服？\n\n---\n\n## 费曼自检\n\n合上本章，向朋友解释：\"为什么录用决策不能由单个人拍板？多面试官评估到底在防什么？\"\n\n如果能讲出\"防主观偏差、靠证据共识\"，你就掌握了本章核心。\n", "sort_order": 2}, {"id": 4, "module_code": "recruitment", "title": "第四章 战略性招聘与人才规划", "summary": "进阶视角（诺伊）：从\"缺人再招\"到战略导向的人才规划。", "content": "# 战略性招聘与人才规划\n\n## 案例引入：年年救火的人才缺口（先思考，再看下文）\n\n一年后，莱茵科技已扩张到 200 人，但每个季度都在上演同样的戏码：业务要人，HR 加班补坑。\n\n林晓统计了一下：从业务提需求到新人到岗平均要 **72 天**；硬件工程师岗位尤其难招；而销售团队总是临时要人、临时招聘。王总在经营会上问她：\"我们是不是永远在缺人？\"\n\n> **思考：如果你是林晓，你会怎么回答王总？仅仅是\"加快招聘\"就能解决吗？你觉得问题出在哪里？**\n\n## 带着问题学\n\n> 本章的知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 战术招聘与战略招聘的本质区别是什么？\n> 2. 人才规划四步法具体怎么做？\n> 3. 如何用数据度量招聘的效率和效果？\n\n---\n\n## 一、从战术招聘到战略招聘\n\n- **战术招聘**：有了空缺才启动，看简历、约面试、补缺口——救火式招聘。\n- **战略招聘（诺伊《人力资源管理：赢得竞争优势》）**：招聘是**组织战略的执行手段**——人才获取能力本身就是竞争优势。优秀企业的人才获取不是\"HR 的事\"，而是业务战略的一部分。\n\n## 二、人才规划四步法\n\n1. **人才盘点**：盘点现有人才的数量、质量与结构（年龄、能力、潜力、梯队）\n2. **供需预测**：预测未来 1~3 年组织扩张/收缩带来的人才需求，与内部供给对比\n3. **差距分析**：识别关键岗位的缺口（数量缺口 + 能力缺口）\n4. **行动计划**：内部培养（继任梯队）与外部获取（招聘）双轮驱动\n\n## 三、招聘渠道策略\n\n| 渠道 | 适用场景 | 特点 |\n|---|---|---|\n| 内部招聘 | 保留与激励、快速上岗 | 成本低、文化契合，但可能引发内部竞争 |\n| 内部推荐 | 中高级岗位 | 质量高、入职快（奈飞等公司内推占比高） |\n| 猎头/人才寻访 | 高管与稀缺人才 | 精准但成本高 |\n| 线上平台/招聘网站 | 批量岗位 | 覆盖面广、需要筛选成本 |\n\n> 渠道策略不是\"哪个便宜用哪个\"，而是**针对岗位层级与稀缺度组合投放**。\n\n## 四、招聘关键度量指标\n\n- **招聘周期（Time to Fill）**：从启动到接受 Offer 的天数\n- **Offer 接受率**：发出的 Offer 中候选人接受的比例\n- **试用期通过率 / 新人绩效**：招聘质量的结果指标\n- **单位招聘成本（Cost per Hire）**\n\n> **小结**：战略招聘 = 人才规划（盘清家底、预测缺口）+ 渠道组合（精准投放）+ 数据度量（持续优化）。HR 要像业务一样管理自己的\"人才供应链\"。\n\n---\n\n## 案例复盘：从\"缺人现招\"到人才规划\n\n林晓没有简单回答\"我们加快招聘\"，而是启动了第一次**人才规划**：\n\n- **盘点**：6 个关键岗位（含产品线技术负责人）的现状与继任情况——发现技术负责人没有后备人选\n- **预测**：明年新品线扩张需要新增 15 人，其中 5 个岗位可以内部晋升\n- **差距分析**：硬件工程师缺口最大；内推渠道贡献了 60% 的优质简历，却被长期忽视\n- **行动计划**：① 关键岗位提前 6 个月启动储备招聘；② 把内推做成制度（推荐奖+透明流程）；③ 每月发布招聘度量看板（周期、接受率、到岗质量）\n\n她把 72 天 vs 行业标杆 45 天的数据摆到王总桌上。半年后，招聘周期缩短到 45 天。**林晓第一次让招聘有了\"供应链\"的样子。**\n\n> **对照思考**：你开头的答案是不是\"加大招聘力度\"？人才规划四步法是否让你看到了\"问题出在供需管理，而不是招聘速度\"？\n\n---\n\n## 费曼自检\n\n合上本章，向朋友解释：\"战略招聘和'缺人再招'到底差在哪？\"试着用\"人才供应链\"这个词讲明白。\n\n如果只能说出\"提前招人\"，说明你还没抓住**规划与数据度量**——回去重读人才规划四步法。\n", "sort_order": 3}, {"id": 5, "module_code": "recruitment", "title": "第五章 雇主品牌与人才契约", "summary": "实战前沿层：高人才密度文化、联盟任期制与数据化招聘（奈飞/联盟/重新定义团队）。", "content": "# 雇主品牌与人才契约\n\n## 案例引入：一张难发的 Offer（先思考，再看下文）\n\n产品线团队基本成型，但硬件负责人岗位悬而未决。候选人何工是业内小有名气的结构设计专家，同时收到了另一家公司的 offer——对方薪水高出 **15%**。\n\n何工对莱茵科技的产品方向感兴趣，但他直接问林晓：\"你们凭什么叫我来？那边的钱更多，我为什么要冒这个险？\"\n\n> **思考：如果你是林晓，你会怎么回答？除了加钱，莱茵科技还能拿出什么\"牌\"来打动何工？**\n\n## 带着问题学\n\n> 本章的知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 什么是员工价值主张（EVP）？它在招聘中起什么作用？\n> 2. \"高人才密度\"理念对招聘标准有什么启示？\n> 3. \"任期制\"如何改变招聘沟通的方式？\n\n---\n\n## 一、雇主品牌：候选人为什么选择你\n\n**员工价值主张（EVP，Employee Value Proposition）**：公司向员工提供的独特价值——薪酬、发展、文化、使命、工作方式的总和。雇主品牌就是 EVP 的外部传播：候选人选择公司，本质是在\"买\"你的价值主张。\n\n## 二、奈飞式人才理念：高人才密度\n\n《奈飞文化手册》的核心主张：\n\n- **高人才密度**：团队里 A 类人才越多，整体标准越高；平庸者会拉低所有人的产出与标准\n- **只留 A 类**：奈飞的管理者被要求像\"离职面谈\"一样坦诚地评估团队成员，不合适的成员尽早安排\n- **坦诚文化**：直接反馈（反馈给同事而非背后议论）是团队高效的基石\n- **对招聘的启示**：**宁可慢一点、贵一点，也要招对的人**——招聘标准是人才密度的入口\n\n## 三、联盟与任期制：新的人才契约\n\n《联盟》（霍夫曼）重新定义了雇佣关系：\n\n- 员工与公司不是\"终身雇佣\"或\"随时走人\"的两极，而是**互为投资者的联盟**\n- **任期计划（Tour of Duty）**：录用时明确\"本轮任期\"——公司给员工什么发展机会，员工为公司完成什么使命\n- 招聘时沟通任期计划，能让候选人更清楚\"这段关系里彼此期待什么\"，降低错配\n\n## 四、数据驱动的招聘决策\n\n《重新定义团队》（Google）的核心经验：\n\n- 用**数据验证招聘方法**：结构化面试、行为题、多面试官评分的预测效度都有研究支撑\n- 招聘决策要**可度量、可复盘**：记录面试评分与后续绩效，持续校准面试标准\n- 避免\"光环式拍板\"：让数据说话，而不是让最强势的面试官说话\n\n> **小结**：优秀招聘的终点不只是\"招到人\"，而是**为组织注入人才密度**。用 EVP 吸引对的人，用任期制管理期望，用数据持续校准标准。\n\n---\n\n## 案例复盘：一张\"看得见下一步\"的 Offer\n\n林晓没有盲目加薪，而是把莱茵科技的 **EVP** 讲清楚：① 智能手表是公司战略级产品线，何工将直接带队，而非在大厂做一个模块；② 团队\"高人才密度\"——现有核心成员个个能打，何工来了是和高手共事；③ 一份**任期计划**：本轮任期，公司支持他完成结构设计的专利布局，并给出硬件负责人培养路径。\n\n何工问：\"你们怎么保证这些承诺？\"林晓拿出书面任期计划。最终何工选择了莱茵科技。入职那天他说：\"我不是被 15% 的差价吸引来的，是被一个**看得见下一步**的契约吸引来的。\"\n\n> **对照思考**：你开头想出的\"牌\"里，有没有\"价值主张\"和\"任期计划\"？当薪水不是唯一筹码时，雇主品牌就是决定性变量。\n\n---\n\n## 费曼自检\n\n合上本章，向朋友解释：\"为什么有的公司薪水不是最高，却能吸引到最好的人？\"用 EVP 和任期制两个词讲清楚。\n\n如果你能讲出\"候选人买的不是薪水，而是价值主张与看得见的成长\"，你就真正理解了雇主品牌。\n", "sort_order": 4}, {"id": 12, "module_code": "labor-law", "title": "第一章 劳动合同的订立与试用期", "summary": "书面合同何时签、合同必备哪些条款、试用期如何约定——守住入职第一道合规关。", "content": "# 第一章 劳动合同的订立与试用期\n\n## 案例引入：翻不完的“合同欠账”（先思考，再看下文）\n\n莱茵科技一年内从 80 人扩张到 300 人。招聘团队拼命赶进度，入职流程却跟不上：不少新员工入职一两个月了，合同还在“流程里”；产品总监陈工为了让硬件团队尽快到岗，口头承诺“先干着，试用期三个月，不合适随时走人”；还有一位员工签的是工资栏空白的“空白合同”。\n\n林晓在做人员盘点时吓了一跳：有三位员工的“试用期”已经过了 7 个月还在试用状态，一位员工入职满一年了连书面合同都没见过。她把情况汇报给资深 HR 导师赵姐，赵姐说：“这些不是流程问题，是合规风险。咱们先从劳动合同的订立和试用期开始体检吧。”\n\n> **思考：如果你是林晓，你会怎么向王总说明这些问题的严重性？“试用期三个月随时走人”这样的口头约定，法律上算数吗？**\n>\n> （先自己想想，学完本章再看林晓是怎么做的。）\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 法律对书面劳动合同的订立时间有什么硬性要求？逾期不签的后果是什么？\n> 2. 试用期可以随便约定吗？试用期长短、工资和解除各有什么规则？\n> 3. 一份合法有效的劳动合同，必须包含哪些条款？\n\n---\n\n## 一、劳动关系与书面劳动合同\n\n《劳动合同法》规定，**用人单位自用工之日起即与劳动者建立劳动关系**（第七条）。也就是说，从员工第一天上班开始，不管有没有签合同，劳动关系就已经成立。但订立书面合同是法定义务：\n\n- **订立时限**：应当自用工之日起 **一个月内** 订立书面劳动合同（第十条）。\n- **逾期后果**：\n  - 超过一个月不满一年未订立的，应当每月向劳动者支付 **二倍工资**（第八十二条）；\n  - 满一年仍未订立的，视为双方已订立 **无固定期限劳动合同**，并应当立即补订书面合同（第十四条第三款）。\n\n书面合同的意义不只是“应付检查”——它是双方权利义务的书面证据，是劳动争议发生时最重要的依据。没有合同，员工主张二倍工资、加班费、经济补偿时，公司举证会非常被动。\n\n## 二、劳动合同的必备条款\n\n《劳动合同法》第十七条规定，劳动合同应当具备以下条款：\n\n| 类别 | 条款 |\n|---|---|\n| 主体信息 | 用人单位名称、住所和法定代表人或主要负责人；劳动者姓名、住址和居民身份证号码 |\n| 期限 | 劳动合同期限 |\n| 工作内容 | 工作内容和工作地点 |\n| 工时休假 | 工作时间和休息休假 |\n| 劳动报酬 | 劳动报酬 |\n| 社会保险 | 社会保险 |\n| 劳动保护 | 劳动保护、劳动条件和职业危害防护 |\n| 兜底条款 | 法律、法规规定应当纳入劳动合同的其他事项 |\n\n除必备条款外，双方还可以**约定**试用期、培训、保守秘密、补充保险和福利待遇等事项。注意：工资、岗位、工作地点这些关键信息一旦空白，就等于把解释权交给了对方，是典型的高风险操作。\n\n## 三、试用期的法定规则\n\n试用期不是“想定多长就多长”，而是与劳动合同期限严格挂钩（第十九条）：\n\n| 劳动合同期限 | 试用期上限 |\n|---|---|\n| 三个月以上不满一年 | 不得超过 1 个月 |\n| 一年以上不满三年 | 不得超过 2 个月 |\n| 三年以上固定期限或无固定期限 | 不得超过 6 个月 |\n| 不满三个月或以完成一定工作任务为期限 | 不得约定试用期 |\n\n- **次数**：同一用人单位与同一劳动者**只能约定一次**试用期，不能“延长”或“再来一次”；\n- **包含关系**：试用期包含在劳动合同期限内，单独约定或单独计算均不合法；\n- **工资**：试用期工资不得低于本单位相同岗位最低档工资或劳动合同约定工资的 **80%**，且不得低于当地最低工资标准（第二十条）；\n- **解除**：试用期内被证明不符合录用条件的，用人单位可以解除劳动合同且无需支付经济补偿（第三十九条第一项），但前提是**录用条件事先明确、考核有证据**——“觉得不行”不等于法律意义上的“不符合录用条件”。\n\n## 四、实务要点：把“补签”变成“该签就签”\n\n1. 把签订书面合同嵌入入职流程第一周，设立“合同签订率”监控台账；\n2. 录用条件写进合同或入职告知书，由员工签字确认；\n3. 试用期考核留痕：考核表、工作记录、面谈纪要，缺一不可。\n\n> **小结**：一个月的签约时限、随合同期限递增的试用期上限、一次性的试用期次数——这三条红线，是本章最需要记住的合规底线。\n\n---\n\n## 进阶视角：合规体检的视角看“合同欠账”\n\n- **德斯勒（《人力资源管理》）劳动关系框架**：劳动合同是雇佣关系的“契约载体”。德斯勒把劳动关系管理视为组织与员工之间权利与义务的制度化安排——合同签得越规范，后续的绩效、薪酬、员工关系管理就越有据可依。\n- **法条视角（《劳动合同法》）**：双倍工资条款（第八十二条）与无固定期限劳动合同制度（第十四条）是一套“组合拳”，立法目的是倒逼企业主动签约，而不是给员工“送钱”——企业真正该做的，是把签约做成日常流程而非事后补救。\n- **实务陷阱提醒**：口头约定、空白合同、试用期口头延长，是中小型企业最常见的三类高频败诉点。一旦发生争议，“公司说的”永远不如“白纸黑字”。\n\n> **进阶思考**：如果一边在追着补签、一边仍不断有新员工逾期未签，最根本的解决方式是什么——是继续补签，还是重构入职流程？\n\n---\n\n## 案例复盘：先把流程立起来\n\n林晓没有急着挨个“逼签”，而是先给王总算了一笔账：按现有逾期人数，公司一年最多可能多付出相当于十几个人月工资的二倍工资成本，还有被认定无固定期限劳动合同的风险。王总当场拍板：合同签订进流程、上系统。\n\n随后林晓做了三件事：一是把“入职一个月内签合同”写进新员工入职 checklist，由招聘专员跟进闭环；二是请法务起草统一合同模板，把录用条件、岗位职责写清楚，堵住空白合同；三是按合同期限重新核定每位员工的试用期，把超期试用、口头延长的做法全部纠正，并补签书面确认。\n\n三个月后的复盘会上，赵姐看了台账说：“合同签订率 100%，试用期全部合规——这一关，过了。”\n\n> **对照思考**：你开头打算怎么处理“试用期三个月随时走人”？读完本章你会发现，正确的做法不是去争论“能不能随时走”，而是先把试用期长短、工资、录用条件和解除证据这些法定要素全部落实到位。\n\n---\n\n## 费曼自检\n\n合上本章，用自己的话向一位刚创业的朋友解释：“新公司招人，合同该什么时候签？试用期最长能定几个月？没签合同会有什么后果？”\n\n讲不清楚的地方，就是你需要回去重读的地方。\n", "sort_order": 0}, {"id": 13, "module_code": "labor-law", "title": "第二章 工时、休假与加班管理", "summary": "标准工时与加班上限、三档加班费、带薪年休假——让加班有据可依、休假有名有实。", "content": "# 第二章 工时、休假与加班管理\n\n## 案例引入：加不完的班（先思考，再看下文）\n\n智能手表样机进入冲刺阶段，产品总监陈工在项目群发话：“这个月全员 996，谁掉链子谁负责。”销售总监刘姐也不甘示弱，让销售团队周末拉业绩。一时间公司晚上灯火通明，可考勤系统里却查不到任何加班记录——大家“凭自觉”打卡，加班申请制度根本没建立。\n\n有位研发工程师私下跟林晓吐槽：“加班快俩月了，一分钱加班费没有，年假也没人提过怎么休。”刘姐却觉得：“创业公司哪有不加班的？给年轻人机会就不错了。”\n\n> **思考：如果你是林晓，你知道“996”在法律上意味着什么吗？公司不发加班费、不给年假，会埋下什么隐患？**\n>\n> （先自己想想，学完本章再看林晓是怎么做的。）\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 标准工时制度下，工作时间和加班有哪些法定上限？\n> 2. 不同时段的加班，加班费分别按什么标准计算？休息日加班能否用补休替代？\n> 3. 年休假怎么算？不休年假要不要给钱？\n\n---\n\n## 一、工时制度与加班的法律上限\n\n我国法定的**标准工时**制度：每日工作不超过 **8 小时**，每周不超过 **40 小时**（《劳动法》第三十六条）。用人单位应当保证劳动者每周至少休息一日。\n\n加班受到严格限制（《劳动法》第四十一条）：经与工会和劳动者协商后，**一般每日不得超过 1 小时**；因特殊原因需要延长的，在保障劳动者身体健康的条件下每日不得超过 3 小时，且 **每月不得超过 36 小时**。\n\n除标准工时外，还有综合计算工时制和不定时工作制，适用于特定岗位（如连续作业、外勤销售等），但必须**经劳动行政部门审批**，不能由企业自行宣布。\n\n## 二、加班费的计算标准\n\n《劳动法》第四十四条对加班费作了三档规定：\n\n| 加班情形 | 支付标准 |\n|---|---|\n| 工作日延长工作时间 | 不低于工资的 **150%** |\n| 休息日（周末）安排工作且不能安排补休 | 不低于工资的 **200%** |\n| 法定休假日（如春节、国庆）安排工作 | 不低于工资的 **300%** |\n\n要点辨析：\n\n- **休息日加班可以补休替代**：安排了补休的，不再支付 200% 加班费；\n- **法定节假日加班不能以补休替代**：必须支付 300%，因为法定节假日的休假权利是法定的，调休无法弥补；\n- **加班费计算基数**：一般按劳动合同约定的工资标准确定，实务中需与当地口径一致并写入规章制度。\n\n## 三、年休假：法定福利，不能“自动蒸发”\n\n依据《职工带薪年休假条例》，职工连续工作满 1 年即可享受带薪年休假，天数按**累计工作年限**确定：\n\n| 累计工作年限 | 年休假天数 |\n|---|---|\n| 满 1 年不满 10 年 | 5 天 |\n| 满 10 年不满 20 年 | 10 天 |\n| 满 20 年 | 15 天 |\n\n- 国家法定休假日、休息日**不计入**年休假假期；\n- 年休假可以在 1 个年度内集中或分段安排，确因工作需要可**跨 1 个年度**安排；\n- **应休未休**的：单位应当按照该职工**日工资收入的 300%** 支付年休假工资报酬（其中 100% 为正常工作期间已付工资，即还需额外补发 200%）。\n\n## 四、实务要点：加班管理要“先有制度，再有记录”\n\n1. **加班审批制**：员工加班须经主管审批，杜绝“隐性加班”；\n2. **考勤留痕**：打卡记录、审批单、工资单上的加班费条目要能互相印证——劳动争议中，考勤记录等由用人单位掌握管理的证据，举证责任在单位；\n3. **额度监控**：每月加班小时数预警，把“月 36 小时”的红线变成管理动作。\n\n> **小结**：标准工时不超时、加班有审批、加班费给到位、年假安排明白——这四件事做到，工时合规就立住了。\n\n---\n\n## 进阶视角：从“管理便利”到“工时合规”\n\n- **德斯勒（《人力资源管理》）视角**：工时与休息是劳动关系的基本内容，也是工作生活质量的一部分。把加班管理做好，不只是规避法律风险，更是对员工健康的投资——过度加班带来的疲惫与流失，最终由企业买单。\n- **诺伊（《人力资源管理：赢得竞争优势》）战略视角**：工时制度必须与业务战略匹配——冲刺期临时加班可以理解，但若“996”成为常态，说明人力规划出了问题。合规的工时管理，本质是**人力配置效率**问题，而不是“能不能扛”的问题。\n- **实务陷阱提醒**：许多企业败诉，不是“没给加班费”，而是“说不清给了没有”——没有审批、没有记录、没有工资条明细，等于把举证主动权拱手让人。\n\n> **进阶思考**：如果你是快速扩张公司的 HR，你会用哪些数据指标来提前预警“加班失控”？\n\n---\n\n## 案例复盘：先立规矩，再谈冲刺\n\n林晓没有直接跟陈工“讲法条”，而是先做了一次合规测算：按现有加班规模，若员工全部主张加班费，公司一年的加班费缺口可能高达数十万元，还不算潜在的仲裁赔偿。她把数据摆到王总桌上，王总才意识到“免费加班”是笔糊涂账。\n\n随后林晓推动了三件事：第一，上线**加班审批流程**，任何加班须主管审批、系统留痕；第二，对已发生的周末加班，与员工协商优先**安排补休**，无法补休的按 200% 补发加班费；第三，制定年休假安排表，把研发团队的休假排进项目节奏。\n\n陈工一开始嫌“流程繁琐”，直到一次项目复盘发现，强制审批后无效加班明显减少、效率反而更高。赵姐点评：“合规不是给业务添堵，是把账算清楚。”\n\n> **对照思考**：如果你是林晓，你会直接拿《劳动法》第四十四条去“教育”陈工，还是先算账、再立规矩？哪种方式更能推动业务管理者配合？\n\n---\n\n## 费曼自检\n\n合上本章，用自己的话向朋友解释：“加班费有哪三档？休息日加班和法定节假日加班，处理方式有什么不一样？年假不休会怎样？”\n\n讲不清楚的地方，就是你需要回去重读的地方。\n", "sort_order": 1}, {"id": 14, "module_code": "labor-law", "title": "第三章 劳动合同解除、终止与经济补偿", "summary": "解除的类型与法定程序、经济补偿计算、劳动争议处理路径——让每一次离职都合法合规。", "content": "# 第三章 劳动合同解除、终止与经济补偿\n\n## 案例引入：被裁员的“老黄牛”（先思考，再看下文）\n\n莱茵科技扩张踩了急刹车：智能手表销量不及预期，CEO 王总在管理会上发话：“成本要降，该清的就清一批。”销售总监刘姐把矛头指向一位司龄 6 年的老销售：“他今年业绩垫底，直接辞退，省得给补偿。”产品总监陈工也想借机“优化”一名正在休产假的研发工程师——“她休假大半年，项目等不起。”\n\n消息传开，一位被口头通知“明天不用来了”的员工直接去了劳动仲裁委。林晓第一次直面劳动争议，心里发慌，找到赵姐：“辞退一个人，到底要走什么程序？赔多少才算数？”\n\n> **思考：如果你是林晓，你知道“不胜任”该怎么合法解除吗？孕期员工能不能辞退？仲裁来了，公司该怎么办？**\n>\n> （先自己想想，学完本章再看林晓是怎么做的。）\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 劳动合同解除有哪些类型？各自需要什么条件和程序？\n> 2. 经济补偿怎么算？什么情况下不用给？\n> 3. 劳动争议处理的法定程序是什么？企业如何举证自保？\n\n---\n\n## 一、解除的四大类型\n\n### 1. 协商解除（第三十六条）\n\n双方协商一致可以解除劳动合同。**由用人单位提出的**，应当支付经济补偿；由劳动者提出的，用人单位无需支付。\n\n### 2. 劳动者单方解除（第三十七、三十八条）\n\n- **预告解除**：劳动者提前 **30 日** 以书面形式通知用人单位即可；试用期内提前 **3 日** 通知即可；\n- **被迫解除**：用人单位未及时足额支付劳动报酬、未依法缴纳社会保险费等，劳动者可以解除合同并**要求经济补偿**（第三十八条）。\n\n### 3. 用人单位过失性辞退（第三十九条）\n\n劳动者存在**过错**（试用期不符合录用条件、严重违反规章制度、严重失职营私舞弊造成重大损害、被依法追究刑事责任等），用人单位可以立即解除，**无需提前通知、无需支付经济补偿**。但“严重违反”必须依据规章制度认定，制度须经民主程序制定并向员工公示。\n\n### 4. 无过失性辞退与经济性裁员（第四十、四十一条）\n\n| 情形 | 要件 | 程序与补偿 |\n|---|---|---|\n| 医疗期满 | 不能从事原工作也不能从事另行安排的工作 | 提前 30 日书面通知或支付代通知金，并支付经济补偿 |\n| 不胜任工作 | 经培训或调整岗位后仍不能胜任 | 提前 30 日书面通知或支付代通知金，并支付经济补偿 |\n| 客观情况重大变化 | 劳动合同无法履行且协商变更不成 | 提前 30 日书面通知或支付代通知金，并支付经济补偿 |\n| 经济性裁员 | 裁减 20 人以上或占职工总数 10% 以上 | 提前 30 日向工会或全体职工说明情况、听取意见，向劳动行政部门报告方案，并支付经济补偿 |\n\n**特别保护（第四十二条）**：从事接触职业病危害作业未进行离岗前检查、患职业病或因工负伤、在医疗期内、**孕期/产期/哺乳期女职工**、连续工作满 15 年且距法定退休年龄不足 5 年等情形，不得依据第四十条、四十一条解除劳动合同。\n\n## 二、经济补偿的计算（“N”怎么算）\n\n《劳动合同法》第四十七条：经济补偿按劳动者在本单位工作的年限，**每满一年支付一个月工资**；六个月以上不满一年的，按一年计算；不满六个月的，支付**半个月工资**。\n\n- **月工资基数**：解除或终止前 12 个月的平均工资（含奖金、津贴、补贴等工资性收入）；\n- **高薪封顶**：月工资高于当地上年度职工月平均工资 **3 倍**的，按 3 倍支付，且年限最高不超过 **12 年**；\n- **违法解除赔偿金**：用人单位违法解除或终止劳动合同的，应当支付**经济补偿标准的二倍**（即 2N，第八十七条）；劳动者要求继续履行的，应当继续履行。\n\n## 三、劳动争议处理：协商→调解→仲裁→诉讼\n\n劳动争议的法定程序（《劳动争议调解仲裁法》）：\n\n1. **协商**：与用人单位协商，或请工会、第三方共同协商解决；\n2. **调解**：向企业劳动争议调解委员会或基层调解组织申请调解；\n3. **仲裁**：向劳动争议仲裁委员会申请仲裁——**仲裁是诉讼的前置程序**，未经仲裁不能直接起诉；仲裁时效为自知道或应当知道权利被侵害之日起 **1 年内**；\n4. **诉讼**：对仲裁裁决不服的，自收到裁决书之日起 **15 日内**向人民法院起诉。\n\n实务中有一句口诀：**“证据为王”**。考勤、工资、加班、解除通知等由用人单位掌握管理的证据，由用人单位承担举证责任；解除、终止决定必须书面送达并留存送达凭证。\n\n## 四、实务要点：把“辞退”做成“合规动作”\n\n1. **先找依据**：解除必须对应法定情形，逐条核验；\n2. **程序到位**：听取工会意见（有工会的）、书面通知、送达凭证、工作交接，一个不能少；\n3. **补偿算清**：经济补偿、代通知金、加班费、未休年假折算，一次性结清并留书面确认。\n\n> **小结**：解除合规 = 法定情形 + 法定程序 + 法定补偿。三缺一，就是违法解除。\n\n---\n\n## 进阶视角：解除管理背后的劳动关系观\n\n- **德斯勒（《人力资源管理》）视角**：德斯勒强调“公平解雇”理念——解雇必须有正当理由、经过正当程序。把解除做成合规动作，本质是尊重员工、维护组织公信力。\n- **尤里奇（《人力资源转型》）视角**：HR 在解除场景中要同时扮演“员工代言人”与“组织管理者”双重角色——既维护公司利益，也保障员工的程序正义。处理得体的离职，是雇主品牌的最后一次亮相。\n- **实务陷阱提醒**：高频败诉点集中在——口头辞退无书面通知、以“不胜任”直接解除未走培训/调岗程序、协商解除后反被主张违法解除、“三期”女职工被裁员。每一条都是本章要避开的坑。\n\n> **进阶思考**：为什么说“口头辞退”是劳动争议第一大雷区？书面通知的意义仅仅是“留证据”吗？\n\n---\n\n## 案例复盘：把“清人”变成“依法办结”\n\n林晓在赵姐的指导下，把王总的“清理一批”翻译成了合规动作。对业绩垫底的老销售，她没有直接辞退，而是：调取绩效记录 → 启动“培训 + 调岗”程序 → 培训后仍不胜任 → 提前 30 日书面通知，依法支付经济补偿和代通知金。对正在休产假的工程师，她直接向王总说明这是法定保护对象，辞退即构成违法解除，公司果断调整方案、保留岗位。\n\n对那位申请仲裁的员工，林晓不再慌张：她整理出书面解除通知、考勤记录、工资明细等证据，主动与员工协商，在仲裁委主持下达成调解，比对方主张的金额少、速度快，也避免了裁决书公开带来的影响。\n\n复盘会上，赵姐对林晓说：“合规解除不是不辞人，而是让每一次‘再见’都有法可依、有据可查。你这一课，学费省了。”\n\n> **对照思考**：你开头认为“业绩垫底就该直接辞退”吗？读完本章你会发现，合法的“不胜任”解除要先培训或调岗、要提前 30 日通知、要给经济补偿——省掉程序的代价，往往是 2N 的赔偿金。\n\n---\n\n## 费曼自检\n\n合上本章，用自己的话向朋友解释：“经济补偿的 N 是怎么算的？什么叫违法解除，要赔多少？员工被辞退不服气，要走过哪几步程序才能告到法院？”\n\n讲不清楚的地方，就是你需要回去重读的地方。\n", "sort_order": 2}, {"id": 18, "module_code": "performance", "title": "第一章 KPI 与 OKR 目标设定", "summary": "掌握 KPI 与 OKR 的区别与适用场景、SMART 目标设定方法，以及目标与战略对齐的机制。", "content": "# 第一章 KPI 与 OKR 目标设定\n\n## 案例引入：王总说“把绩效立起来”（先思考，再看下文）\n\n莱茵科技智能手表产品线团队组建完成——硬件工程师、产品经理、嵌入式软件工程师陆续到岗，公司人数突破 300 人。经营会上，CEO 王总把一份新季度经营目标推到林晓面前：“团队齐了，绩效也得立起来。两周内给我一版方案。”\n\n林晓兴冲冲去找各部门收目标，却碰了一鼻子灰：\n\n销售总监刘姐说：“简单！卖了多少表、回了多少款，直接按销售额考核，谁低谁走人。”\n\n产品总监陈工却拍桌子反对：“手表卖得好不好，得看芯片方案、功耗算法这些要长期打磨的东西。你拿季度销售额考核工程师，他们只会去改几个花哨的界面，谁还碰底层创新？”\n\n更让林晓头疼的是，两边拿上来的“目标”五花八门：有写“提升产品质量”的，有写“尽快提升用户满意度”的，还有写“把创新做起来”的——没有一个说得清什么叫“做到”。\n\n> **思考：如果你是林晓，你如何说服两位总监放下分歧？KPI 和 OKR 到底有什么区别？怎么把“提升产品质量”变成一句能验收的话？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. KPI 与 OKR 的本质区别是什么？什么岗位该用哪一种？\n> 2. 怎样用 SMART 原则把模糊的目标变成可衡量、可验收的目标？\n> 3. 如何让部门目标与公司战略对齐，避免“指标打架”？\n\n---\n\n## 一、目标设定：绩效管理的起点\n\n德斯勒在《人力资源管理》中把绩效管理定义为“确保员工的活动与产出和组织目标保持一致的过程”。它不是年底打分那一个瞬间，而是一条完整的链：**目标设定 → 过程辅导 → 绩效评估 → 反馈与改进**，目标设定是链条的第一环——目标错了，后面全是白忙。\n\n目标管理的源头可以追溯到德鲁克。他在《管理的实践》中提出**目标管理（MBO）**：管理者与员工共同设定目标，用“自我控制”取代“外部控制”。德鲁克有一个著名判断：“不是有了工作才有目标，而是有了目标才能确定每个人的工作。”这一思想后来演化出两大工具——KPI 与 OKR。\n\n### KPI：关键绩效指标\n\nKPI（Key Performance Indicator）是把组织战略层层分解为可量化的关键指标。经典分解框架是卡普兰与诺顿的**平衡计分卡**，从四个维度展开：财务、客户、内部流程、学习与成长。比如莱茵科技的战略是“手表卖得好、口碑好”，分解下来就是：销售额、回款率（财务）；复购率、NPS（客户）；良品率、交付周期（内部流程）；关键岗位培训覆盖率（学习与成长）。\n\nKPI 的特点：自上而下分解、承诺制（定了就要达成）、与考核薪酬挂钩、结果导向。\n\n### OKR：目标与关键结果\n\nOKR（Objectives and Key Results）起源于英特尔，由约翰·杜尔带到谷歌并广为人知。它由两部分组成：\n\n- **O（Objective）**：定性、鼓舞人心的方向，回答“我们要去哪里”；\n- **KR（Key Results）**：2~4 个可量化的关键结果，回答“怎么证明我们到了”。\n\n比如产品团队的 O 是“让智能手表成为用户离不开的随身健康伙伴”，KR 可以是“心率算法静息误差 ≤ 3 次/分”“典型场景续航从 3 天提升到 5 天”。\n\nOKR 的关键特征是**挑战性**：理想状态下 KR 达成率在 70% 左右，全部达成反而说明目标定保守了。\n\n### KPI 与 OKR 的核心区别\n\n| 维度 | KPI | OKR |\n|---|---|---|\n| 目的 | 衡量与考核，保底线 | 对齐与牵引，拉增长 |\n| 目标来源 | 战略自上而下分解 | 上下共创、对齐 |\n| 目标性质 | 承诺制，必须达成 | 挑战制，允许不完成 |\n| 与薪酬关系 | 通常直接挂钩 | 一般不直接挂钩 |\n| 适用岗位 | 销售、生产等结果明确、重复性工作 | 研发、产品等创新探索性工作 |\n| 回顾频率 | 月度/季度 | 季度设定，周/双周回顾 |\n\n### SMART 原则：把“模糊”变成“可验收”\n\n无论 KPI 还是 OKR，目标本身都要经得起 SMART 检验：\n\n| 字母 | 含义 | 反面例子 |\n|---|---|---|\n| S | 具体（Specific） | “提升产品质量” |\n| M | 可衡量（Measurable） | “尽快提升” |\n| A | 可实现（Achievable） | “三个月把续航做到 30 天”（明显不现实） |\n| R | 相关（Relevant） | 与产品线战略无关的指标 |\n| T | 有时限（Time-bound） | “有一天会做到” |\n\n改写示范：“提升产品质量”→“通过引入来料抽检与整机老化测试，在 9 月底前将手表良品率从 92% 提升到 97%”。\n\n## 进阶视角：别让工具用反了\n\n**第一，KPI 与 OKR 不是二选一，而是组合拳。** 成熟企业常见做法是“KPI 保底线、OKR 拉增长”：销售用 KPI 守住回款与铺货，产品用 OKR 挑战创新高地，两条线各自清晰。\n\n**第二，警惕把 OKR 用成 KPI。** 一旦把 OKR 达成率与奖金硬挂钩，员工就会“理性地”把目标越定越低，挑战精神荡然无存。这正是《绩效使能》的核心警示：传统绩效管理假设员工需要外部奖惩驱动，而绩效使能主张通过目标本身激发**内在动机**——自主、胜任与联结。\n\n**第三，目标不是越多越好。** 3~5 个关键目标即可，什么都抓等于什么都没抓；目标还应随战略动态调整。\n\n\n## 进阶视角：绩效认同——员工思维如何落地（杨国安）\n\n很多绩效体系失败，不是设计不好，而是**员工不认同**。**杨国安（《组织能力的杨三角》）**提醒我们：绩效管理要同时打通三条腿——目标体系（治理）、能力准备（能力）、**认同与意愿（思维）**。员工若把绩效当成\"扣钱的工具\"，再科学的 KPI 也会被消极执行。\n\n落地认同的三步：① **目标共担**：目标不是 HR 发下去，而是管理者和员工一起定（承接德鲁克 MBO 精神）；② **过程透明**：评分规则、数据来源事先讲清楚，让员工知道\"怎么算的\"；③ **结果应用一致**：绩效结果与激励、晋升的联动规则公开一致，员工才会相信\"努力有回报\"。记住：**绩效管理管的不只是结果，更是人心**。\n\n<!-- 书单补强 -->\n## 案例复盘：林晓的两条线\n\n林晓没有在“谁对谁错”上纠缠，而是先请王总在战略解码会上把产品线战略讲透——“第一款产品要跑通：量不冒进，但体验要立得住”。有了这个锚点，林晓的方案清晰起来：\n\n- **销售团队用 KPI**：渠道铺货数、回款率、月度销售额，承诺制，与奖金挂钩；\n- **产品团队用 OKR**：O 是“打造体验领先的首款智能手表”，KR 为功耗、心率算法准确率、NPS 等可量化里程碑，季度对齐、双周回顾，不与奖金直接强挂钩；\n- **统一用 SMART 改写目标**：把“提升产品质量”之类口号全部改写成带数字、带时限的表述。\n\n两个月后，两个团队不再互相拆台：销售守住基本盘，产品敢于挑战大胆目标。王总在月度经营会上点名表扬：“这才叫把绩效立起来了。”\n\n> **对照思考：如果你是林晓，你会先说服刘姐还是陈工？你原来的方案与林晓的差别在哪里？**\n\n## 费曼自检\n\n合上本章，用 3 分钟向一位朋友讲清楚三件事：KPI 和 OKR 各自是什么、区别在哪；什么岗位适合 OKR；SMART 五个字母分别代表什么。讲不清楚的地方，就是你需要重读的地方。", "sort_order": 0}, {"id": 19, "module_code": "performance", "title": "第二章 绩效评估流程设计", "summary": "学会设计评估周期与评估主体、理解 360 度评估的适用与陷阱，掌握评分校准与绩效等级方法。", "content": "# 第二章 绩效评估流程设计\n\n## 案例引入：分数是怎么“评”出来的（先思考，再看下文）\n\n目标体系上线两个月后，第一个季度评估来了。林晓把评估表发下去，问题接踵而至：\n\n销售总监刘姐五分钟填完全部表格：“我闭着眼都知道谁干得好，还用得着打分？”——可她给手下人的分数从没低于 85 分。\n\n产品总监陈工对着表直皱眉：“工程师的活怎么量化？功耗降低了 20%，这算几分？”最后他给团队平均分 75 分。\n\n两个部门的分数一对比，林晓发现问题大了：**同样水平的两个人，在销售部拿 92 分，在产品部只有 74 分。**有员工在匿名反馈里写道：“干得多的不如会沟通的，老好人分最高。”更麻烦的是，有人提议“干脆全公司强制末位淘汰”，产品团队当场炸锅。\n\n林晓被问住了：到底谁来评？多久评一次？要不要让同事、下属都来打分？分数出来之后怎么保证公平？\n\n> **思考：如果你是林晓，你会怎么设计评估流程，让评分既不“拍脑袋”又不打击创新？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 评估周期与评估主体应该如何选择？\n> 2. 360 度评估是什么？什么时候该用、什么时候要慎用？\n> 3. 评分校准和绩效等级如何让跨部门评分“一把尺子量到底”？\n\n---\n\n## 一、绩效评估：让“好不好”有据可依\n\n德斯勒对绩效评估的定义是：**评估员工当前与过去的绩效水平，并与既定标准进行比较的系统化过程**。注意关键词是“与标准比较”——没有标准就没有评估，只有印象。\n\n### 评估周期怎么定\n\n| 周期 | 适用场景 | 注意点 |\n|---|---|---|\n| 年度 | 战略总结、晋升调薪决策 | 反馈太迟，易受近因效应影响 |\n| 半年度 | 平衡反馈及时性与管理成本 | 常见折中选择 |\n| 季度/月度 | 销售等结果周期短的岗位 | 成本高，需防“考核疲劳” |\n\n趋势是“短周期回顾 + 长周期综合”：季度回顾聚焦改进，年度综合用于晋升、调薪与人才盘点。\n\n### 谁来评：评估主体的选择\n\n评估主体应服务于评估目的：\n\n- **直接上级**：最了解下属绩效，是评估主体（通常占最高权重）；\n- **员工自评**：让员工回顾与反思，面谈时作为对照；\n- **同事**：了解协作表现，但怕得罪人、易失真；\n- **下属/客户**：多用于管理岗位或服务岗位。\n\n### 360 度评估：多源反馈\n\n**360 度评估**指由上级、同事、下属、客户（外部）与自评等多个来源收集反馈的评估方式。它的价值在于避免单一视角的盲区，尤其适合**发展目的**——帮助管理者认识领导力盲区，用于培训与人才盘点。\n\n但它有三个必须警惕的陷阱：其一，人际关系会污染评价；其二，成本高、耗时长；其三，**若直接与薪酬、晋升强挂钩，反馈会迅速失真**。所以实践中常见做法是：360 反馈用于发展，与薪酬脱钩。\n\n### 评分者误差：分数的系统性偏差\n\n即使有标准，评分者仍会犯错，常见有四类：**晕轮效应**（一个优点掩盖全部）、**近因效应**（只记得最近的表现）、**居中趋势**（大家都打中间分）、**过宽/过严倾向**（刘姐式好人分 vs 陈工式严苛分）。消除这些偏差，单靠“要求客观”没用，要靠流程。\n\n### 评分校准：让不同部门“一把尺子”\n\n**评分校准会（Calibration Meeting）**是解决跨部门标准不一致的关键机制：各部门负责人与 HR 坐在一起，逐项讨论评分依据、统一各等级的标准与比例上限，把“刘姐的 92 分”和“陈工的 74 分”拉回同一把尺子。校准会通常与**绩效等级**配套使用，例如 A（超出预期，≤15%）、B（达到预期）、C（部分未达预期）、D（严重未达预期），每个等级配明确的行为与结果描述。\n\n### 要不要强制分布\n\n**强制分布法**（如 GE 的活力曲线 20-70-10）要求按比例评定等级。它解决了“大家全是好人”的问题，但也有代价：微软曾因强制排序引发内部恶性竞争而废止。中小公司更稳妥的做法是“设定 A 级比例上限 + 校准会统一标准”，既保留区分度，又不搞一刀切淘汰。\n\n## 进阶视角：从“年度审判”到“持续反馈”\n\n传统年度评估越来越被诟病：一次评估改变不了什么，员工在评估前突击表现、评估后原形毕露。前沿实践是**持续绩效管理**：Adobe 用 Check-in 取代年度评估，谷歌靠持续的经理一对一反馈驱动改进，《绩效使能》将其概括为“反馈日常化、评估轻量化”。\n\n评估结果还应进入**人才盘点**：把“绩效”与“潜力”两个维度组合成九宫格，高绩效高潜力的进入继任梯队，高绩效低潜力的留在现岗深耕——评估不再只是打分，而是人才决策的输入。\n\n## 案例复盘：林晓的“三件套”\n\n林晓把方案交给导师赵姐把关后，定了三件事：\n\n**第一，明确主体与周期。** 直接上级评估为主（权重 70%），员工自评为辅（30%）；季度回顾 + 年度综合评估；销售岗月度看结果数据、季度综合评级。\n\n**第二，引入校准会。** 季度末，刘姐、陈工和各部门负责人带着评分依据坐到一起，逐条说明“为什么给这个分”，统一 A 级比例上限 15%。刘姐被问到“92 分对应的关键事件是什么”时答不上来，只好回去补事实。\n\n**第三，重新定义等级。** A/B/C/D 各配行为描述：A 是“显著超出目标并有可验证的成果”，C 是“部分未达且原因在自身”，避免感觉打分。\n\n两个季度后，跨部门打分偏差明显缩小，匿名反馈里“不公平”的抱怨大幅下降。陈工也接受了：“至少现在知道 74 分是怎么来的。”\n\n> **对照思考：如果你是林晓，你敢让刘姐和陈工坐在一起对质评分吗？你的方案里，谁来保证公平？**\n\n## 费曼自检\n\n合上本章，向朋友解释：为什么“直接上级打分”还不够？360 度评估适合用来定奖金吗？校准会到底解决了什么问题？能用莱茵科技的例子讲清楚，你就掌握了本章核心。", "sort_order": 1}, {"id": 20, "module_code": "performance", "title": "第三章 绩效面谈与反馈改进", "summary": "掌握绩效面谈的流程与技巧、STAR 反馈法，以及绩效改进计划（PIP）与 GROW 辅导模型。", "content": "# 第三章 绩效面谈与反馈改进\n\n## 案例引入：分数公布之后（先思考，再看下文）\n\n评估结果终于出来了。林晓还没来得及松口气，问题像雪崩一样压过来：\n\n销售总监刘姐图省事，把团队评估结果直接群发到工作群——一名业绩靠后的老销售当场在群里发火：“我一整年跑烂三双鞋，你告诉我末位？这公司没良心！”群里瞬间刷屏。\n\n产品总监陈工倒是约谈了工程师，可每次谈话都不超过五分钟：“最近表现一般，继续加油。”被谈的工程师一脸茫然：“‘一般’是什么意思？我到底哪里不行？”\n\n最让林晓头疼的是硬件工程师小周——他把评估结果摔在林晓桌上：“功耗方案是我通的宵，续航翻倍是我做的，凭什么给我 C？这评分我不认！”\n\n王总把林晓叫到办公室：“评估做完就算完了吗？分数后面怎么让员工服气、能力提升，这才是绩效的真本事。”\n\n> **思考：如果你是林晓，你会怎么组织这场“分数之后”的沟通？面谈该说什么、怎么说，才能既留住人心又推动改进？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 一场合格的绩效面谈，事前、事中、事后分别该做什么？\n> 2. STAR 反馈法如何让批评“具体”而不“伤人”？\n> 3. 绩效改进计划（PIP）和日常辅导如何把“差评”变成“进步”？\n\n---\n\n## 一、绩效面谈：评估的最后一公里\n\n德斯勒把绩效面谈（Appraisal Interview）定义为**评估者与被评估者就评估结果进行的正式沟通**。没有面谈的评估只是一张纸——员工不知道分数怎么来、下一步怎么办，评估就失去了改进意义。\n\n### 面谈三阶段\n\n| 阶段 | 关键动作 |\n|---|---|\n| 面谈前 | 收集事实与关键事件、提前通知、选择安静环境、准备改进方向 |\n| 面谈中 | 先肯定后改进、对事不对人、多听员工说、共同制定计划 |\n| 面谈后 | 形成书面记录、双方确认、按期跟进辅导 |\n\n面谈中最常见的四个坑：**秋后算账**（只谈过去不谈未来）、**人身攻击**（“你就是懒”）、**一言堂**（员工全程无发言权）、**无下文**（谈完就完，没有改进计划）。\n\n### STAR 反馈：让批评具体而不伤人\n\n批评最忌讳空泛。**STAR 反馈法**用四个要素描述具体行为：\n\n- **S（Situation）**：当时的情境；\n- **T（Task）**：承担的任务或目标；\n- **A（Action）**：实际采取的行为；\n- **R（Result）**：行为带来的结果。\n\n对比两种说法：\n\n- ❌ “你最近工作态度有问题。”（空泛、像人身攻击）\n- ✅ “上周三新品压力测试中，你未按流程复测电池满充场景，导致异常在发布前未被发现、返工两天。我们一起看看怎么避免。”\n\nSTAR 的关键是**只说事实与影响，不贴标签**——批评行为，不否定人。\n\n### 处理员工的抵触情绪\n\n评估结果不如预期时，员工可能否认、争辩、沉默或情绪化。管理者的应对不是压服，而是：用记录的事实说话、允许员工表达、聚焦“未来怎么办”。林晓面对小周的摔桌子，正确的姿势是“先接住情绪，再讲事实，最后谈改进”。\n\n## 二、绩效改进计划（PIP）与日常辅导\n\n**绩效改进计划（PIP，Performance Improvement Plan）**是给未达预期员工的结构化改进方案，通常包含四要素：\n\n1. **明确差距**：列出未达标的具体指标与事实依据；\n2. **改进目标与时间表**：如 90 天内达成什么、分几个里程碑；\n3. **资源与支持**：培训、导师、工具、工作再分配；\n4. **定期跟进评估**：每周/双周回顾，记录改进证据。\n\nPIP 有双重价值：对员工，它是“再给一次机会”的真诚帮助；对组织，它是合规的程序依据——若员工在充分支持下仍无改进，后续调岗或解除劳动合同才有据可依（将衔接劳动法与合规模块）。\n\n**日常辅导（Coaching）**则把改进融入平时，经典工具是 **GROW 模型**：\n\n| 步骤 | 含义 | 提问示例 |\n|---|---|---|\n| G | Goal 目标 | “你希望 90 天后达到什么状态？” |\n| R | Reality 现状 | “现在离目标差在哪里？” |\n| O | Options 方案 | “还有哪些办法可以试？” |\n| W | Will 行动意愿 | “你决定先做哪一件？什么时候开始？” |\n\nGROW 的精髓是**让员工自己找到答案**，管理者只负责提问与支持，而非下达命令。\n\n## 进阶视角：把反馈变成组织文化\n\n《奈飞文化手册》把坦诚视为文化的基石：反馈不是年终才发生的仪式，而是随时随地、双向流动的日常——“反馈是礼物”。谷歌的研究同样发现，高效经理的共同习惯是高频一对一沟通与具体及时的反馈。\n\n《绩效使能》更进一步：绩效管理的终点不是分出高低，而是**激发人的成长**。当评估、面谈、PIP 全部指向“帮员工变得更好”，绩效就从控制工具升级为发展引擎。\n\n## 案例复盘：林晓的“三步棋”\n\n林晓没有逃避这场混乱，她做了三件事：\n\n**第一，堵住伤害性沟通。** 她第一时间请刘姐撤回群发消息，逐个安排一对一保密面谈，并在管理层例会上立规矩：评估结果只允许一对一沟通。\n\n**第二，培训 STAR。** 她拉着赵姐给全体管理者开了一场 STAR 反馈工作坊：每人用真实案例练习“情境—任务—行为—结果”四步表述。陈工练完感慨：“原来‘表现一般’后面还有这么多话要说。”\n\n**第三，接住硬钉子、给改进留门。** 面对小周，林晓没有讲道理，而是调出功耗方案的评审记录，逐条对照 C 级标准解释扣分依据——小周承认“续航翻倍”属实，但“方案评审迟交两周”也属实。双方对齐改进点；随后她为业绩靠后的老销售制定 90 天 PIP：明确目标、安排产品培训、每周五复盘。\n\n一个季度后，小周的改进目标全部达成，被评为 B+；老销售在 PIP 支持下业绩回升；只有一位连续两个周期无改进的员工，在走完程序后转入协商转岗。\n\n> **对照思考：如果是你，能接住小周的“摔桌子”吗？你会在面谈前准备哪些事实？**\n\n## 费曼自检\n\n合上本章，用 STAR 句式当场给朋友做一次具体反馈；再用自己的话讲一遍 PIP 的四要素和 GROW 的四步。能讲顺，说明你真正理解了绩效面谈与改进的闭环。", "sort_order": 2}, {"id": 6, "module_code": "compensation", "title": "第一章 薪酬结构设计", "summary": "薪酬由固定与浮动两部分构成，薪酬策略与带宽设计决定体系骨架，绩效联动让薪酬真正激励人。", "content": "# 第一章 薪酬结构设计\n\n## 案例引入：工程师的离职信（先思考，再看下文）\n\n周二上午，林晓的邮箱里躺着一封辞职信——硬件工程师张磊要去竞争对手“星环智能”，薪资高出 40%。这是本月第三位提离职的硬件工程师了。莱茵科技刚完成产品线成型和绩效体系落地，正处在快速扩张期，人才竞争异常激烈。\n\n王总把林晓叫到办公室，表情严肃：“我们的产品卖得不差，绩效体系也刚上线，为什么留不住核心工程师？注意，先别急着给张磊加薪挽留——加薪能留一个月，留不住一年。你先想清楚：我们的薪酬结构到底怎么搭，凭什么留人。”\n\n林晓翻着手里厚厚一沓入职谈薪记录，心里明白：公司的工资基本都是“谈出来的”，结构混乱、同岗不同酬、涨薪全靠老板拍板。\n\n> **思考：如果你是林晓，面对核心工程师接连被高薪挖角，你第一步会做什么？直接加薪是最优解吗？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 一套完整的薪酬结构由哪些部分构成，固定与浮动部分各起什么作用？\n> 2. 薪酬水平策略有哪些类型，扩张期的莱茵科技该选哪一种？\n> 3. 薪酬带宽怎么设计，薪酬如何与绩效联动？\n\n---\n\n## 一、薪酬的构成：固定 + 浮动\n\n薪酬（compensation）是企业因员工提供劳动而支付的各类回报的总和。按照德斯勒《人力资源管理》的经典框架，广义薪酬包含经济性报酬与非经济性报酬；其中经济性报酬又可划分为固定薪酬与浮动薪酬两大部分，再加上福利，共同构成完整的薪酬包。\n\n固定薪酬是员工每月稳定获得的部分，主要包括基本工资、岗位工资和技能工资，主要与岗位价值和任职者能力挂钩，承担“保障”功能，让员工有稳定的生活预期。\n\n浮动薪酬随个人、团队或公司绩效波动，包括绩效工资、奖金、销售提成、利润分享等，承担“激励”功能，把员工的努力与组织成果绑定。\n\n| 构成 | 发放依据 | 特点 | 典型形式 |\n| --- | --- | --- | --- |\n| 固定薪酬 | 岗位价值、能力等级 | 稳定、可预期、保障性强 | 基本工资、岗位工资 |\n| 浮动薪酬 | 绩效结果 | 有弹性、有风险、激励性强 | 绩效工资、年终奖、提成 |\n| 福利 | 全员普惠或差异化设计 | 保障与归属感 | 五险一金、补充保险、节日福利 |\n\n薪酬结构设计须遵循五项原则：保障性、激励性、公平性、经济性与合法性——只保不激是“大锅饭”，只激不保是“透支信任”。\n\n## 二、薪酬水平策略：定“高、平、低”\n\n薪酬水平策略回答“我们给的钱在市场上算多还是少”：\n\n- 领先策略：薪酬定位在市场高分位（如 P75 以上），用于吸引顶尖人才，成本高；\n- 跟随策略：定位在市场 50 分位附近，成本可控，是多数企业的主流选择；\n- 滞后策略：定位在市场低分位（如 P25 以下），需用稳定、成长空间等其他要素弥补；\n- 混合策略：关键岗位领先、一般岗位跟随或滞后，兼顾吸引与成本。\n\n莱茵科技处于扩张期、主打产品差异化、核心研发人才争夺激烈，更适合“关键岗位（研发）领先、支持岗位跟随”的混合策略。\n\n## 三、薪酬带宽设计\n\n薪酬带宽（pay range）指同一薪酬等级内薪酬最低值与最高值之间的区间，带宽通常用“最高值 ÷ 最低值”衡量。设计参数包括：中点值（常与市场目标分位对齐，作为该等级的“标准薪酬”）、带宽幅度（如 ±20%、±30%）、相邻等级间的级差与重叠度。经验上，岗位等级越高，带宽越宽——高层级岗位个人能力差异对组织影响更大，需要更大空间容纳差异。\n\n宽带薪酬（broadbanding）将多个薪酬等级合并为少数几个跨度很大的宽带，弱化行政层级、鼓励横向技能发展与轮岗，特别适合扁平化的成长型组织——莱茵科技这类快速扩张的公司正合适。\n\n## 四、薪酬与绩效联动\n\n绩效工资的基本公式是：绩效工资 = 绩效工资基数 × 绩效系数。绩效系数与考核等级挂钩，例如 S=1.3、A=1.1、B=1.0、C=0.8、D=0.5，做到“奖优罚劣有梯度”，避免干好干坏一个样。\n\n设计要点有二：一是浮动比例要与岗位性质匹配——研发岗浮动比例宜低（20%～30%），销售岗可高（50% 以上），否则研发工程师会因收入波动大而焦虑；二是考核结果必须真正影响收入，否则绩效体系就会沦为“走形式”。\n\n## 进阶视角：战略性薪酬与薪酬公平理论\n\n战略性薪酬（strategic compensation）强调：薪酬体系设计必须从公司战略出发。采取成本领先战略的企业宜控制薪酬成本；采取差异化战略、靠创新取胜的企业则应在关键人才上舍得投入。薪酬策略与战略错位，钱花得再多也留不住对的人。\n\n薪酬公平理论（亚当斯公平理论）指出：员工会将自己的“投入产出比”与参照对象比较，参照对象包括组织内的同事（内部公平）、外部市场上的同行（外部公平）、以及自己过去的经历（个体公平）。一旦感知到不公平，员工会消极怠工、要求加薪，甚至离职。三个公平分别靠三种机制保证：内部公平靠岗位价值评估，外部公平靠薪酬调查，个体公平靠绩效与能力付薪。\n\n常见误区：① 只靠加薪留人，忽视公平结构与成长通道；② 固定与浮动比例一刀切；③ 薪酬不透明，员工靠猜；④ 带宽设计不参照市场数据，全凭拍脑袋。\n\n\n## 进阶视角：战略薪酬与 HR 价值（尤里奇）\n\n薪酬不是\"发钱\"那么简单——它是组织战略的信号灯。**尤里奇（《人力资源转型》）**提出 HR 的角色模型（战略伙伴、效率专家、员工支持者、变革推动者），薪酬职能正是\"战略执行\"的关键抓手：薪酬体系设计前，先回答\"组织要什么行为、我们奖励什么\"。如果战略要求创新，薪酬却只奖励资历，体系与战略就互相打架。\n\n设计薪酬体系的三问：① 我们的战略靠什么赢？（成本领先 → 严控人工成本；差异化 → 高固定+高激励吸引顶尖人才）② 我们要激励什么行为？（结果、创新、还是协作？）③ 现有激励是否传递了正确的信号？**薪酬不是成本，是投资**——把每一分钱花在能驱动战略行为的地方。\n\n<!-- 书单补强 -->\n## 案例复盘：林晓的第一步\n\n林晓没有急着给张磊加薪，而是做了三件事：第一，与张磊离职面谈，发现他真正不满的除了收入，还有“薪酬结构里看不到明确的上升通道”——固定、浮动全凭入职时谈定，之后几乎不变；第二，拉出全员薪酬台账，发现研发岗整体水平偏低，且存在“早进来的比晚进来的低”的同岗不同酬现象，内部不公平已经显现；第三，与王总确认公司战略——扩张期、产品差异化，确定“关键岗位领先、支持岗位跟随”的薪酬策略。\n\n结果：林晓没有直接加薪，而是提交了“薪酬体系优化立项”，第一步是岗位价值评估。王总认可：先把工资是怎么算出来的说清楚，再谈加不加钱。\n\n> **对照思考：如果当时林晓选择“给张磊加薪挽留”，会引发哪些连锁问题？你能想到薪酬结构混乱还会带来哪些隐性成本？**\n\n## 费曼自检\n\n合上书，试着用你的话向一位朋友解释：薪酬由哪几部分组成？什么是薪酬带宽？为什么“同岗不同酬”最伤士气？如果你能讲清楚固定与浮动的分工、薪酬策略的选择逻辑和绩效联动机制，说明你已经掌握了本章核心。", "sort_order": 0}, {"id": 7, "module_code": "compensation", "title": "第二章 岗位价值评估与薪酬调查", "summary": "用因素计点法给岗位称重，用薪酬调查与分位数据对标市场，让内部公平与外部公平都有数据支撑。", "content": "# 第二章 岗位价值评估与薪酬调查\n\n## 案例引入：谁的岗位更值钱？（先思考，再看下文）\n\n薪酬体系优化立项后，林晓准备动手，会议室里先吵了起来。产品总监陈工拍着桌子：“硬件工程师天天画板子、赶版本，没有他们产品就是一堆图纸，研发岗当然最值钱！”销售总监刘姐不甘示弱：“产品再好，卖不出去就是库存，没有销售哪来的现金流？”行政的小李小声嘀咕：“我一年到头杂事最多，工资却垫底……”\n\n吵到王总面前，王总说：“别争了，让林晓拿数据说话。”林晓摊开台账，发现公司从来没有系统评估过岗位价值，所有人的工资几乎都是“入职时谈出来的”，同岗不同酬、岗位间价值倒挂的情况不少。可是，“岗位值多少钱”到底怎么衡量？\n\n> **思考：如果你是林晓，怎么让“谁的岗位更值钱”从吵架变成科学结论？凭感觉定工资和用方法定工资，差别到底在哪里？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 岗位价值评估有哪些主流方法？因素计点法是怎么给岗位打分的？\n> 2. 外部薪酬调查怎么做，薪酬数据从哪里来？\n> 3. 薪酬分位 P25、P50、P75 分别是什么意思，怎么用？\n\n---\n\n## 一、岗位价值评估：给岗位“称重”\n\n岗位价值评估（job evaluation）是依据岗位说明书，用系统化方法比较组织内各岗位的相对价值、从而建立岗位等级序列的过程。要点是：评估的对象是“岗位”，而不是“岗位上的人”——先有岗位的价值，再谈这个岗位上的人值多少钱。\n\n主流方法有四种：\n\n- 排序法：把岗位按整体价值从高到低直接排序，简单快捷，但缺乏精确尺度，岗位多时难以区分；\n- 分类法：预先设定若干等级并给出定义，把岗位归入相应等级，适合结构稳定的组织；\n- 因素比较法：选取若干付酬要素，直接与市场基准岗位比较定价；\n- 因素计点法：最常用也最系统——先选取付酬要素（如知识技能、解决问题能力、责任、工作条件），给每个要素按重要程度分配权重与点数，再逐项打分求和。总分越高，岗位等级越高。\n\n海氏评估法（Hay Guide Chart）是因素计点法的经典代表，选取三个要素：技能水平、解决问题的能力和承担的责任，分别套用量表打分，再按公式加权汇总，得出“海氏点数”，特别适用于管理和专业岗位。\n\n实施要点：① 以规范的岗位说明书为基础——说不清“做什么、要什么条件、担什么责任”，打分就是空中楼阁；② 组建跨部门评估委员会，避免 HR 闭门造车；③ 打分前统一培训，校准各要素的理解口径；④ 评估结果形成岗位等级表，作为薪酬等级划分的依据。\n\n## 二、外部薪酬调查：让市场数据说话\n\n薪酬调查（salary survey）是通过收集和分析外部劳动力市场上同类岗位的薪酬数据，为内部定薪提供参照基准的过程。它解决的是“外部公平”问题——我们的工资在市场上处于什么水平。\n\n数据来源主要有：专业咨询机构的薪酬报告（美世、怡安等）、招聘平台薪资数据、同行企业 HR 的数据交换、猎头反馈、政府发布的工资指导价位等。\n\n调研时有三个关键点：一是界定“可比市场”——同行业、同地区、同规模、同类岗位，跨行业跨地区的数据没有参考意义；二是明确调查的岗位范围，通常选取关键岗位和基准岗位；三是统一薪酬口径——月薪现金、年度总现金（含奖金）还是总薪酬（含福利与长期激励），口径不一致，结论必然失真。\n\n## 三、薪酬分位：P25、P50、P75\n\n分位（percentile）把一组市场薪酬数据按从低到高排序后，按百分位取值：P25 表示有 25% 的样本低于该值，是市场较低水平；P50 是中位值，代表市场中等水平；P75 表示有 75% 的样本低于该值，是市场较高水平。\n\n用法上：把薪酬中点值对齐 P50 对应“跟随策略”，对齐 P75 对应“领先策略”，对齐 P25 则偏“成本控制型”。定薪实践中，通常先用目标分位确定各等级中点值，再用带宽覆盖上下范围，形成完整的薪酬结构。\n\n## 进阶视角：评估的不是人，是岗位\n\n一个高频误区是把岗位评估结果直接当成个人工资——岗位值 8000 分，任职者是刚毕业的新人，工资绝不能按满分套。岗位评估决定“这个岗位的薪酬区间”，任职者能力与绩效决定“在这个区间里的位置”，两者必须分开。\n\n其他常见误区：评估要素与权重拍脑袋，不结合公司业务特点；只看内部不看外部，或只看外部不看内部；评估一次管十年，岗位职责变化后不重新评估；评估过程不透明，员工不知道等级怎么来的，反而引发猜疑。\n\n战略性视角：岗位评估解决内部公平，薪酬调查解决外部公平，二者结合后，把岗位点数与市场薪酬做回归拟合，画出薪酬曲线（salary line）——这是设计薪酬带宽、校准各等级中点值的数据基础。一张科学的薪酬曲线，等于把“谁值多少钱”写成了可验证的公式。\n\n## 案例复盘：莱茵科技的第一张薪酬曲线\n\n林晓按四步推进：第一，成立由王总、陈工、刘姐、赵姐组成的岗位评估委员会，先花两周完善各岗位说明书；第二，采用因素计点法，设计四大付酬要素（知识技能、解决问题、责任、工作条件），总分 1000 分，委员会逐岗打分；第三，购买行业薪酬报告、向同行 HR 交换数据，锁定研发岗的 P50 与 P75 数据；第四，把岗位点数与市场薪酬画成散点图，拟合出莱茵科技第一张薪酬曲线。\n\n结果出乎意料又在情理之中：硬件工程师因“知识技能 + 解决问题”权重最高而点数领先，销售岗在“责任”维度得分不低，行政岗整体居中偏低。由于分数是大家用同一把尺子量出来的，陈工和刘姐都服气；王总看着薪酬曲线说：“原来‘值多少钱’是可以算出来的。”\n\n> **对照思考：如果跳过岗位评估，直接按市场价给每个人调薪，会埋下什么隐患？为什么“先内部公平、后外部公平”的顺序很重要？**\n\n## 费曼自检\n\n合上书，向朋友解释：什么是因素计点法？P50 和 P75 分别代表什么？为什么说“评估岗位”和“评估个人”是两件事？如果你能用大白话讲清楚，说明你已经掌握了本章的核心。", "sort_order": 1}, {"id": 8, "module_code": "compensation", "title": "第三章 福利体系与激励设计", "summary": "法定福利守住合规底线，弹性福利提升感知，长期激励与非物质激励把留人从“加钱”升级为“共同成长”。", "content": "# 第三章 福利体系与激励设计\n\n## 案例引入：留人，光靠工资够吗？（先思考，再看下文）\n\n薪酬曲线画好了，林晓准备设计调薪方案，资深 HR 导师赵姐却提醒她：“工资是‘推力’，福利和成长才是‘拉力’。星环智能挖人不只是加钱——他们有期权、有弹性福利、有技术分享论坛。张磊走的时候说，那边‘给的不只是钱’。”\n\n林晓翻开刚出炉的员工满意度调研，发现两组扎眼的数据：30% 的年轻员工觉得“公司福利像老年套餐”——团建是爬山，过节发大米；而硬件工程师呼声最高的“加班打车报销”根本不在福利清单里。王总问林晓：“预算就这么多，除了涨薪，我们还能拿什么留人？”\n\n> **思考：如果你是林晓，在预算有限的条件下，怎么设计一套既合法合规、又让员工“有感觉”的福利与激励体系？福利和工资的作用有什么不同？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 法定福利有哪些？五险一金的缴费主体和特点是什么？\n> 2. 什么是弹性福利？它为什么越来越流行？\n> 3. 长期激励有哪些形式？工资之外的“非物质激励”怎么做？\n\n---\n\n## 一、法定福利：五险一金\n\n法定福利是国家通过法律法规强制企业提供的福利，核心是“五险一金”：养老保险（退休后按月领取养老金）、医疗保险（报销就医费用）、失业保险（失业期间的生活保障）、工伤保险（因工受伤的医疗与补偿）、生育保险（生育相关待遇，多地已并入职工医保），以及住房公积金（用于购房、租房等住房消费）。\n\n五险一金的特点是强制性、互助共济性、保障基本生活。缴费上，养老、医疗、失业三险和公积金由企业与个人按比例共同缴纳，工伤和生育保险由企业全额缴纳。\n\n合规红线必须牢记：试用期也要缴纳社保；不能用现金补贴代替社保；应按员工实际工资基数足额缴纳。踩了这些红线，不仅是福利问题，更是法律风险。\n\n## 二、弹性福利：把选择权还给员工\n\n弹性福利（flexible benefits）也称“自助餐式福利”：在福利预算总额内，员工可以根据个人需求，自主选择福利项目的组合，常见做法是“福利积分兑换制”——每人每年获得一定积分，按项目标价自由兑换。\n\n典型项目包括：补充商业保险、健康体检、加班打车报销、学习培训基金、弹性工作时间、带薪年假买卖、健身卡、住房补贴、子女教育津贴等。\n\n弹性福利的价值在于“千人千面”：不同年龄、不同家庭阶段的员工需求差异巨大——单身年轻人想要培训与健身，有娃员工想要子女教育津贴。把选择权交给员工，福利的感知度会大幅提升，同时预算总额封顶，成本可控。实施中要注意：法定福利不可被弹性项目替代；积分与项目定价要透明；定期调研员工偏好、动态调整菜单。\n\n## 三、长期激励：把员工变成“合伙人”\n\n长期激励指覆盖三年以上周期、把员工利益与公司长期发展绑定的激励安排，常见形式有：\n\n- 股票期权：授予员工在未来以约定价格购买公司股份的权利，公司价值增长则期权升值；\n- 限制性股票：达到业绩或服务年限条件后获得股票；\n- 虚拟股权 / 分红权：不涉及实际股权变更，按约定分享利润；\n- 跟投与利润分享计划：项目或年度利润的一定比例与核心员工分享。\n\n长期激励一般面向核心人才——研发骨干、管理层，因为“激励要给创造价值的人”。设计时要注意设定归属期（vesting）与行权条件，防止“期权画饼”；涉及个税与法律条款时需咨询专业意见。\n\n## 四、非物质激励：不花钱也能留人\n\n赫茨伯格双因素理论把工作相关因素分为两类：工资、福利、工作条件属于“保健因素”——不具备会引起不满，具备了也只是“没有不满”，并不会带来真正的满意；成就感、认可、成长、责任属于“激励因素”——它们才是驱动员工投入的真正引擎。\n\n非物质激励的手段丰富：清晰的晋升通道与职业发展双通道（管理线 / 技术线）、公开的认可与荣誉（评优、光荣榜、感谢信）、授权与挑战性任务、导师制、弹性工作安排、健康的企业文化。对预算有限的成长型企业，非物质激励是性价比最高的留人手段。\n\n## 进阶视角：总报酬模型——留人是一场组合拳\n\n世界薪酬协会（WorldatWork）提出总报酬模型（Total Rewards），把员工获得的一切分为五大要素：薪酬（pay）、福利（benefits）、工作生活平衡（work-life）、绩效与认可（performance & recognition）、发展与职业机会（development & career opportunities）。它提醒我们：员工不是只被钱激励的“经济人”，而是追求综合体验的“完整人”。\n\n据此反思常见误区：把福利当工资的附庸、预算一紧就砍掉；福利全员平均主义发放，感知度极低；用期权画饼却不说清归属条件，透支信任；忽视合规，社保基数不实、试用期不缴。留人没有银弹，只有把现金、福利、成长、认可组合起来，才能形成真正的“拉力”。\n\n\n## 进阶视角：激励认同与薪酬透明（杨国安 / 奈飞）\n\n钱不是万能的激励。**杨国安（《组织能力的杨三角》）**指出，组织能力 = 员工能力 × 员工思维 × 员工治理：能力解决\"会不会\"，**员工思维解决\"愿不愿\"**——薪酬福利设计如果只算经济账、不算认同账，员工会\"拿着钱骂公司\"。\n\n**奈飞（《奈飞文化手册》）**的实践更进一步：薪酬透明——经理可以看到全公司薪酬，鼓励员工公开讨论。其逻辑是：与其让员工私下猜疑\"隔壁是不是拿得比我多\"，不如用透明建立信任，让每个人都清楚\"高绩效高回报\"的规则。当然，薪酬透明需要配套的绩效文化和坦诚沟通，否则只会放大不满。\n\n> 启发：激励设计要回答三个层次——给得够不够（外部公平）、分得公不公（内部公平）、**为什么这么分**（规则透明与认同）。\n\n<!-- 书单补强 -->\n## 案例复盘：莱茵科技的“福利积分制”\n\n林晓的方案分五步落地：第一，合规盘点，核查社保公积金缴纳情况并补齐漏洞——红线绝对不能碰；第二，预算内重构，把“发大米、爬山团建”等低感知项目的预算转为“福利积分池”，每人每年固定积分；第三，上线弹性福利菜单——补充商业保险、加班打车报销、学习基金、健身卡、弹性上下班、年假兑换等，按积分自由兑换，硬件工程师最爱的“加班打车报销”上线首月使用率第一；第四，为研发骨干设计虚拟股权 / 分红权方案，归属期三年，把“被挖角”变成“一起干”；第五，建立技术分享论坛、季度“硬件之星”评选和双通道职业发展体系。\n\n半年后，人才流失率从 18% 降到 9%，竞对挖角电话明显减少，员工福利满意度从 41% 升到 78%。王总在月度会上感慨：“花在福利上的每一分钱，都花在刀刃上了。”\n\n> **对照思考：为什么“发大米”没人感激，而“积分自选”却广受好评？如果福利预算只有 20 万，你会把哪三项放在第一优先级？**\n\n## 费曼自检\n\n合上书，向朋友解释：五险一金是哪“五险”哪“一金”？弹性福利与传统福利的区别是什么？为什么说“工资福利是保健因素，成长与认可才是激励因素”？讲得明白，才算真正掌握。", "sort_order": 2}, {"id": 9, "module_code": "employee-relations", "title": "第一章 员工入职与全生命周期管理", "summary": "从入职前准备到试用期管理，用员工生命周期与心理契约视角留住新人。", "content": "# 第一章 员工入职与全生命周期管理\n\n## 案例引入：新人来了，为什么留不住？（先思考，再看下文）\n\n莱茵科技已扩张到 300 人，绩效、薪酬体系先后落地，但林晓在季度 HR 数据盘点时发现一个刺眼的数字：销售部两名新人在试用期内主动离职，技术团队也反馈\"新同事入职三个月了还没进入状态\"。离职面谈里，新人说得最多的两句话是：\"入职第一周，我不知道该找谁、不知道自己该干什么。\"行政同事翻出记录：有一位新人的工位和电脑账号，是入职当天下午才临时配齐的，第一周几乎没人主动带他认识团队。王总在管理会上敲着桌子问：\"人招进来了，怎么留不住？\"\n\n> **思考：如果你是林晓，会从哪些环节入手改善新人的入职体验？入职管理做得不好，与试用期流失、团队融入慢之间是什么关系？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 一套完整的入职流程覆盖哪些环节？\"第一天到第一个月\"的入职引导应该如何设计？\n> 2. 试用期管理如何与目标设定、转正决策衔接，避免用人部门\"放养\"新人？\n> 3. 用\"员工生命周期\"的视角看，入职环节为什么会影响员工后续的敬业度与留任？\n\n---\n\n## 一、员工入职与全生命周期管理\n\n**员工关系**是组织为建立并维持良好雇佣关系所做的全部努力，它的起点不是离职管理，而是员工进入组织的那一刻。德斯勒把入职流程概括为\"欢迎新员工并帮助他们适应组织\"的系统过程，现代人力资源管理进一步把它视为**入职管理（Onboarding）**——让新员工从\"外部人\"转变为\"内部人\"的一段旅程，目标是同时完成三件事：**传递信息**（文化、制度、岗位职责）、**建立连接**（认识同事、找到支持）、**形成承诺**（认同组织、愿意投入）。\n\n**入职引导（Orientation）**是入职管理的核心载体，分为三个层面：\n\n| 层面 | 内容 | 典型动作 |\n|---|---|---|\n| 组织层面 | 愿景、文化、制度、组织结构 | 欢迎会、CEO 致辞、员工手册 |\n| 岗位层面 | 职责、工具、资源、目标 | 岗位说明、IT 账号、第一周任务清单 |\n| 人际层面 | 同事、上级、导师 | 介绍团队成员、安排入职伙伴 |\n\n很多公司把入职引导做成\"入职第一天的一堂 PPT 课\"，这是最大的误区。有效的入职引导是分阶段的：**第一天**解决\"被欢迎、知道往哪坐、知道找谁\"；**第一周**解决\"知道要干什么、怎么干\"；**第一个月**解决\"能独立承担小任务、建立信任\"。\n\n**试用期管理**是入职管理的延续，本质是\"双向考察期\"：组织考察新人是否胜任，新人考察组织是否值得留下。关键动作是**把目标说在前面**——入职第一周，直属主管与新人共同设定试用期目标与转正标准；在 30 天、60 天等节点安排正式反馈；转正前依据事先明确的标准评估，而不是凭主管印象。试用期管理做得好，等于把\"最小的绩效闭环\"做了一遍：目标→反馈→评估→改进。\n\n**员工生命周期**把雇佣关系划分为：吸引→招聘→入职→发展→保留→离职。每个触点都是一次\"体验交换\"，也是**心理契约**的兑现点。心理契约指员工与组织之间未成文的相互期望——员工期望\"我付出努力，组织给我成长与回报\"，组织期望\"员工认同并投入\"。入职期是心理契约形成最敏感的时期：承诺与体验落差过大，新人会迅速产生\"被欺骗感\"，这正是试用期流失的深层原因。\n\n## 进阶视角：员工体验、心理契约与任期制\n\n- **从\"触点\"到\"旅程\"**：员工体验（Employee Experience）理念认为，HR 不应只管理一个个孤立触点（签合同、发工牌），而应设计整段\"员工旅程\"，入职是第一站。Google 的研究与众多企业实践都显示，良好的入职体验与新人留存率、首年产出率正相关。\n- **心理契约是\"易碎品\"**：它是主观的、动态的。入职时的承诺（哪怕是随口一句\"这里能快速成长\"）如果后续不被兑现，比从未承诺更伤信任。HR 要做的不是避免承诺，而是让承诺可兑现、可沟通。\n- **《联盟》的任期制启发**：把雇佣关系看作一段有起止的\"任期\"，入职时双方就明确\"这次任期你要达成什么、组织给你什么\"。入职引导因此成为\"盟约\"的起点，让新人带着明确契约而不是模糊期待开始工作。\n- **《奈飞文化手册》的坦诚筛选**：高人才密度文化下，入职是双向选择。奈飞强调用坦诚对话让新人了解真实的工作方式，避免\"蜜月期后幻灭\"。\n\n## 案例复盘：林晓把入职做成\"一段旅程\"\n\n问题：新人试用期流失、融入慢，入职体验粗糙。林晓做了三件事：**第一，入职前准备清单化**——HR 在入职前 3 天完成工位、电脑、账号、门禁与欢迎信（含第一周日程），由行政与 IT 双确认；**第二，第一天引导标准化 + 入职伙伴制度**——每位新人配一位非直属的老员工做\"入职伙伴\"，专治\"不知道找谁\"；**第三，试用期 30-60-90 机制**——第 1 周主管与新人共同设定目标并书面确认，第 30、60 天各做一次正式反馈，转正前 HR 汇总材料、安排转正面谈，把转正变成一次\"双向复盘\"而非\"生死判决\"。结果：下一季度试用期主动离职明显下降，新人第一个月即可承担基础任务，技术团队的\"三个月进入状态\"缩短为\"一个月上手\"。赵姐点评：\"入职引导不是仪式感，它是一场心理契约的奠基礼——第一天丢的新人，后面要用三个月补。\"\n\n> **对照思考：你最初的想法和林晓的做法差距在哪里？你是否把入职引导当成\"一次性活动\"，而忽略了它其实是贯穿第一个月的旅程？**\n\n## 费曼自检\n\n合上章节，向朋友解释：\"为什么入职引导做得好的公司，试用期流失率更低？\"如果能讲清楚\"入职体验塑造心理契约，心理契约影响承诺与留任\"这条链路，本章就过关了；讲不清楚的地方，就是需要重读的地方。", "sort_order": 0}, {"id": 10, "module_code": "employee-relations", "title": "第二章 员工沟通与冲突处理", "summary": "搭建沟通渠道、识别冲突类型，用事实对齐与坦诚文化把分歧变成更好的决策。", "content": "# 第二章 员工沟通与冲突处理\n\n## 案例引入：会议室里的针锋相对（先思考，再看下文）\n\n智能手表产品线进入上市冲刺，销售总监刘姐在全员会上宣布：\"下季度末必须上市，我已经向渠道商承诺了交付时间。\"产品总监陈工当场反驳：\"功能还没打磨完，测试都过不了，强行上市是砸自己的口碑。\"两人在会议室里针锋相对，会后陈工把项目群名字改成了\"背锅群\"，刘姐则直接找王总告状，说产品部门不配合、拖业绩后腿。接下来的两周，两个部门互相推诿：销售抱怨\"产品不给承诺\"，产品抱怨\"销售乱承诺\"。多名员工私下找到林晓：\"夹在中间，活都没法干了。\"\n\n> **思考：如果你是林晓，会怎么介入这场跨部门冲突？是先站队、还是先做什么？HR 平时做哪些工作，才能在冲突升级前就听到这些声音？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 员工沟通有哪些渠道？HR 如何让\"上行、下行、平行\"的信息都流动起来？\n> 2. 冲突有哪些类型和根源？处理冲突的正确步骤是什么？\n> 3. 什么是坦诚文化？HR 如何引导组织\"对事不对人\"地表达分歧？\n\n---\n\n## 一、员工沟通与冲突处理\n\n**员工沟通**是组织内部信息传递与意见交换的系统工程，是员工关系管理的基础。按方向分为**下行沟通**（组织→员工：制度、通知、愿景）、**上行沟通**（员工→组织：意见、建议、诉求）和**平行沟通**（部门之间、同事之间）；按正式程度分为正式渠道（全员会、绩效面谈、员工意见箱、内部通讯）与非正式渠道（茶水间聊天、私下交流）。HR 的职责不是\"管住嘴\"，而是**让渠道通畅、让声音上得来、让反馈有闭环**——员工提了意见却石沉大海，比没有渠道更伤信任。\n\n**员工满意度**与**敬业度**是两个常被混用的概念。满意度是员工对工作条件（薪酬、环境、福利等\"保健因素\"）的满意程度；敬业度则是员工在情感与认知上认同组织、愿意为组织成功付出额外努力的程度（对应\"激励因素\"）。满意度高不等于敬业——\"拿着满意的薪水混日子\"并不少见；而敬业度与业务结果（效率、质量、留任、客户满意度）的关联更强。HR 既要通过沟通了解满意度，更要通过机制经营敬业度。\n\n**冲突**是一方感知到另一方损害或可能损害自身利益的过程。冲突并非全是坏事，关键在于类型与处理：\n\n| 类型 | 本质 | 危害/价值 |\n|---|---|---|\n| 任务冲突 | 对工作内容、方案看法不同 | 适度可提升决策质量 |\n| 关系冲突 | 人际对立、情绪对抗 | 通常有害，需及时干预 |\n| 过程冲突 | 对分工、流程、做事方式分歧 | 需通过明确规则化解 |\n\n冲突的常见根源：目标不一致、资源稀缺、沟通不良、角色不清、个性差异。案例中陈工与刘姐的分歧表面是\"吵交付时间\"，本质是**目标不一致（销售要市场窗口、产品要质量闸门）叠加信息不对称**。\n\n**处理冲突的步骤**：①冷静介入，不偏听偏信——分别与各方单独沟通，还原事实；②识别类型与根源——是任务、关系还是过程冲突？争的是事实还是立场？③情绪安抚与分别沟通——先处理情绪，再处理问题；④促成共同协商——把双方拉回\"共同目标\"，对事不对人，用事实和数据说话；⑤形成共识与跟进机制——明确决策、记录在案、定期复盘。HR 的角色不是裁判或法官，而是**搭台子的人**：帮双方回到事实与共同利益。\n\n托马斯-基尔曼冲突处理模式给出五种策略：**竞争**（坚持己见，适用紧急且正确时）、**协作**（双赢，适用重要且时间充足时）、**妥协**（各让一步，适用双方实力均衡时）、**回避**（暂不处理，适用小事或需要冷静期时）、**迁就**（牺牲自己成全对方，适用关系重于结果时）。没有绝对最优策略，高手按情境选择。\n\n**坦诚文化**以《奈飞文化手册》为代表：高人才密度让坦诚沟通的成本更低、收益更高——因为每个人都值得被直接告知真相。坦诚不是粗暴，而是\"基于事实与善意的直言不讳\"：区分事实与观点、对事不对人、公开表达分歧但私下不传播。HR 要做的，是建立\"说真话不被惩罚\"的心理安全感。\n\n## 进阶视角：敬业度、心理安全感与坦诚的边界\n\n- **盖洛普 Q12**：敬业度研究最著名的工具，12 个问题测量员工对\"期望、资源、认可、成长、伙伴\"的感知，其结果与部门绩效、留任显著相关。员工关系的日常，就是回答 Q12 里那些问题。\n- **心理安全感**：Google \"亚里士多德项目\"对上百个团队的研究发现，高绩效团队的第一要素不是成员能力，而是**心理安全感**——成员敢于表达不同意见而不担心被嘲笑或惩罚。坦诚文化的底层就是心理安全感。\n- **坦诚的边界**：坦诚≠批评人格。健康的坦诚是\"指出问题、对事不对人、给出改进方向\"；在低信任环境里强行推行\"直言不讳\"，只会变成互相攻击。坦诚文化要靠高人才密度与领导示范共同支撑。\n- **HR 的定位升级**：尤里奇模型中，HR 是\"员工支持者\"与\"组织能力建设者\"。处理冲突不是替老板站台，而是设计让分歧\"建设性发生\"的机制——例会是机制，决策记录是机制，跨部门对齐也是机制。\n\n\n## 进阶视角：组织能力视角的员工关系（杨国安）\n\n员工关系不是\"救火队\"，而是组织能力的基石。**杨国安（《组织能力的杨三角》）**的员工思维与员工治理两个支柱，恰好对应员工关系的两个层面：\n\n- **员工思维（愿不愿）**：价值观、认同感、敬业度——靠文化、沟通、坦诚（呼应奈飞）；员工愿不愿投入，决定了冲突处理、留任挽留的效果\n- **员工治理（机制）**：沟通渠道、申诉机制、员工手册、反馈制度——**好的关系靠机制兜底，不靠个人魅力**。案例中陈工与刘姐的交付冲突，单靠调解只能解决一次，靠\"跨部门对齐机制\"才能根治\n\n> 思考：你们公司的员工关系，是依赖某个\"会来事\"的 HR，还是靠一套透明、可预期的机制？\n\n<!-- 书单补强 -->\n## 案例复盘：林晓把\"立场之争\"变成\"数据决策\"\n\n问题：产品与销售因交付时间激烈对立，部门间推诿、员工士气受损。林晓没有在会上站队，而是：**第一步**，分别与陈工、刘姐单独深谈，还原各自的事实——刘姐的依据是渠道商与市场窗口期，陈工的依据是测试通过率与质量风险；**第二步**，识别这是任务冲突叠加目标不一致，而非私人恩怨；**第三步**，建议王总召开\"事实对齐会\"，规则只有一条：只摆数据，不摆情绪。会上，双方把市场窗口、竞品节奏、测试数据摊在桌上，分歧立刻收敛为一个真问题：\"质量闸门定在什么标准，最迟什么时候必须过。\"最终确定：以质量闸门为准、销售同步调整渠道预期，上市时间仅延后两周。**第四步**，林晓推动建立每周跨部门例会与\"决策记录单\"，防止同类冲突复发。结果：两个团队从对立转向配合，陈工说\"吵明白了比憋着强\"。赵姐提醒：\"HR 处理冲突的最高境界，不是当和事佬，而是让下一次冲突变成一次更好的决策。\"\n\n> **对照思考：你会不会像林晓一样先收集事实再介入？你能区分任务冲突与关系冲突，并分别用不同方式处理吗？**\n\n## 费曼自检\n\n合上章节，向朋友讲清楚：\"为什么说冲突不都是坏事？\"并说出处理冲突的五步。如果能讲明白\"任务冲突要管理、关系冲突要干预、坦诚要建立在心理安全感之上\"，本章就过关了。", "sort_order": 1}, {"id": 11, "module_code": "employee-relations", "title": "第三章 离职管理与离职面谈", "summary": "规范离职流程、挖掘真实离职原因，用挽留评估与留任访谈把流失变成组织改进的输入。", "content": "# 第三章 离职管理与离职面谈\n\n## 案例引入：骨干要走，怎么留？（先思考，再看下文）\n\n周一早晨，林晓收到一封离职申请：一位入职三年的高级硬件工程师要离开，理由写的是\"个人发展\"。私下沟通时他坦言拿到了竞对 offer，薪酬涨 40%。王总很着急：\"薪酬不是刚调过吗？怎么还是留不住人？\"林晓翻了近两个季度的数据，发现研发核心岗位主动离职率从 5% 升到了 12%，其中两位离职员工在面谈时欲言又止，只留下\"公司挺好的，就是不太适合\"。赵姐提醒她：\"离职面谈是你最接近真相的窗口，别浪费了——但也要小心，员工说出口的，未必是真正的原因。\"\n\n> **思考：如果你是林晓，会如何设计这场离职面谈？什么样的离职值得挽留、如何挽留？一次离职背后，可能藏着什么样的组织问题？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 离职的标准流程是什么？HR 在每个环节的职责边界在哪里？\n> 2. 离职面谈有哪些技巧？如何让员工说出\"真正的\"离职原因？\n> 3. 如何分析离职数据并推动组织改进？\"留任访谈\"为什么比离职面谈更前置？\n\n---\n\n## 一、离职管理与离职面谈\n\n**离职**分为**自愿离职**（员工主动提出：个人原因、组织原因）与**非自愿离职**（辞退、裁员、合同到期不续）。员工关系管理的重点是自愿离职中**可预防的部分**——那些本可以避免的核心人才流失。离职的真实成本常被低估：显性成本包括招聘重置、培训投入、薪酬溢价与临时替代，隐性成本包括业务中断、知识流失、团队士气受损与客户关系波动。行业经验普遍认为，核心员工流失的总成本可达其年薪的 1 至 2 倍甚至更高。\n\n**离职流程**要合规、有序、有温度：\n\n| 环节 | 关键动作 | 责任主体 |\n|---|---|---|\n| 提出申请 | 书面申请、明确最后工作日 | 员工 |\n| 初步沟通 | 了解原因、评估是否挽留 | HR/主管 |\n| 审批与交接 | 清单化交接、防止知识断层 | 主管/HR |\n| 离职面谈 | 中立、保密、挖真实原因 | HR |\n| 手续办理 | 财务/行政/IT/社保/离职证明 | HR/各部门 |\n| 关系维护 | 好聚好散、保持连接 | HR |\n\n**离职面谈技巧**：目的不是\"说服留下\"，而是获取真实原因、为组织改进提供输入。要点包括：**时机**——在员工情绪平复后、审批流程中安排，避免当面冲动；**环境**——私密、安静、中立，不选主管办公室；**方式**——开放式提问为主，先感谢、多倾听、不评判，明确告知内容保密且不影响离职手续；**追问**——对\"个人原因\"\"薪酬\"这类表面答案多问一层：\"除了薪酬，还有没有其他原因？\"\"如果公司能改变一件事，你希望是什么？\"常见误区：让直属主管去谈（员工不敢说真话）、在公共场合谈、把面谈变成挽留谈判。\n\n**离职原因分析**：把每次面谈内容结构化编码（薪酬、发展、管理风格、工作负荷、文化氛围、家庭等），按岗位、司龄、部门、季度维度汇总，重点识别\"组织可控制原因\"并推动改进。一次离职是个人事件，十次离职就是组织信号。\n\n**离职挽留**：挽留不是\"加钱万能\"，更不是\"为留而留\"。正确顺序是：先判断**挽留价值**（绩效、不可替代性、团队影响），再判断**原因可解决性**（薪酬缺口可补，价值观不合难解），最后给**针对性方案**（调岗、新项目、晋升通道、柔性安排）。对不值得留的人开出高价条件，既破坏内部公平，也为未来埋雷。\n\n## 进阶视角：任期制、留任访谈与校友网络\n\n- **《联盟》的任期制**：雇佣关系不是\"终身承诺\"，而是一段段有目标的任期。离职不是背叛，而是任期结束——好聚好散，双方都能体面转身。基于此，企业可以经营**前员工校友网络（Alumni Network）**：离职员工可能成为客户、伙伴、人才推荐者甚至回流者。\n- **留任访谈（Stay Interview）**：与其等员工提出离职才做\"离职面谈\"，不如定期问在职员工两个问题：\"什么会让你留下？什么会让你离开？\"留任访谈是事前的、低成本的、可干预的流失预警。\n- **离职面谈的局限**：员工可能因为顾虑（背调、圈子、尴尬）而不说真话。所以离职数据要与留任访谈、匿名调研、绩效数据交叉验证，避免被个别失真样本带偏。\n- **数据视角**：把离职率、离职原因、流失成本做成定期管理报表（如\"组织健康仪表盘\"），让\"留人\"从 HR 的独角戏变成管理者的共同指标。\n\n## 案例复盘：林晓从一次离职看到组织问题\n\n问题：高级硬件工程师离职、研发主动离职率翻倍、面谈信息模糊。林晓的做法：**第一步，专业离职面谈**——选择安静会议室，先感谢三年的贡献，用开放式提问：\"抛开薪酬，什么让你最想离开？\"工程师最终说出真话：薪酬只是诱因，真正的原因是产品方向反复、跨部门扯皮让他\"三年没做成一个像样的项目\"，成长见顶。**第二步，结构化分析**——她把当季所有离职面谈编码汇总，发现\"成长空间\"与\"跨部门协作\"排在前两位，薪酬反而排在第三。**第三步，挽留评估**——该工程师绩效优秀、属核心人才，离职主因\"成长空间\"部分可解决，王总与陈工随后给了他新项目的主导角色，他最终留下。**第四步，组织改进**——林晓推动公司建立研发技术晋升通道、固化跨部门对齐机制（承接第二章的例会制度），并把离职数据纳入季度经营会。结果：半年后研发主动离职率回落至 7%，两名离职员工一年后通过\"校友群\"回流，还推荐了 3 名候选人。赵姐点评：\"离职面谈的终点不是留人，是改组织。你能从一个人的离开里看到一群人的问题，这一单就不亏。\"\n\n> **对照思考：你会不会一听说离职就先加薪？你能否从一次离职面谈里，看到组织层面的系统性原因？**\n\n## 费曼自检\n\n合上章节，向朋友讲清楚：\"离职面谈的真正目的不是挽留，而是组织改进。\"并解释为什么\"留任访谈比离职面谈更值得做\"。能讲明白，本章就过关了。", "sort_order": 2}, {"id": 15, "module_code": "training", "title": "第一章 培训需求分析", "summary": "从组织、任务、个人三个层面诊断培训需求，先归因再培训，让每一分培训投入都有的放矢。", "content": "# 第一章 培训需求分析\n\n## 案例引入：新人断层，先别急着排课（先思考，再看下文）\n\n一年之内，莱茵科技从 80 人扩张到 300 人，扩张的代价很快显现：硬件部新招的工程师平均要 6 个月才能独立负责一个项目，研发进度一拖再拖；产品团队里一半是转岗和应届生，对智能穿戴行业一窍不通，做出来的产品需求文档被陈工退回好几次；销售刘姐也抱怨，新人对新品功能讲不清楚，客户问两句就答不上来。王总把林晓叫到办公室：“别整那些虚的，赶紧把培训排起来，人来了就得能干活。”\n\n林晓很清楚，王总要的是“能干活的人”，可她一时不知道该怎么排——给谁培训？培训什么？为什么培训？如果只是随便拉几门课，钱花了，问题还在。\n\n> **思考：如果你是林晓，接到王总“赶紧培训”的指令，你会直接去排课表吗？先想一想：培训到底该给谁上、上什么、为什么上？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 为什么说培训之前必须先做需求分析？组织、任务、个人三层分析分别解决什么问题？\n> 2. 常用的需求调研方法有哪些？怎么避免调研结果失真？\n> 3. 721 学习法则告诉我们，员工能力提升的主要来源是什么？\n\n---\n\n## 一、什么是培训需求分析：三层模型\n\n培训需求分析（Training Needs Analysis，TNA）是指在设计培训之前，由 HR 与业务部门共同收集和分析相关信息，找出员工“实际绩效”与“期望绩效”之间的差距，并判断这个差距能否通过培训来弥补的系统过程。它是培训工作的起点：没有需求分析，培训就是无的放矢。\n\n经典的做法是把需求分成三个层面来看：\n\n| 分析层次 | 分析内容 | 要回答的问题 | 常用方法 |\n| --- | --- | --- | --- |\n| 组织层 | 组织战略、目标、资源与绩效数据 | 培训是否支撑战略？组织愿意投入多少？ | 战略会议、绩效报告、访谈高管 |\n| 任务层 | 岗位职责与完成工作所需的知识、技能、标准 | 做好这份工作，到底需要什么能力？ | 工作分析、岗位说明书、访谈业务专家 |\n| 个人层 | 员工实际能力与岗位标准之间的差距 | 谁需要培训？缺什么？缺多少？ | 绩效评估、能力测评、问卷访谈 |\n\n组织层回答“要不要培训”——培训必须为战略服务；任务层回答“培训什么”——以岗位要求为标准；个人层回答“培训谁”——锁定真正有差距的人。三个层面缺一不可：跳过组织层，培训可能与战略脱节；跳过任务层，不知道标准在哪；跳过个人层，容易变成“大锅饭”式全员培训。\n\n## 进阶视角：需求分析不是走形式\n\n实践中最大的误区是把培训当“万金油”：绩效上不去就培训。其实绩效差距的成因很多——流程不顺、激励不足、工具落后，都可能造成同样的表现差距，这些不是培训能解决的。所以需求分析的关键一步是“归因”：先判断差距是不是“员工不会”造成的，再决定要不要培训。\n\n这也是打造“学习型组织”的起点。管理学家彼得·圣吉在《第五项修炼》中提出，学习型组织不是“多办几场培训”，而是把学习嵌入组织的日常运作。杨国安教授在《组织能力的杨三角》中指出，员工能力、员工思维、员工治理是组织能力的三大支柱，其中“员工能力”正是靠招聘、培训、发展等手段系统打造的，而且必须与战略方向一致——这就是组织层分析的意义所在。\n\n从投资视角看，培训是人才资本投资而不是成本。正因为要花钱，才更要先算清楚“缺口在哪、投给谁、怎么衡量回报”，否则钱花了，培训却沦为“看起来很努力”。\n\n## 案例复盘：林晓没有急着排课\n\n林晓没有直接安排课程，而是花了两周做需求分析。她先与王总对齐战略（组织层）：公司要主攻中高端智能手表市场并拓展海外，人才必须支撑这个方向；再与陈工、刘姐一起做关键岗位的工作分析（任务层）：硬件工程师需要掌握电源管理、传感器调试和可穿戴产品认证流程，产品经理需要行业认知与需求分析方法论；最后用绩效数据、主管访谈和员工问卷（个人层）盘点出三类重点人群——新入职硬件工程师 44 人、转岗及应届产品经理 12 人、一线销售 60 人。\n\n当她拿着“差距清单”向王总汇报时，讲的已经不是“要不要培训”，而是“培训什么、给谁、何时、怎么衡量”。王总认可并批了预算。林晓明白，这次培训第一次有了明确的靶子。\n\n> **对照思考：如果你们团队出现“新人上手慢”，你会先做哪一层的分析？为什么先做它？**\n\n## 费曼自检\n\n合上本章，试着用自己的话向一位朋友解释：什么是培训需求分析？三层模型分别看什么？为什么“领导说该培训”不等于“真的需要培训”？", "sort_order": 0}, {"id": 16, "module_code": "training", "title": "第二章 培训计划与实施", "summary": "把培训目标翻译成可落地的课程与形式，用柯氏四级评估证明培训价值，让培训从“花钱买热闹”变成“投资有回报”。", "content": "# 第二章 培训计划与实施\n\n## 案例引入：培训是“排课表”，还是“搭体系”？（先思考，再看下文）\n\n需求分析做完，林晓向王总汇报了三大培训需求，王总大手一挥：“需求清楚了，那就开课！”可一落地林晓就犯了难：44 名硬件工程师分布在三个产品组，排班各不相同；12 名产品经理水平参差；60 名销售遍布全国，集中面授差旅成本高得吓人。赵姐提醒她：“培训不是排个课表就完事——目标、课程、形式、效果证明，每一步都要想清楚，否则就是花钱买热闹。”\n\n林晓意识到，她需要的不是课程清单，而是一套从目标到评估的完整方案。\n\n> **思考：如果你是林晓，面对“人少、分散、水平不齐”的三类人群，你会怎么设计培训方案？先想：每类人的培训目标是什么？用什么形式最划算？怎么证明有效？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 一份好的培训目标应该怎么写？它和业务目标是什么关系？\n> 2. 面授、在线、在岗三种培训形式各有什么适用场景？如何组合？\n> 3. 柯氏四级评估的四个层次是什么？为什么“学员很满意”不等于“培训有效”？\n\n---\n\n## 一、培训目标设定与课程设计\n\n培训目标（Training Objectives）是用可观察、可衡量的行为，描述学员培训后应达到的水平。规范写法含三要素：条件（什么情况下）、行为（能做什么）、标准（做到什么程度）。例如：“培训结束后两周内，新入职硬件工程师能独立完成一块开发板的电源调试，返工率低于 5%。”相比“提升能力”这类空泛表述，这样的目标可考核、可追踪。\n\n培训目标必须能“反向追溯”到业务目标——它支撑“缩短新人上手周期、提升研发良率”这一诉求。目标与业务挂钩，评估才有依据。\n\n课程设计可以遵循 ADDIE 闭环：分析（Analysis）→ 设计（Design）→ 开发（Development）→ 实施（Implementation）→ 评估（Evaluation），评估结果反哺下一轮需求分析。\n\n## 二、培训形式：面授、在线与在岗\n\n| 培训形式 | 适用内容 | 优点 | 局限 |\n| --- | --- | --- | --- |\n| 面授（线下集中） | 复杂技能演练、态度与价值观类 | 互动强、可实操演练、即时反馈 | 成本高、规模受限、时间难统一 |\n| 在线（E-learning） | 标准化知识、制度合规类 | 可规模化、时间灵活、成本低 | 互动弱、完成率难保证、效果难监督 |\n| 在岗（OJT，在岗培训） | 岗位技能、业务场景类 | 做中学、即学即用、成本低 | 依赖带教人水平、质量不稳定 |\n\n721 学习法则告诉我们：员工能力的提升，约 70% 来自在岗实践，20% 来自向他人学习（导师、同事、反馈），只有 10% 来自正式培训。因此成熟的培训体系以在岗实践为主体，面授与在线作为补充，三种形式组合使用。\n\n## 进阶视角：柯氏四级评估——让培训价值“看得见”\n\n培训到底有没有用？管理界最经典的检验框架是柯氏四级评估模型：\n\n- 反应层（Reaction）：学员是否满意——用满意度问卷测量；\n- 学习层（Learning）：知识技能是否掌握——用考试、实操考核测量；\n- 行为层（Behavior）：工作中行为是否改变——用主管观察、行为指标测量；\n- 结果层（Results）：业务结果是否改善——用良率、效率、销售额等经营指标测量。\n\n常见误区是培训只做到反应层：掌声热烈、好评如潮，却拿不出“行为变了、结果好了”的证据。正确做法是从结果层倒推：先想清楚要改善什么业务结果，再反推行为、学习、反应各层怎么做。培训后的复盘与知识沉淀（案例库、SOP）则把个人所学转化为组织能力——这正是学习型组织强调的“组织学习”。\n\n## 案例复盘：林晓把培训做成了“项目”\n\n林晓没有排“大课表”，而是按人群分别设计方案。硬件工程师采用“面授集训 + 在岗带教”：第一周集中面授（电源管理、传感器调试、认证流程），之后 6 周由资深工程师带教在岗项目，每周技术评审；产品经理采用“线上课程 + 案例拆解工作坊”，由陈工主持竞品拆解会；销售用在线微课 + 话术演练打卡，在刘姐的销售例会上复盘。\n\n每类培训都写明了可衡量目标，例如“培训后 4 周内，新人硬件工程师独立交付的开发板调试任务通过率不低于 80%”，并按柯氏四级设计了评估：反应层用问卷，学习层用实操考核，行为层由主管按月评估，结果层直接对比新人独立上手周期。半年后，新人独立上手周期从 6 个月缩短到 4 个月。\n\n> **对照思考：如果你是林晓，会拿哪一层的证据向王总证明培训有效？为什么？**\n\n## 费曼自检\n\n合上本章，向朋友解释：什么叫“可衡量的培训目标”？面授、在线、在岗各适合什么场景？柯氏四级评估为什么不能只停在“满意”这一层？", "sort_order": 1}, {"id": 17, "module_code": "training", "title": "第三章 人才梯队与继任计划", "summary": "识别关键岗位、评估继任者并持续培养，用导师制与双通道让组织不靠几个“英雄”撑着。", "content": "# 第三章 人才梯队与继任计划\n\n## 案例引入：一个人走了，业务会不会塌？（先思考，再看下文）\n\n随着公司扩张，林晓心里埋着一个隐患：产品总监陈工一个人攥着三条产品线的关键决策，他休假一周，产品评审就停摆；资深工程师老周、老吴几乎包揽了所有新人问题的解答，一旦离职，新人连问的人都找不到。销售刘姐也半开玩笑地说：“大客户都认我，我是一天都不敢休。”\n\n王总在管理会点题：“公司不能靠几个‘英雄’撑着，得把板凳坐深一点——关键位置上得有人能随时顶上来。”\n\n> **思考：如果你是林晓，怎么帮公司“攒板凳”？先想：哪些岗位最怕人走？怎么提前知道谁能顶上来？**\n\n## 带着问题学\n\n> 本章知识点将帮你解决上面的难题。学完本章，你将能够回答：\n> 1. 什么是关键岗位？怎么识别它？\n> 2. 继任者评估看什么？为什么“高潜”不等于“马上能用”？\n> 3. 导师制和职业发展通道在人才梯队建设中起什么作用？\n\n---\n\n## 一、关键岗位识别与继任计划\n\n关键岗位（Key Positions）是指一旦空缺或由不胜任者占据，就会对组织战略和业务产生重大影响的岗位。识别通常看三个维度：战略影响度（是否直接支撑核心业务与战略）、可替代性（市场是否稀缺、内部培养周期是否长）、人员风险（在岗者是否临近退休、离职风险是否高）。\n\n继任计划（Succession Planning）是系统地为关键岗位识别潜在继任者，并通过发展计划让其逐步具备接任能力的持续管理过程。它不是“提拔承诺”，而是“准备度管理”——管理“这个人离胜任岗位还有多远”，而不是“到点就升谁”。\n\n继任者评估常用“绩效 × 潜力”两维度：绩效看过去，潜力看未来。潜力通常考察学习敏锐度（能否快速从经验中学习）、成就动机与关键时刻的表现。两者结合形成九宫格（9-box）：高绩效高潜力是“明星”，值得重点投入；高绩效低潜力是“骨干”，可倚重但不必拔苗助长；低绩效高潜力则需分析原因、给改进机会。\n\n## 二、发展计划、导师制与职业发展通道\n\n识别继任者只是开始，关键是发展。继任者培养同样遵循 70-20-10：70% 靠轮岗、项目历练等在岗实践，20% 靠上级与导师的辅导反馈，10% 靠正式课程。每位继任者都应有一份书面的个人发展计划（IDP），写明目标、行动与衡量标准。\n\n导师制（Mentoring）是资深者与经验较少者之间建立的长期发展关系，重在职业引导、经验传承和组织洞察；它与侧重短期技能传授的“带教”不同，导师更像“引路人”而不是“师傅”。在莱茵科技，赵姐正是林晓的导师——每当她拿不准主意，赵姐的经验都帮她避开了不少坑。\n\n职业发展通道则是给人才“出路”。成熟企业普遍采用双通道：管理通道（主管→经理→总监）与专业通道（工程师→高级工程师→主任工程师→技术专家）并行，让不想做管理、只爱钻研技术的人也能晋升，否则只能挤“管理独木桥”。\n\n## 进阶视角：梯队建设的常见误区\n\n误区一：梯队建设 = 一份名单。只列名字不做发展，名单只是“安慰剂”，关键时刻顶不上去。误区二：把继任者当“秘密备份”，既不告知也不培养，临危受命时两败俱伤。误区三：只建管理梯队，忽视专业人才梯队——技术专家同样会退休、离职。误区四：凭感觉选人——继任评估应与任职资格、能力模型挂钩，标准透明才能服众。\n\n从投资视角看，内部培养继任者往往比外部猎头更划算：外部招聘周期长、成本高、融入风险大；内部继任者则熟悉业务、文化契合。继任计划同时是组织知识传承的机制——把个人经验转化为组织能力，这正是学习型组织的核心命题。\n\n\n## 进阶视角：人才发展与联盟契约（尤里奇 / 联盟）\n\n人才发展不只是\"培训部的课程表\"。**尤里奇**把 HR 的核心产出定义为\"个人能力 × 组织能力\"——人才培养要直接服务业务结果，而非为了培训而培训。\n\n**《联盟》（霍夫曼）**提供了新视角：把员工发展看作**联盟契约的一部分**——公司为员工投资能力（培训、导师、轮岗），员工为公司贡献关键任务（任期目标）。继任计划因此不是\"公司单方面的储备\"，而是\"双方看得见的成长路径\"：明确的职业发展通道 + 发展承诺，能显著提升人才保留率。\n\n> 启发：设计人才梯队时，除了\"公司需要谁\"，也问问\"员工想要什么样的成长\"——把发展计划变成双方共同投资的契约，人才才会留下来。\n\n<!-- 书单补强 -->\n## 案例复盘：林晓为莱茵科技“攒板凳”\n\n林晓与王总、各部门负责人一起，用“战略影响 × 可替代性 × 人员风险”矩阵盘点出 8 个关键岗位，包括产品总监、资深硬件工程师、华东区销售经理等；再用“绩效 × 潜力”九宫格为每个关键岗位筛出 1～2 名继任者：为陈工筛选出高潜产品经理小孟，安排她牵头一条新产品线的全流程，由陈工担任导师；两位资深工程师各带一名高潜新人，纳入“硬件专家培养计划”，打通专业晋升通道；公司层面推出导师制，新员工入职即配对导师。\n\n一年后，关键岗位继任者覆盖率达到 80%。老周休长假那三周，他的高潜继任者顺利顶替了技术支撑工作，产品线没有中断。王总在管理会上说：“现在我可以安心休假了。”\n\n> **对照思考：你们部门有没有“一个人走了就塌”的岗位？如果让你为它找继任者，你会考察哪些维度？**\n\n## 费曼自检\n\n合上本章，向朋友解释：关键岗位和普通岗位有什么区别？继任者评估为什么要同时看“绩效”和“潜力”？导师制和技能带教有什么区别？", "sort_order": 2}], "questions": [{"id": 64, "module_code": "recruitment", "chapter_id": 1, "category": "exam", "qtype": "single", "stem": "招聘流程的起点是？", "options": [{"key": "A", "text": "发布招聘信息"}, {"key": "B", "text": "岗位需求分析"}, {"key": "C", "text": "面试候选人"}, {"key": "D", "text": "发放Offer"}], "answer": ["B"], "explanation": "岗位需求分析是招聘全流程的起点，决定选人标准。", "knowledge_point": "岗位需求分析", "sort_order": 0}, {"id": 65, "module_code": "recruitment", "chapter_id": 1, "category": "exam", "qtype": "single", "stem": "JD 中描述「岗位的核心产出指标」的是哪部分？", "options": [{"key": "A", "text": "任职资格"}, {"key": "B", "text": "关键绩效指标"}, {"key": "C", "text": "汇报关系"}, {"key": "D", "text": "福利待遇"}], "answer": ["B"], "explanation": "关键绩效指标用于衡量岗位产出，如到岗率、招聘周期等。", "knowledge_point": "岗位说明书构成", "sort_order": 1}, {"id": 66, "module_code": "recruitment", "chapter_id": 1, "category": "exam", "qtype": "judge", "stem": "任职资格越严格，越能保证招聘到优秀人才。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "任职资格应与岗位需求匹配，过高会造成候选人池过小与人岗错配。", "knowledge_point": "任职资格匹配", "sort_order": 2}, {"id": 67, "module_code": "recruitment", "chapter_id": 2, "category": "exam", "qtype": "single", "stem": "STAR 法则中 R 代表什么？", "options": [{"key": "A", "text": "Requirement（要求）"}, {"key": "B", "text": "Result（结果）"}, {"key": "C", "text": "Review（回顾）"}, {"key": "D", "text": "Resource（资源）"}], "answer": ["B"], "explanation": "STAR = Situation、Task、Action、Result（结果）。", "knowledge_point": "STAR法则", "sort_order": 3}, {"id": 68, "module_code": "recruitment", "chapter_id": 2, "category": "exam", "qtype": "multiple", "stem": "结构化面试的优势包括？", "options": [{"key": "A", "text": "统一题目，候选人可比性强"}, {"key": "B", "text": "统一评分标准，减少主观偏差"}, {"key": "C", "text": "信度效度更高"}, {"key": "D", "text": "完全不需要面试官经验"}], "answer": ["A", "B", "C"], "explanation": "结构化面试提升信度效度，但仍需要面试官的专业追问与判断能力。", "knowledge_point": "结构化面试", "sort_order": 4}, {"id": 69, "module_code": "recruitment", "chapter_id": 2, "category": "exam", "qtype": "single", "stem": "因候选人最后一个问题回答出色而给出高分，属于？", "options": [{"key": "A", "text": "首因效应"}, {"key": "B", "text": "近因效应"}, {"key": "C", "text": "光环效应"}, {"key": "D", "text": "刻板印象"}], "answer": ["B"], "explanation": "近因效应指被面试末尾的表现所影响，应全程记录、综合评估。", "knowledge_point": "面试认知偏差", "sort_order": 5}, {"id": 70, "module_code": "recruitment", "chapter_id": 2, "category": "exam", "qtype": "single", "stem": "行为面试中，听到「我沟通能力很强」这类概括性回答时应？", "options": [{"key": "A", "text": "记录优点"}, {"key": "B", "text": "用 STAR 追问具体事例"}, {"key": "C", "text": "直接判定不合格"}, {"key": "D", "text": "换下一个问题"}], "answer": ["B"], "explanation": "必须追问具体情境与行为，以事实证据判断能力。", "knowledge_point": "行为面试与STAR追问", "sort_order": 6}, {"id": 71, "module_code": "recruitment", "chapter_id": 3, "category": "exam", "qtype": "single", "stem": "录用决策中，背景调查的目的是？", "options": [{"key": "A", "text": "验证候选人的关键经历与表现"}, {"key": "B", "text": "降低薪资报价"}, {"key": "C", "text": "了解候选人的家庭情况"}, {"key": "D", "text": "拖延招聘进度"}], "answer": ["A"], "explanation": "背景调查核实工作经历、职位与表现，降低录用风险。", "knowledge_point": "背景调查", "sort_order": 7}, {"id": 72, "module_code": "recruitment", "chapter_id": 3, "category": "exam", "qtype": "single", "stem": "多维度评估中，专业能力通常占多少权重比较合理？", "options": [{"key": "A", "text": "10%"}, {"key": "B", "text": "20%"}, {"key": "C", "text": "40%"}, {"key": "D", "text": "90%"}], "answer": ["C"], "explanation": "专业能力是岗位胜任的核心，通常占 35%-50%，并搭配经验、素质与动机维度。", "knowledge_point": "评估维度与权重", "sort_order": 8}, {"id": 73, "module_code": "recruitment", "chapter_id": 3, "category": "exam", "qtype": "judge", "stem": "书面 Offer 应包含岗位、薪资、入职时间等关键条款。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "书面 Offer 明确关键条款可避免入职前后争议，保护双方权益。", "knowledge_point": "Offer与录用决策", "sort_order": 9}, {"id": 84, "module_code": "recruitment", "chapter_id": 4, "category": "exam", "qtype": "single", "stem": "人才规划四步法中，\"识别关键岗位的数量与能力缺口\"属于哪一步？", "options": [{"key": "A", "text": "人才盘点"}, {"key": "B", "text": "供需预测"}, {"key": "C", "text": "差距分析"}, {"key": "D", "text": "行动计划"}], "answer": ["C"], "explanation": "差距分析在盘点和预测之后，识别关键岗位的数量与能力缺口。", "knowledge_point": "人才规划四步法", "sort_order": 10}, {"id": 85, "module_code": "recruitment", "chapter_id": 5, "category": "exam", "qtype": "single", "stem": "奈飞\"高人才密度\"理念对招聘标准的启示是？", "options": [{"key": "A", "text": "宁可慢一点、贵一点，也要招对的人"}, {"key": "B", "text": "尽快招人填满岗位最重要"}, {"key": "C", "text": "降低标准扩大候选人池"}, {"key": "D", "text": "招聘标准与人才密度无关"}], "answer": ["A"], "explanation": "高人才密度要求招聘标准宁高勿低，避免平庸者稀释团队标准。", "knowledge_point": "高人才密度", "sort_order": 11}, {"id": 86, "module_code": "recruitment", "chapter_id": 5, "category": "exam", "qtype": "single", "stem": "《联盟》一书建议招聘沟通中加入\"任期计划\"，其目的是？", "options": [{"key": "A", "text": "明确本轮合作中公司与员工各自的目标与回报"}, {"key": "B", "text": "强制员工服务固定年限"}, {"key": "C", "text": "避免支付培训费用"}, {"key": "D", "text": "替代绩效考核"}], "answer": ["A"], "explanation": "任期计划管理双方期望，让雇佣关系成为目标明确的联盟合作。", "knowledge_point": "任期制", "sort_order": 12}, {"id": 87, "module_code": "recruitment", "chapter_id": 5, "category": "exam", "qtype": "multiple", "stem": "用数据驱动招聘决策的做法包括？", "options": [{"key": "A", "text": "记录面试评分与新人绩效以校准标准"}, {"key": "B", "text": "用元分析结论选择面试方法"}, {"key": "C", "text": "定期复盘招聘周期与Offer接受率"}, {"key": "D", "text": "完全凭面试官直觉决策"}], "answer": ["A", "B", "C"], "explanation": "数据驱动要求记录、验证、复盘招聘各环节；凭直觉决策正是要避免的。", "knowledge_point": "数据驱动招聘", "sort_order": 13}, {"id": 88, "module_code": "recruitment", "chapter_id": 5, "category": "exam", "qtype": "single", "stem": "员工价值主张（EVP）在招聘中的作用是？", "options": [{"key": "A", "text": "向候选人传递公司独特价值，吸引匹配的人才"}, {"key": "B", "text": "设定候选人薪资上限"}, {"key": "C", "text": "评估候选人性格"}, {"key": "D", "text": "计算招聘成本"}], "answer": ["A"], "explanation": "EVP 是雇主品牌的核心，用于吸引与公司价值匹配的候选人。", "knowledge_point": "EVP雇主品牌", "sort_order": 14}, {"id": 99, "module_code": "recruitment", "chapter_id": 1, "category": "exam_case", "qtype": "single", "stem": "【案例】陈工说\"招几个能干的人\"但提不出标准，林晓应该用哪套流程把需求落地为可执行的 JD？", "options": [{"key": "A", "text": "工作分析（目标梳理→关键任务→访谈在岗优秀员工→行为化任职资格）"}, {"key": "B", "text": "直接参考同行 JD 改写"}, {"key": "C", "text": "按候选人简历反向定制 JD"}, {"key": "D", "text": "先招进来试用再定标准"}], "answer": ["A"], "explanation": "案例中林晓正是通过工作分析产出扎实的 JD，把\"能干的人\"变成可执行的招聘标准。", "knowledge_point": "岗位需求分析", "sort_order": 100}, {"id": 100, "module_code": "recruitment", "chapter_id": 2, "category": "exam_case", "qtype": "single", "stem": "【案例】\"聊得来\"但 STAR 追问给不出行为细节的候选人，最终被结构化评分表筛掉。这说明面试评估应依赖什么？", "options": [{"key": "A", "text": "可观察的行为证据与统一评分标准"}, {"key": "B", "text": "面试官的第一印象"}, {"key": "C", "text": "候选人的谈吐与幽默感"}, {"key": "D", "text": "面试时长"}], "answer": ["A"], "explanation": "结构化面试以行为证据和统一标准为评估依据，避免主观印象偏差（案例中评分表替团队做了决定）。", "knowledge_point": "结构化面试与行为证据", "sort_order": 101}, {"id": 101, "module_code": "recruitment", "chapter_id": 5, "category": "exam_case", "qtype": "single", "stem": "【案例】何工因薪资低 15% 犹豫，林晓用 EVP 和任期计划打动了他。这体现了招聘中的什么理念？", "options": [{"key": "A", "text": "雇主品牌与人才契约（联盟任期制）"}, {"key": "B", "text": "以最高薪资取胜"}, {"key": "C", "text": "压低薪资试探底线"}, {"key": "D", "text": "降低招聘标准"}], "answer": ["A"], "explanation": "EVP 传递独特价值，任期计划管理双方期望——候选人被\"看得见下一步\"的契约吸引（《联盟》观点）。", "knowledge_point": "EVP与任期制", "sort_order": 102}, {"id": 1, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "招聘流程的起点通常是什么？", "options": [{"key": "A", "text": "发布招聘广告"}, {"key": "B", "text": "岗位需求分析"}, {"key": "C", "text": "筛选简历"}, {"key": "D", "text": "安排面试"}], "answer": ["B"], "explanation": "招聘应从岗位需求分析开始，明确岗位职责、任职资格与用人标准，才能精准选人。", "knowledge_point": "", "sort_order": 0}, {"id": 2, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "JD（岗位说明书）中「任职资格」主要描述什么？", "options": [{"key": "A", "text": "岗位的汇报关系"}, {"key": "B", "text": "候选人应具备的知识、技能与经验要求"}, {"key": "C", "text": "岗位的薪资范围"}, {"key": "D", "text": "部门的组织架构"}], "answer": ["B"], "explanation": "任职资格描述的是胜任该岗位所需的教育背景、工作经验、专业技能与能力素质。", "knowledge_point": "", "sort_order": 1}, {"id": 3, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "行为面试法中 STAR 原则的 S 代表什么？", "options": [{"key": "A", "text": "Skill（技能）"}, {"key": "B", "text": "Situation（情境）"}, {"key": "C", "text": "Score（评分）"}, {"key": "D", "text": "Standard（标准）"}], "answer": ["B"], "explanation": "STAR 即 Situation（情境）、Task（任务）、Action（行动）、Result（结果），用于还原候选人的真实行为。", "knowledge_point": "", "sort_order": 2}, {"id": 4, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "judge", "stem": "结构化面试对所有候选人使用相同的题目和评分标准，信度更高。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "结构化面试的标准化题目与评分维度能显著提高面试的信度和效度，减少主观偏差。", "knowledge_point": "", "sort_order": 3}, {"id": 5, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "做出录用决策前，一般还应完成哪项工作？", "options": [{"key": "A", "text": "背景调查"}, {"key": "B", "text": "延长试用期"}, {"key": "C", "text": "降低薪资"}, {"key": "D", "text": "发布二次招聘"}], "answer": ["A"], "explanation": "背景调查可核实候选人的工作经历与表现，是录用决策前的重要风控环节。", "knowledge_point": "", "sort_order": 4}, {"id": 6, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "简历筛选的第一步通常是什么？", "options": [{"key": "A", "text": "按岗位任职资格进行硬性条件初筛"}, {"key": "B", "text": "直接约面试"}, {"key": "C", "text": "做性格测试"}, {"key": "D", "text": "背景调查"}], "answer": ["A"], "explanation": "简历筛选先按任职资格的硬性条件（学历、经验、证书）快速初筛，再做深度评估。", "knowledge_point": "", "sort_order": 5}, {"id": 7, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "电话邀约候选人面试时，应确认哪些信息？", "options": [{"key": "A", "text": "面试时间与地点"}, {"key": "B", "text": "需携带的证件材料"}, {"key": "C", "text": "候选人的薪资期望"}, {"key": "D", "text": "面试官的个人履历"}], "answer": ["A", "B", "C"], "explanation": "邀约需确认时间地点、携带材料，并可在电话中初步了解薪资期望；面试官履历与候选人无关。", "knowledge_point": "", "sort_order": 6}, {"id": 8, "module_code": "recruitment", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "面试结束后，建议在多长时间内完成评估记录？", "options": [{"key": "A", "text": "24 小时内"}, {"key": "B", "text": "一周内"}, {"key": "C", "text": "一个月内"}, {"key": "D", "text": "不必记录"}], "answer": ["A"], "explanation": "趁面试印象新鲜及时记录评估，可减少记忆偏差（近因效应），提高评估准确性。", "knowledge_point": "", "sort_order": 7}, {"id": 49, "module_code": "recruitment", "chapter_id": 1, "category": "practice", "qtype": "single", "stem": "岗位需求分析的主要产出是什么？", "options": [{"key": "A", "text": "一份完善的岗位说明书（JD）"}, {"key": "B", "text": "一份招聘广告"}, {"key": "C", "text": "候选人的面试评估表"}, {"key": "D", "text": "公司组织架构图"}], "answer": ["A"], "explanation": "需求分析的最终产出是明确的岗位说明书，包含职责、任职资格与能力要求。", "knowledge_point": "岗位需求分析", "sort_order": 0}, {"id": 54, "module_code": "recruitment", "chapter_id": 2, "category": "practice", "qtype": "single", "stem": "STAR 法则中，T 代表什么？", "options": [{"key": "A", "text": "Time（时间）"}, {"key": "B", "text": "Task（任务）"}, {"key": "C", "text": "Team（团队）"}, {"key": "D", "text": "Target（目标）"}], "answer": ["B"], "explanation": "STAR = Situation（情境）、Task（任务）、Action（行动）、Result（结果）。", "knowledge_point": "结构化面试", "sort_order": 0}, {"id": 59, "module_code": "recruitment", "chapter_id": 3, "category": "practice", "qtype": "single", "stem": "录用决策中最忌讳的做法是？", "options": [{"key": "A", "text": "多面试官讨论"}, {"key": "B", "text": "凭面试官个人感觉直接拍板"}, {"key": "C", "text": "按评分表逐项评估"}, {"key": "D", "text": "进行背景调查"}], "answer": ["B"], "explanation": "凭感觉拍板缺乏客观依据，容易受主观偏差影响，应依据评分表与多维度证据决策。", "knowledge_point": "面试评估与录用决策", "sort_order": 0}, {"id": 74, "module_code": "recruitment", "chapter_id": 4, "category": "practice", "qtype": "single", "stem": "战略性招聘与战术招聘的本质区别是？", "options": [{"key": "A", "text": "战略性招聘服务于组织战略，人才获取本身是竞争优势"}, {"key": "B", "text": "战略性招聘渠道更多"}, {"key": "C", "text": "战术招聘成本更低"}, {"key": "D", "text": "没有区别"}], "answer": ["A"], "explanation": "战略招聘把人才获取与组织战略绑定，视人才能力为竞争优势来源（诺伊观点）。", "knowledge_point": "战略性招聘与人才规划", "sort_order": 0}, {"id": 79, "module_code": "recruitment", "chapter_id": 5, "category": "practice", "qtype": "single", "stem": "员工价值主张（EVP）是指？", "options": [{"key": "A", "text": "公司向员工提供的独特价值总和（薪酬、发展、文化等）"}, {"key": "B", "text": "员工的薪资要求"}, {"key": "C", "text": "公司的利润指标"}, {"key": "D", "text": "候选人的简历亮点"}], "answer": ["A"], "explanation": "EVP 是公司向员工提供的独特价值组合，是雇主品牌的核心内容。", "knowledge_point": "雇主品牌与人才契约", "sort_order": 0}, {"id": 50, "module_code": "recruitment", "chapter_id": 1, "category": "practice", "qtype": "multiple", "stem": "下列哪些属于岗位说明书（JD）的构成要素？", "options": [{"key": "A", "text": "岗位职责"}, {"key": "B", "text": "任职资格"}, {"key": "C", "text": "汇报关系"}, {"key": "D", "text": "候选人星座"}], "answer": ["A", "B", "C"], "explanation": "JD 通常包含职责、任职资格、能力素质、汇报关系与关键绩效；星座与岗位无关。", "knowledge_point": "岗位需求分析", "sort_order": 1}, {"id": 55, "module_code": "recruitment", "chapter_id": 2, "category": "practice", "qtype": "single", "stem": "候选人回答“我负责协调项目进度”时，面试官最应该？", "options": [{"key": "A", "text": "相信候选人的能力"}, {"key": "B", "text": "用 STAR 追问具体行为细节"}, {"key": "C", "text": "立即进入下一个问题"}, {"key": "D", "text": "打断并指出不足"}], "answer": ["B"], "explanation": "概括性回答需用 STAR 追问细节，通过具体行为判断真实能力。", "knowledge_point": "结构化面试", "sort_order": 1}, {"id": 60, "module_code": "recruitment", "chapter_id": 3, "category": "practice", "qtype": "single", "stem": "背景调查一般安排在什么时候进行？", "options": [{"key": "A", "text": "简历筛选阶段"}, {"key": "B", "text": "对所有候选人进行"}, {"key": "C", "text": "确定拟录用对象后"}, {"key": "D", "text": "入职一年后"}], "answer": ["C"], "explanation": "背景调查通常仅对拟录用候选人进行，以控制成本并保护候选人隐私。", "knowledge_point": "面试评估与录用决策", "sort_order": 1}, {"id": 75, "module_code": "recruitment", "chapter_id": 4, "category": "practice", "qtype": "single", "stem": "人才规划四步法的正确顺序是？", "options": [{"key": "A", "text": "人才盘点→供需预测→差距分析→行动计划"}, {"key": "B", "text": "行动计划→盘点→预测→差距"}, {"key": "C", "text": "预测→盘点→行动→差距"}, {"key": "D", "text": "差距→盘点→预测→行动"}], "answer": ["A"], "explanation": "先盘点现状，再预测供需，识别差距，最后制定行动计划。", "knowledge_point": "战略性招聘与人才规划", "sort_order": 1}, {"id": 80, "module_code": "recruitment", "chapter_id": 5, "category": "practice", "qtype": "single", "stem": "奈飞\"高人才密度\"理念的核心逻辑是？", "options": [{"key": "A", "text": "顶级人才产出更高且提升团队整体标准"}, {"key": "B", "text": "多招人可以降低成本"}, {"key": "C", "text": "人才越多越好，不论水平"}, {"key": "D", "text": "只招聘应届生"}], "answer": ["A"], "explanation": "高人才密度认为 A 类人才的产出数倍于平庸者，并带动团队标准提升。", "knowledge_point": "雇主品牌与人才契约", "sort_order": 1}, {"id": 51, "module_code": "recruitment", "chapter_id": 1, "category": "practice", "qtype": "judge", "stem": "任职资格写得越高越好，可以吸引更优秀的人才。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "任职资格应与岗位实际需求匹配，过高会导致候选人池过小、人岗错配。", "knowledge_point": "岗位需求分析", "sort_order": 2}, {"id": 56, "module_code": "recruitment", "chapter_id": 2, "category": "practice", "qtype": "judge", "stem": "结构化面试要求所有候选人回答相同的核心问题，以保证可比性。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "统一题目与统一评分标准是结构化面试的核心特征，保证候选人之间的公平可比。", "knowledge_point": "结构化面试", "sort_order": 2}, {"id": 61, "module_code": "recruitment", "chapter_id": 3, "category": "practice", "qtype": "multiple", "stem": "常见的面试评估维度包括？", "options": [{"key": "A", "text": "专业能力"}, {"key": "B", "text": "工作经验"}, {"key": "C", "text": "综合素质"}, {"key": "D", "text": "动机与价值观"}], "answer": ["A", "B", "C", "D"], "explanation": "评估通常覆盖专业、经验、素质与动机价值观四个维度，并按权重综合评分。", "knowledge_point": "面试评估与录用决策", "sort_order": 2}, {"id": 76, "module_code": "recruitment", "chapter_id": 4, "category": "practice", "qtype": "multiple", "stem": "下列哪些属于招聘效果的关键度量指标？", "options": [{"key": "A", "text": "招聘周期（Time to Fill）"}, {"key": "B", "text": "Offer 接受率"}, {"key": "C", "text": "试用期通过率"}, {"key": "D", "text": "单位招聘成本"}], "answer": ["A", "B", "C", "D"], "explanation": "招聘周期、Offer接受率、试用期通过率、单位成本都是衡量招聘效率与质量的核心指标。", "knowledge_point": "战略性招聘与人才规划", "sort_order": 2}, {"id": 81, "module_code": "recruitment", "chapter_id": 5, "category": "practice", "qtype": "single", "stem": "《联盟》一书提出的\"任期制\"（Tour of Duty）是指？", "options": [{"key": "A", "text": "录用时明确本轮合作双方的目标与回报"}, {"key": "B", "text": "员工必须工作满固定年限"}, {"key": "C", "text": "终身雇佣制度"}, {"key": "D", "text": "只签短期合同"}], "answer": ["A"], "explanation": "任期制把雇佣看作有明确目标与回报的联盟合作，管理双方期望。", "knowledge_point": "雇主品牌与人才契约", "sort_order": 2}, {"id": 52, "module_code": "recruitment", "chapter_id": 1, "category": "practice", "qtype": "single", "stem": "下列哪种方法适合梳理一个全新岗位的关键任务？", "options": [{"key": "A", "text": "访谈该岗位的在岗优秀员工"}, {"key": "B", "text": "直接复制竞争对手的JD"}, {"key": "C", "text": "凭HR个人经验编写"}, {"key": "D", "text": "让老板随意指定"}], "answer": ["A"], "explanation": "访谈在岗优秀员工（工作分析法）能获取真实的关键任务与能力要求。", "knowledge_point": "岗位需求分析", "sort_order": 3}, {"id": 57, "module_code": "recruitment", "chapter_id": 2, "category": "practice", "qtype": "single", "stem": "因候选人形象气质好而高估其能力，属于哪种面试偏差？", "options": [{"key": "A", "text": "首因效应"}, {"key": "B", "text": "光环效应"}, {"key": "C", "text": "近因效应"}, {"key": "D", "text": "从众效应"}], "answer": ["B"], "explanation": "光环效应指因某一突出特质（如形象）而影响对其他维度的客观评价。", "knowledge_point": "结构化面试", "sort_order": 3}, {"id": 62, "module_code": "recruitment", "chapter_id": 3, "category": "practice", "qtype": "judge", "stem": "面试评估会议应尽快召开，趁面试官对候选人的印象还新鲜。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "尽快召开评估会议可减少近因效应与记忆衰减，提高评估准确性。", "knowledge_point": "面试评估与录用决策", "sort_order": 3}, {"id": 77, "module_code": "recruitment", "chapter_id": 4, "category": "practice", "qtype": "judge", "stem": "内部招聘比外部招聘成本低、上手快，因此所有岗位都应优先内部招聘。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "内部招聘有优势，但外部招聘能引入新视角与稀缺技能，渠道应结合岗位层级与稀缺度组合选择。", "knowledge_point": "战略性招聘与人才规划", "sort_order": 3}, {"id": 82, "module_code": "recruitment", "chapter_id": 5, "category": "practice", "qtype": "judge", "stem": "根据《重新定义团队》，结构化面试比非结构化面试对工作绩效的预测更准确，且有数据研究支撑。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "Schmidt & Hunter 元分析显示结构化面试预测效度显著更高，Google 也以此实践。", "knowledge_point": "雇主品牌与人才契约", "sort_order": 3}, {"id": 53, "module_code": "recruitment", "chapter_id": 1, "category": "practice", "qtype": "single", "stem": "「每月到岗率 ≥ 90%」属于 JD 中的哪一类要素？", "options": [{"key": "A", "text": "岗位职责"}, {"key": "B", "text": "任职资格"}, {"key": "C", "text": "关键绩效指标"}, {"key": "D", "text": "汇报关系"}], "answer": ["C"], "explanation": "关键绩效是衡量岗位产出成果的量化指标，如到岗率、招聘周期等。", "knowledge_point": "岗位需求分析", "sort_order": 4}, {"id": 58, "module_code": "recruitment", "chapter_id": 2, "category": "practice", "qtype": "multiple", "stem": "面试中常采用的行为面试题应包含哪些要素？", "options": [{"key": "A", "text": "过去的真实经历"}, {"key": "B", "text": "具体的情境描述"}, {"key": "C", "text": "候选人的具体行动"}, {"key": "D", "text": "可验证的结果"}], "answer": ["A", "B", "C", "D"], "explanation": "行为面试题以候选人过去的具体行为（情境-任务-行动-结果）为评估依据。", "knowledge_point": "结构化面试", "sort_order": 4}, {"id": 63, "module_code": "recruitment", "chapter_id": 3, "category": "practice", "qtype": "single", "stem": "关于 Offer，正确的做法是？", "options": [{"key": "A", "text": "口头承诺即可，不必书面"}, {"key": "B", "text": "书面 Offer 明确岗位、薪资与入职时间等关键条款"}, {"key": "C", "text": "先让候选人入职再谈薪资"}, {"key": "D", "text": "Offer 内容无需与面试沟通一致"}], "answer": ["B"], "explanation": "书面 Offer 应明确岗位、薪资结构、入职时间与录用条件，避免入职后争议。", "knowledge_point": "面试评估与录用决策", "sort_order": 4}, {"id": 78, "module_code": "recruitment", "chapter_id": 4, "category": "practice", "qtype": "single", "stem": "企业高管与稀缺技术人才通常更适合哪种招聘渠道？", "options": [{"key": "A", "text": "内部推荐与猎头寻访"}, {"key": "B", "text": "招聘网站海投"}, {"key": "C", "text": "校园招聘"}, {"key": "D", "text": "劳务派遣"}], "answer": ["A"], "explanation": "高管与稀缺人才需要精准寻访，内部推荐与猎头是主流渠道。", "knowledge_point": "战略性招聘与人才规划", "sort_order": 4}, {"id": 83, "module_code": "recruitment", "chapter_id": 5, "category": "practice", "qtype": "multiple", "stem": "打造雇主品牌通常需要从哪些方面发力？", "options": [{"key": "A", "text": "明确员工价值主张（EVP）"}, {"key": "B", "text": "招聘体验与候选人沟通"}, {"key": "C", "text": "在职员工体验与口碑"}, {"key": "D", "text": "只靠高薪吸引"}], "answer": ["A", "B", "C"], "explanation": "雇主品牌 = 价值主张 + 招聘体验 + 员工口碑的综合建设，高薪只是其中一环。", "knowledge_point": "雇主品牌与人才契约", "sort_order": 4}, {"id": 89, "module_code": "recruitment", "chapter_id": 1, "category": "practice_case", "qtype": "single", "stem": "【案例】陈工对林晓说“帮我招几个能干的人”，林晓最应该做的第一步是？", "options": [{"key": "A", "text": "立即发布招聘广告，扩大简历量"}, {"key": "B", "text": "与陈工做工作分析，梳理岗位职责与任职资格"}, {"key": "C", "text": "先面试几个候选人再定标准"}, {"key": "D", "text": "直接复制同行公司的 JD"}], "answer": ["B"], "explanation": "案例中林晓正是先做工作分析（目标梳理、关键任务、访谈在岗优秀员工），才产出扎实的 JD——先定标准，再找对人。", "knowledge_point": "岗位需求分析", "sort_order": 100}, {"id": 91, "module_code": "recruitment", "chapter_id": 2, "category": "practice_case", "qtype": "single", "stem": "【案例】面对那位\"聊得来\"但给不出具体行为细节的候选人，林晓最应该怎么做？", "options": [{"key": "A", "text": "相信第一印象，聊得好就是能力强"}, {"key": "B", "text": "用 STAR 法则追问具体情境与行动"}, {"key": "C", "text": "直接结束面试并标记不合格"}, {"key": "D", "text": "让技术面试官替他回答"}], "answer": ["B"], "explanation": "案例中林晓用 STAR 逐一追问，候选人停留在\"我很强\"的概括层——没有具体行为的回答不能作为评估依据。", "knowledge_point": "结构化面试", "sort_order": 100}, {"id": 93, "module_code": "recruitment", "chapter_id": 3, "category": "practice_case", "qtype": "single", "stem": "【案例】评估会议上，A 候选人专业最强但动机维度低，B 候选人均衡且匹配度高，林晓正确的处理方式是？", "options": [{"key": "A", "text": "专业最强就选 A，其他维度不重要"}, {"key": "B", "text": "核对各维度评分表的证据，集体决策"}, {"key": "C", "text": "让嗓门最大的面试官拍板"}, {"key": "D", "text": "两个都录用，试用期再淘汰"}], "answer": ["B"], "explanation": "案例中林晓主持的评估会议只做一件事——核对多维度评分表中的证据，最终依据证据与共识决策。", "knowledge_point": "面试评估与录用决策", "sort_order": 100}, {"id": 95, "module_code": "recruitment", "chapter_id": 4, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技每个季度都\"缺人现招\"，林晓要回答王总\"我们是不是永远在缺人\"，她首先应该做什么？", "options": [{"key": "A", "text": "加大招聘广告投放，加快补坑"}, {"key": "B", "text": "启动人才盘点与供需预测，找出缺口根因"}, {"key": "C", "text": "把招聘全部外包给猎头"}, {"key": "D", "text": "降低用人标准，尽快到岗"}], "answer": ["B"], "explanation": "案例中林晓通过人才规划四步法（盘点→预测→差距→行动）找到了根因——问题在供需管理，而不只是招聘速度。", "knowledge_point": "战略性招聘与人才规划", "sort_order": 100}, {"id": 97, "module_code": "recruitment", "chapter_id": 5, "category": "practice_case", "qtype": "single", "stem": "【案例】何工因对方薪水高出 15% 而犹豫，林晓最有效的应对是？", "options": [{"key": "A", "text": "直接加薪 20% 压过对手"}, {"key": "B", "text": "讲清 EVP（战略产品线、高人才密度）并给出书面任期计划"}, {"key": "C", "text": "许诺升职但无书面承诺"}, {"key": "D", "text": "不再争取，放走候选人"}], "answer": ["B"], "explanation": "案例中林晓用 EVP + 任期计划打动何工——候选人在意的不仅是薪水，更是价值主张与看得见的成长。", "knowledge_point": "雇主品牌与人才契约", "sort_order": 100}, {"id": 90, "module_code": "recruitment", "chapter_id": 1, "category": "practice_case", "qtype": "judge", "stem": "【案例】林晓访谈两位在岗优秀硬件工程师，提炼\"能在资源受限时独立推进调试\"这样的行为化任职资格，这种做法是科学的。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "访谈在岗优秀员工提炼行为化任职资格，正是工作分析法的科学应用（德斯勒框架）。", "knowledge_point": "岗位需求分析", "sort_order": 101}, {"id": 92, "module_code": "recruitment", "chapter_id": 2, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓为所有候选人使用同一套面试题和统一评分表，体现了结构化面试的哪个特征？", "options": [{"key": "A", "text": "标准化：统一题目、统一评分标准"}, {"key": "B", "text": "随意性：面试官自由发挥"}, {"key": "C", "text": "高效性：缩短面试时间"}, {"key": "D", "text": "社交性：营造轻松氛围"}], "answer": ["A"], "explanation": "统一题目与统一评分标准是结构化面试的核心特征，保证候选人可比、评分客观。", "knowledge_point": "结构化面试", "sort_order": 101}, {"id": 94, "module_code": "recruitment", "chapter_id": 3, "category": "practice_case", "qtype": "judge", "stem": "【案例】对拟录用的 B 候选人先做背景调查、确认经历属实后再发放 Offer，是录用决策中的必要风控环节。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "背景调查核实候选人的关键经历，是录用决策前的重要风控环节，案例中林晓正是如此操作。", "knowledge_point": "面试评估与录用决策", "sort_order": 101}, {"id": 96, "module_code": "recruitment", "chapter_id": 4, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓发现内推渠道贡献了 60% 的优质简历却被长期忽视，她合理的应对措施是？", "options": [{"key": "A", "text": "把内推制度化：推荐奖励 + 透明流程"}, {"key": "B", "text": "认为内推是巧合，继续用单一渠道"}, {"key": "C", "text": "取消内推，全部走外部招聘"}, {"key": "D", "text": "只依赖猎头渠道"}], "answer": ["A"], "explanation": "数据（60%优质简历）说明内推是高质量渠道，制度化运营能稳定放大这一优势。", "knowledge_point": "战略性招聘与人才规划", "sort_order": 101}, {"id": 98, "module_code": "recruitment", "chapter_id": 5, "category": "practice_case", "qtype": "judge", "stem": "【案例】林晓向何工提供书面任期计划（本轮合作公司的目标、何工的成长路径），有助于管理双方预期、降低人岗错配。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "任期计划明确本轮合作的目标与回报，是联盟式雇佣关系的核心工具（《联盟》观点）。", "knowledge_point": "雇主品牌与人才契约", "sort_order": 101}, {"id": 188, "module_code": "labor-law", "chapter_id": 12, "category": "exam", "qtype": "single", "stem": "用人单位自用工之日起满一年未与劳动者订立书面劳动合同，法律后果是？", "options": [{"key": "A", "text": "视为已订立无固定期限劳动合同"}, {"key": "B", "text": "劳动关系自动终止"}, {"key": "C", "text": "只需补签，没有任何其他后果"}, {"key": "D", "text": "应当支付三倍工资"}], "answer": ["A"], "explanation": "《劳动合同法》第十四条第三款：满一年未订立书面合同的，视为已订立无固定期限劳动合同，并应立即补订书面合同。", "knowledge_point": "未签书面劳动合同的后果", "sort_order": 0}, {"id": 189, "module_code": "labor-law", "chapter_id": 12, "category": "exam", "qtype": "single", "stem": "劳动合同期限为三年以上固定期限或无固定期限的，试用期最长不得超过多久？", "options": [{"key": "A", "text": "1 个月"}, {"key": "B", "text": "2 个月"}, {"key": "C", "text": "6 个月"}, {"key": "D", "text": "12 个月"}], "answer": ["C"], "explanation": "《劳动合同法》第十九条：三年以上固定期限或无固定期限合同，试用期最长不得超过 6 个月。", "knowledge_point": "试用期长度规则", "sort_order": 1}, {"id": 190, "module_code": "labor-law", "chapter_id": 13, "category": "exam", "qtype": "single", "stem": "因特殊原因需要延长工作时间，在保障劳动者身体健康的条件下，每月加班累计不得超过多少小时？", "options": [{"key": "A", "text": "24 小时"}, {"key": "B", "text": "32 小时"}, {"key": "C", "text": "36 小时"}, {"key": "D", "text": "40 小时"}], "answer": ["C"], "explanation": "《劳动法》第四十一条：特殊原因下每日不得超过 3 小时，每月累计不得超过 36 小时——这是加班的法定上限红线。", "knowledge_point": "加班时长上限", "sort_order": 2}, {"id": 191, "module_code": "labor-law", "chapter_id": 13, "category": "exam", "qtype": "multiple", "stem": "下列关于加班费标准的说法，正确的有？", "options": [{"key": "A", "text": "工作日延长工作时间的，支付不低于工资 150% 的报酬"}, {"key": "B", "text": "休息日安排工作又不能安排补休的，支付不低于工资 200% 的报酬"}, {"key": "C", "text": "法定休假日安排工作的，支付不低于工资 300% 的报酬"}, {"key": "D", "text": "法定节假日加班可以用补休替代支付"}], "answer": ["A", "B", "C"], "explanation": "《劳动法》第四十四条三档标准：150%/200%/300%；法定节假日加班不能以补休替代（D 错）。", "knowledge_point": "加班费标准", "sort_order": 3}, {"id": 192, "module_code": "labor-law", "chapter_id": 13, "category": "exam", "qtype": "single", "stem": "劳动者累计工作满 10 年不满 20 年的，带薪年休假为多少天？", "options": [{"key": "A", "text": "5 天"}, {"key": "B", "text": "10 天"}, {"key": "C", "text": "15 天"}, {"key": "D", "text": "20 天"}], "answer": ["B"], "explanation": "《职工带薪年休假条例》：满 1 年不满 10 年为 5 天，满 10 年不满 20 年为 10 天，满 20 年为 15 天。", "knowledge_point": "带薪年休假天数", "sort_order": 4}, {"id": 193, "module_code": "labor-law", "chapter_id": 14, "category": "exam", "qtype": "single", "stem": "劳动者月工资高于当地上年度职工月平均工资三倍的，经济补偿的月工资标准如何计算？", "options": [{"key": "A", "text": "按实际工资计算，年限不限"}, {"key": "B", "text": "按当地上年度职工月平均工资三倍封顶，支付年限最高不超过 12 年"}, {"key": "C", "text": "按二倍工资计算"}, {"key": "D", "text": "按最低工资标准计算"}], "answer": ["B"], "explanation": "《劳动合同法》第四十七条：高薪人员经济补偿按当地上年度职工月平均工资三倍封顶，且年限最高不超过 12 年。", "knowledge_point": "经济补偿计算（高薪封顶）", "sort_order": 5}, {"id": 194, "module_code": "labor-law", "chapter_id": 14, "category": "exam", "qtype": "judge", "stem": "用人单位违法解除或者终止劳动合同，应当依照经济补偿标准的二倍向劳动者支付赔偿金。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "《劳动合同法》第八十七条：违法解除或终止的，按经济补偿标准的二倍支付赔偿金（即 2N）。", "knowledge_point": "违法解除赔偿金（2N）", "sort_order": 6}, {"id": 195, "module_code": "labor-law", "chapter_id": 14, "category": "exam", "qtype": "single", "stem": "劳动者与用人单位发生劳动争议，申请劳动仲裁的时效期间为？", "options": [{"key": "A", "text": "自权利被侵害之日起 6 个月"}, {"key": "B", "text": "自知道或者应当知道其权利被侵害之日起 1 年内"}, {"key": "C", "text": "2 年"}, {"key": "D", "text": "3 年"}], "answer": ["B"], "explanation": "《劳动争议调解仲裁法》第二十七条：劳动争议申请仲裁的时效期间为 1 年，自当事人知道或者应当知道其权利被侵害之日起计算。", "knowledge_point": "劳动争议仲裁时效", "sort_order": 7}, {"id": 279, "module_code": "labor-law", "chapter_id": 12, "category": "exam", "qtype": "single", "stem": "关于试用期的约定，符合《劳动合同法》规定的是？", "options": [{"key": "A", "text": "同一用人单位与同一劳动者只能约定一次试用期"}, {"key": "B", "text": "以完成一定工作任务为期限的劳动合同可以约定试用期"}, {"key": "C", "text": "劳动合同期限不满三个月的，可以约定不超过一个月的试用期"}, {"key": "D", "text": "劳动合同仅约定试用期的，试用期不成立，该劳动合同自始无效"}], "answer": ["A"], "explanation": "依据《劳动合同法》第十九条：同一用人单位与同一劳动者只能约定一次试用期，A 正确；以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期，B、C 错误；劳动合同仅约定试用期的，试用期不成立，该期限视为劳动合同期限（劳动合同并非自始无效，双方劳动关系自用工之日起建立），D 错误。补充：试用期长短受合同期限约束，如合同期限三个月以上不满一年的，试用期不得超过一个月；一年以上不满三年的，不得超过两个月；三年以上固定期限及无固定期限的，不得超过六个月。", "knowledge_point": "试用期规则", "sort_order": 8}, {"id": 280, "module_code": "labor-law", "chapter_id": 13, "category": "exam", "qtype": "single", "stem": "关于工时制度与加班管理，符合现行劳动法律法规的是？", "options": [{"key": "A", "text": "用人单位安排劳动者延长工作时间，一般每日不得超过 1 小时；因特殊原因需要延长的，在保障劳动者身体健康的条件下每日不得超过 3 小时，且每月不得超过 36 小时"}, {"key": "B", "text": "休息日安排劳动者工作又不能安排补休的，应支付不低于工资 150% 的工资报酬"}, {"key": "C", "text": "法定休假日安排劳动者工作的，用人单位可以安排补休代替支付加班费"}, {"key": "D", "text": "只要劳动者书面同意，用人单位每月安排加班的时间可以超过 36 小时"}], "answer": ["A"], "explanation": "《劳动法》第四十一条规定：用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过 1 小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过 3 小时，但是每月不得超过 36 小时，A 正确。休息日安排工作又不能安排补休的，应支付不低于工资 200% 的工资报酬，B 错误；法定休假日安排工作的，应支付不低于工资 300% 的工资报酬，且不能以补休代替，C 错误；每月 36 小时的加班上限属于强制性规定，除抢险救灾等法律规定的特殊情况外，不能通过协商或劳动者书面同意突破，D 错误。", "knowledge_point": "工时制度与加班上限", "sort_order": 9}, {"id": 281, "module_code": "labor-law", "chapter_id": 14, "category": "exam", "qtype": "multiple", "stem": "根据《劳动合同法》，下列情形中用人单位应当向劳动者支付经济补偿的有？", "options": [{"key": "A", "text": "用人单位提出并与劳动者协商一致解除劳动合同"}, {"key": "B", "text": "劳动者患病或非因工负伤，医疗期满后不能从事原工作，也不能从事用人单位另行安排的工作，用人单位依法解除劳动合同"}, {"key": "C", "text": "劳动者严重违反用人单位的规章制度，用人单位解除劳动合同"}, {"key": "D", "text": "劳动合同期满，用人单位维持原劳动合同约定条件续订，劳动者不同意续订，劳动合同终止"}], "answer": ["A", "B"], "explanation": "《劳动合同法》第四十六条规定了应当支付经济补偿的情形：由用人单位提出并协商一致解除劳动合同的（A 正确）；用人单位依第四十条无过失性辞退的，其中包括医疗期满后不能从事原工作、也不能从事另行安排的工作的情形（B 正确）。劳动者严重违反规章制度属于依第三十九条的过失性辞退，用人单位无需支付经济补偿（C 错误）；固定期限劳动合同期满终止时，只有用人单位不同意续订，或虽同意续订但降低约定条件导致劳动者不同意续订的，才需支付经济补偿；用人单位维持或提高条件而劳动者拒绝续订的，无需支付（D 错误）。", "knowledge_point": "经济补偿支付情形", "sort_order": 10}, {"id": 282, "module_code": "labor-law", "chapter_id": 14, "category": "exam", "qtype": "single", "stem": "李某于 2021 年 3 月 1 日入职某公司。2024 年 10 月 31 日，公司以李某医疗期满后不能从事原工作、也不能从事公司另行安排的工作为由，提前三十日书面通知解除劳动合同。李某解除前十二个月的平均工资为 9000 元（未超过当地上年度职工月平均工资的三倍）。公司依法应向李某支付的经济补偿为？", "options": [{"key": "A", "text": "9000 元"}, {"key": "B", "text": "18000 元"}, {"key": "C", "text": "27000 元"}, {"key": "D", "text": "36000 元"}], "answer": ["D"], "explanation": "公司依《劳动合同法》第四十条无过失性辞退李某，应支付经济补偿，标准为：每满一年支付一个月工资；六个月以上不满一年的，按一年计算；不满六个月的，支付半个月工资（第四十七条）。李某在本单位工作 3 年 8 个月（2021 年 3 月 1 日至 2024 年 10 月 31 日），其中 8 个月按 1 年计算，合计按 4 年计，经济补偿为 4 个月工资，即 9000×4=36000 元，故选 D。“月工资”指劳动合同解除前 12 个月的平均工资（含奖金、津贴等）；若月工资高于当地上年度职工月平均工资三倍，则按三倍封顶且年限最多十二年，本题不适用该封顶规则。若公司属违法解除，则应按经济补偿标准的二倍支付赔偿金（2N）。", "knowledge_point": "经济补偿计算", "sort_order": 11}, {"id": 283, "module_code": "labor-law", "chapter_id": 13, "category": "exam", "qtype": "judge", "stem": "根据《职工带薪年休假条例》，职工累计工作已满 10 年不满 20 年的，享受带薪年休假 15 天。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "该说法错误。《职工带薪年休假条例》第三条规定：职工累计工作已满 1 年不满 10 年的，年休假 5 天；已满 10 年不满 20 年的，年休假 10 天；已满 20 年的，年休假 15 天。题干将“满 10 年不满 20 年”一档的休假天数误写为 15 天，实际应为 10 天，故本题判错。补充要点：年休假天数根据职工累计工作年限确定而非本单位工龄；国家法定休假日、休息日不计入年休假假期；单位确因工作需要不能安排职工休年休假的，经职工本人同意可不安排，但对职工应休未休的年休假天数，应按其日工资收入的 300% 支付年休假工资报酬（其中包含正常工作期间的工资收入）。", "knowledge_point": "带薪年休假天数", "sort_order": 12}, {"id": 196, "module_code": "labor-law", "chapter_id": 12, "category": "exam_case", "qtype": "single", "stem": "【案例】合规体检中，林晓发现一位入职满一年的员工从未订立书面劳动合同。根据《劳动合同法》，公司除应立即补订合同外，还可能面临什么后果？", "options": [{"key": "A", "text": "视为已订立无固定期限劳动合同，且超过一个月不满一年期间需支付二倍工资"}, {"key": "B", "text": "只需缴纳少量行政罚款"}, {"key": "C", "text": "员工自动转为劳务关系"}, {"key": "D", "text": "没有任何后果"}], "answer": ["A"], "explanation": "满一年未订立视为无固定期限合同（第十四条第三款）；超过一个月不满一年期间应每月支付二倍工资（第八十二条）。", "knowledge_point": "未签书面劳动合同的后果", "sort_order": 100}, {"id": 197, "module_code": "labor-law", "chapter_id": 14, "category": "exam_case", "qtype": "judge", "stem": "【案例】某员工连续数月加班，公司既无加班审批记录也未支付加班费，员工依据《劳动合同法》第三十八条以“未及时足额支付劳动报酬”为由解除劳动合同并要求经济补偿。员工的主张有法律依据。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "未及时足额支付劳动报酬属于被迫解除情形（第三十八条），劳动者可以解除合同并要求经济补偿；加班费属于劳动报酬的一部分。", "knowledge_point": "被迫解除（未足额支付劳动报酬）", "sort_order": 101}, {"id": 198, "module_code": "labor-law", "chapter_id": 14, "category": "exam_case", "qtype": "single", "stem": "【案例】莱茵科技以“不能胜任工作”为由辞退员工，但既未培训或调岗、也未提前 30 日通知、未支付经济补偿。员工申请仲裁主张违法解除赔偿金。下列说法正确的是？", "options": [{"key": "A", "text": "公司做法合法，无需赔偿"}, {"key": "B", "text": "公司未履行法定程序，构成违法解除，员工可主张经济补偿二倍的赔偿金"}, {"key": "C", "text": "员工只能要求补发当月工资"}, {"key": "D", "text": "仲裁委员会不会受理该案"}], "answer": ["B"], "explanation": "“不胜任”解除须先培训或调岗、提前 30 日通知或支付代通知金并支付经济补偿；程序缺失构成违法解除，按第八十七条支付 2N 赔偿金。", "knowledge_point": "违法解除赔偿金（2N）", "sort_order": 102}, {"id": 9, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "劳动合同的试用期，最长不得超过多久？", "options": [{"key": "A", "text": "3 个月"}, {"key": "B", "text": "6 个月"}, {"key": "C", "text": "1 年"}, {"key": "D", "text": "没有限制"}], "answer": ["B"], "explanation": "《劳动合同法》规定，试用期最长不得超过 6 个月（仅限三年以上固定期限或无固定期限合同）。", "knowledge_point": "", "sort_order": 0}, {"id": 10, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "我国标准工时制度下，劳动者每周工作时间一般不超过多少小时？", "options": [{"key": "A", "text": "36 小时"}, {"key": "B", "text": "40 小时"}, {"key": "C", "text": "44 小时"}, {"key": "D", "text": "48 小时"}], "answer": ["B"], "explanation": "标准工时制度为每日不超过 8 小时、每周不超过 40 小时。", "knowledge_point": "", "sort_order": 1}, {"id": 11, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "用人单位无过失性辞退员工，一般需提前多少天书面通知？", "options": [{"key": "A", "text": "15 天"}, {"key": "B", "text": "30 天"}, {"key": "C", "text": "45 天"}, {"key": "D", "text": "60 天"}], "answer": ["B"], "explanation": "无过失性辞退（如不胜任、客观情况重大变化等）需提前 30 日书面通知，或支付代通知金。", "knowledge_point": "", "sort_order": 2}, {"id": 12, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "judge", "stem": "用人单位自用工之日起超过一个月不满一年未与劳动者订立书面劳动合同，应当每月支付双倍工资。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "《劳动合同法》第八十二条：超过一个月不满一年未订立书面合同的，应当向劳动者每月支付二倍的工资。", "knowledge_point": "", "sort_order": 3}, {"id": 13, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "劳动争议处理的正确程序顺序是？", "options": [{"key": "A", "text": "仲裁→协商→诉讼"}, {"key": "B", "text": "协商→调解→仲裁→诉讼"}, {"key": "C", "text": "诉讼→仲裁→调解"}, {"key": "D", "text": "调解→诉讼→仲裁"}], "answer": ["B"], "explanation": "劳动争议应遵循「协商—调解—仲裁—诉讼」的法定程序，仲裁是诉讼的前置程序。", "knowledge_point": "", "sort_order": 4}, {"id": 14, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "标准工时制度下，用人单位安排劳动者延长工作时间，一般每日不得超过多少小时？", "options": [{"key": "A", "text": "1 小时"}, {"key": "B", "text": "2 小时"}, {"key": "C", "text": "3 小时"}, {"key": "D", "text": "4 小时"}], "answer": ["A"], "explanation": "《劳动法》规定，延长工作时间一般每日不得超过 1 小时；因特殊原因在保障健康条件下每日不得超过 3 小时且每月不得超过 36 小时。", "knowledge_point": "", "sort_order": 5}, {"id": 15, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "下列哪些情形，用人单位应当向劳动者支付经济补偿？", "options": [{"key": "A", "text": "协商一致解除劳动合同"}, {"key": "B", "text": "无过失性辞退（如不能胜任工作）"}, {"key": "C", "text": "经济性裁员"}, {"key": "D", "text": "劳动者在试用期被证明不符合录用条件"}], "answer": ["A", "B", "C"], "explanation": "协商解除（单位提出）、无过失性辞退、经济性裁员等情形需支付经济补偿；试用期不符合录用条件解除无需支付。", "knowledge_point": "", "sort_order": 6}, {"id": 16, "module_code": "labor-law", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "劳动者在试用期被证明不符合录用条件，用人单位应当如何处理？", "options": [{"key": "A", "text": "解除劳动合同且无需支付经济补偿"}, {"key": "B", "text": "必须支付经济补偿后解除"}, {"key": "C", "text": "只能协商解除"}, {"key": "D", "text": "不能解除"}], "answer": ["A"], "explanation": "《劳动合同法》第三十九条：试用期被证明不符合录用条件，用人单位可以解除劳动合同且无需支付经济补偿。", "knowledge_point": "", "sort_order": 7}, {"id": 167, "module_code": "labor-law", "chapter_id": 12, "category": "practice", "qtype": "single", "stem": "用人单位应当自用工之日起多长时间内与劳动者订立书面劳动合同？", "options": [{"key": "A", "text": "7 日内"}, {"key": "B", "text": "15 日内"}, {"key": "C", "text": "一个月内"}, {"key": "D", "text": "三个月内"}], "answer": ["C"], "explanation": "《劳动合同法》第十条规定，用人单位应当自用工之日起一个月内与劳动者订立书面劳动合同。", "knowledge_point": "劳动合同的订立与试用期", "sort_order": 0}, {"id": 174, "module_code": "labor-law", "chapter_id": 13, "category": "practice", "qtype": "single", "stem": "我国标准工时制度下，劳动者每周工作时间一般不超过多少小时？", "options": [{"key": "A", "text": "36 小时"}, {"key": "B", "text": "40 小时"}, {"key": "C", "text": "44 小时"}, {"key": "D", "text": "48 小时"}], "answer": ["B"], "explanation": "《劳动法》第三十六条：标准工时制度为每日不超过 8 小时、每周不超过 40 小时。", "knowledge_point": "工时、休假与加班管理", "sort_order": 0}, {"id": 181, "module_code": "labor-law", "chapter_id": 14, "category": "practice", "qtype": "single", "stem": "劳动者在试用期内被证明不符合录用条件，用人单位解除劳动合同是否需要支付经济补偿？", "options": [{"key": "A", "text": "需要支付"}, {"key": "B", "text": "不需要支付"}, {"key": "C", "text": "需要支付二倍赔偿金"}, {"key": "D", "text": "视员工司龄长短而定"}], "answer": ["B"], "explanation": "《劳动合同法》第三十九条：试用期不符合录用条件属于过失性辞退，无需支付经济补偿，但前提是录用条件明确且考核有证据。", "knowledge_point": "劳动合同解除、终止与经济补偿", "sort_order": 0}, {"id": 168, "module_code": "labor-law", "chapter_id": 12, "category": "practice", "qtype": "single", "stem": "劳动合同期限为一年以上不满三年的，试用期不得超过多久？", "options": [{"key": "A", "text": "1 个月"}, {"key": "B", "text": "2 个月"}, {"key": "C", "text": "3 个月"}, {"key": "D", "text": "6 个月"}], "answer": ["B"], "explanation": "《劳动合同法》第十九条：劳动合同期限一年以上不满三年的，试用期不得超过 2 个月。", "knowledge_point": "劳动合同的订立与试用期", "sort_order": 1}, {"id": 175, "module_code": "labor-law", "chapter_id": 13, "category": "practice", "qtype": "single", "stem": "用人单位安排劳动者加班，每月累计不得超过多少小时？", "options": [{"key": "A", "text": "24 小时"}, {"key": "B", "text": "32 小时"}, {"key": "C", "text": "36 小时"}, {"key": "D", "text": "40 小时"}], "answer": ["C"], "explanation": "《劳动法》第四十一条：特殊原因下每日不得超过 3 小时，且每月累计不得超过 36 小时。", "knowledge_point": "工时、休假与加班管理", "sort_order": 1}, {"id": 182, "module_code": "labor-law", "chapter_id": 14, "category": "practice", "qtype": "single", "stem": "用人单位无过失性辞退劳动者（如不能胜任工作），应当提前多少天书面通知，或额外支付一个月工资作为代通知金？", "options": [{"key": "A", "text": "15 日"}, {"key": "B", "text": "30 日"}, {"key": "C", "text": "45 日"}, {"key": "D", "text": "60 日"}], "answer": ["B"], "explanation": "《劳动合同法》第四十条：无过失性辞退需提前 30 日书面通知，或额外支付一个月工资后解除。", "knowledge_point": "劳动合同解除、终止与经济补偿", "sort_order": 1}, {"id": 169, "module_code": "labor-law", "chapter_id": 12, "category": "practice", "qtype": "judge", "stem": "同一用人单位与同一劳动者可以多次约定试用期，例如试用期结束后再延长一个月。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "同一用人单位与同一劳动者只能约定一次试用期，不能延长或重复约定。", "knowledge_point": "劳动合同的订立与试用期", "sort_order": 2}, {"id": 176, "module_code": "labor-law", "chapter_id": 13, "category": "practice", "qtype": "single", "stem": "休息日安排劳动者工作又不能安排补休的，应当支付不低于工资多少的工资报酬？", "options": [{"key": "A", "text": "100%"}, {"key": "B", "text": "150%"}, {"key": "C", "text": "200%"}, {"key": "D", "text": "300%"}], "answer": ["C"], "explanation": "《劳动法》第四十四条：休息日安排工作又不能安排补休的，支付不低于工资 200% 的工资报酬。", "knowledge_point": "工时、休假与加班管理", "sort_order": 2}, {"id": 183, "module_code": "labor-law", "chapter_id": 14, "category": "practice", "qtype": "single", "stem": "某员工在莱茵科技工作满三年零七个月后被无过失性辞退，其经济补偿应按几个月工资计算？", "options": [{"key": "A", "text": "3 个月"}, {"key": "B", "text": "3.5 个月"}, {"key": "C", "text": "4 个月"}, {"key": "D", "text": "7 个月"}], "answer": ["C"], "explanation": "每满一年支付一个月工资；六个月以上不满一年的按一年计算。满 3 年加 7 个月，合计按 4 个月计算。", "knowledge_point": "劳动合同解除、终止与经济补偿", "sort_order": 2}, {"id": 170, "module_code": "labor-law", "chapter_id": 12, "category": "practice", "qtype": "single", "stem": "下列哪项符合试用期工资的法定要求？", "options": [{"key": "A", "text": "可以低于当地最低工资标准"}, {"key": "B", "text": "不得低于本单位相同岗位最低档工资或劳动合同约定工资的 80%，且不得低于当地最低工资标准"}, {"key": "C", "text": "由用人单位单方自主确定"}, {"key": "D", "text": "试用期可以暂不发工资"}], "answer": ["B"], "explanation": "《劳动合同法》第二十条：试用期工资不得低于本单位相同岗位最低档工资或约定工资的 80%，并不得低于当地最低工资标准。", "knowledge_point": "劳动合同的订立与试用期", "sort_order": 3}, {"id": 177, "module_code": "labor-law", "chapter_id": 13, "category": "practice", "qtype": "judge", "stem": "法定休假日安排劳动者工作的，用人单位可以用安排补休的方式替代支付 300% 的加班工资。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "法定节假日加班只能支付不低于工资 300% 的报酬，不能以补休替代；只有休息日加班可以补休替代。", "knowledge_point": "工时、休假与加班管理", "sort_order": 3}, {"id": 184, "module_code": "labor-law", "chapter_id": 14, "category": "practice", "qtype": "judge", "stem": "对处于孕期、产期、哺乳期的女职工，用人单位可以依据经济性裁员的规定解除劳动合同。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "《劳动合同法》第四十二条：孕期、产期、哺乳期女职工受特别保护，不得依据第四十条、四十一条解除劳动合同。", "knowledge_point": "劳动合同解除、终止与经济补偿", "sort_order": 3}, {"id": 171, "module_code": "labor-law", "chapter_id": 12, "category": "practice", "qtype": "multiple", "stem": "下列关于试用期的说法，正确的有？", "options": [{"key": "A", "text": "试用期包含在劳动合同期限内"}, {"key": "B", "text": "劳动合同期限不满三个月的，不得约定试用期"}, {"key": "C", "text": "试用期工资可以低于当地最低工资标准"}, {"key": "D", "text": "试用期内被证明不符合录用条件，用人单位可以解除劳动合同"}], "answer": ["A", "B", "D"], "explanation": "试用期包含在合同期限内；不满三个月不得约定试用期；试用期工资不得低于最低工资标准（C 错）；不符合录用条件可依法解除（D 对）。", "knowledge_point": "劳动合同的订立与试用期", "sort_order": 4}, {"id": 178, "module_code": "labor-law", "chapter_id": 13, "category": "practice", "qtype": "multiple", "stem": "关于带薪年休假，下列说法正确的有？", "options": [{"key": "A", "text": "职工累计工作满 1 年不满 10 年的，年休假 5 天"}, {"key": "B", "text": "累计工作满 10 年不满 20 年的，年休假 10 天"}, {"key": "C", "text": "国家法定休假日、休息日不计入年休假假期"}, {"key": "D", "text": "应休未休的年休假，用人单位应按日工资收入的 100% 支付报酬"}], "answer": ["A", "B", "C"], "explanation": "应休未休的年休假应按日工资收入的 300% 支付年休假工资报酬（D 错），其余三项均符合《职工带薪年休假条例》规定。", "knowledge_point": "工时、休假与加班管理", "sort_order": 4}, {"id": 185, "module_code": "labor-law", "chapter_id": 14, "category": "practice", "qtype": "multiple", "stem": "下列关于劳动争议处理程序的表述，正确的有？", "options": [{"key": "A", "text": "协商不是必经程序"}, {"key": "B", "text": "劳动仲裁是诉讼的前置程序"}, {"key": "C", "text": "对仲裁裁决不服的，可以自收到裁决书之日起 15 日内向人民法院起诉"}, {"key": "D", "text": "劳动争议可以直接向法院起诉，无须先申请仲裁"}], "answer": ["A", "B", "C"], "explanation": "劳动争议须先经仲裁，对裁决不服再于 15 日内起诉（D 错）；协商、调解均非必经程序。", "knowledge_point": "劳动合同解除、终止与经济补偿", "sort_order": 4}, {"id": 172, "module_code": "labor-law", "chapter_id": 12, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓发现某新员工入职已两个月仍未订立书面劳动合同。根据《劳动合同法》，公司面临什么后果？", "options": [{"key": "A", "text": "只要尽快补签即可，没有任何其他后果"}, {"key": "B", "text": "自第二个月起应当每月向该员工支付二倍工资"}, {"key": "C", "text": "劳动关系自动解除"}, {"key": "D", "text": "员工只能主张精神损害赔偿"}], "answer": ["B"], "explanation": "超过一个月不满一年未订立书面合同的，应当每月支付二倍工资（第八十二条）；事后补签不能免除已发生的二倍工资责任。", "knowledge_point": "劳动合同的订立与试用期", "sort_order": 100}, {"id": 179, "module_code": "labor-law", "chapter_id": 13, "category": "practice_case", "qtype": "single", "stem": "【案例】陈工安排研发团队周末加班赶样机，林晓推动公司对周末加班优先安排补休。关于休息日加班，下列说法正确的是？", "options": [{"key": "A", "text": "休息日加班只能支付 200% 加班费，不能补休"}, {"key": "B", "text": "休息日加班可以优先安排补休；不能补休的，支付不低于工资 200% 的加班费"}, {"key": "C", "text": "休息日加班必须支付 300% 加班费"}, {"key": "D", "text": "休息日加班无需支付任何报酬"}], "answer": ["B"], "explanation": "休息日加班可以补休替代；无法安排补休的，才按不低于工资 200% 的标准支付加班费。案例中林晓的做法符合第四十四条。", "knowledge_point": "工时、休假与加班管理", "sort_order": 100}, {"id": 186, "module_code": "labor-law", "chapter_id": 14, "category": "practice_case", "qtype": "single", "stem": "【案例】刘姐想以“业绩垫底、不能胜任工作”为由直接辞退老销售且不支付经济补偿，林晓指出正确的解除路径是？", "options": [{"key": "A", "text": "直接辞退并拒绝支付补偿"}, {"key": "B", "text": "先培训或调整岗位；仍不能胜任的，提前 30 日书面通知或支付代通知金，并依法支付经济补偿"}, {"key": "C", "text": "口头通知员工离职即可"}, {"key": "D", "text": "让员工自己写辞职信走人"}], "answer": ["B"], "explanation": "“不胜任”解除属无过失性辞退（第四十条），必须先培训或调岗，仍不胜任的提前 30 日通知或支付代通知金，并支付经济补偿。", "knowledge_point": "劳动合同解除、终止与经济补偿", "sort_order": 100}, {"id": 173, "module_code": "labor-law", "chapter_id": 12, "category": "practice_case", "qtype": "judge", "stem": "【案例】陈工口头承诺“试用期三个月，不合适随时走人”，林晓指出：试用期长短必须与劳动合同期限挂钩，且口头约定不能替代书面合同。林晓的说法正确。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "试用期上限按合同期限确定（一年以上不满三年不超过 2 个月），且试用期应明确写入书面劳动合同，口头约定没有法律保障。", "knowledge_point": "劳动合同的订立与试用期", "sort_order": 101}, {"id": 180, "module_code": "labor-law", "chapter_id": 13, "category": "practice_case", "qtype": "judge", "stem": "【案例】刘姐认为“创业公司加班很正常，加班费用调休抵掉就行”，林晓提醒：法定节假日加班不能以补休替代，必须支付不低于工资 300% 的报酬。林晓的说法正确。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "法定节假日加班只能支付 300% 加班费，不能用补休或调休替代；刘姐“一刀切调休”的说法不符合法律规定。", "knowledge_point": "工时、休假与加班管理", "sort_order": 101}, {"id": 187, "module_code": "labor-law", "chapter_id": 14, "category": "practice_case", "qtype": "judge", "stem": "【案例】王总想辞退正在休产假的研发工程师，林晓坚持保留其岗位，理由是“三期”女职工受《劳动合同法》第四十二条特别保护，不得依据无过失性辞退或经济性裁员解除。林晓的做法正确。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "“三期”女职工属于第四十二条特别保护对象，不得依据第四十条、四十一条解除；否则构成违法解除，需支付 2N 赔偿金。", "knowledge_point": "劳动合同解除、终止与经济补偿", "sort_order": 101}, {"id": 252, "module_code": "performance", "chapter_id": 18, "category": "exam", "qtype": "single", "stem": "关于绩效管理的本质，下列说法正确的是？", "options": [{"key": "A", "text": "绩效管理就是年底打分"}, {"key": "B", "text": "绩效管理是“目标设定—过程辅导—绩效评估—反馈改进”的持续闭环，并与组织战略保持一致"}, {"key": "C", "text": "绩效管理只对员工不利"}, {"key": "D", "text": "绩效管理与组织战略无关"}], "answer": ["B"], "explanation": "德斯勒将绩效管理定义为确保员工活动与产出同组织目标保持一致的过程，是四环节持续闭环；打分只是其中的评估环节。", "knowledge_point": "绩效管理闭环与战略对齐", "sort_order": 0}, {"id": 298, "module_code": "performance", "chapter_id": 18, "category": "exam", "qtype": "judge", "stem": "KR 达成率接近 100% 是 OKR 的理想状态，说明目标既具挑战又顺利落地，是目标管理成功的标志。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "OKR 强调挑战性，理想达成率约为 70%；KR 达成率普遍接近 100% 通常意味着目标定得过于保守、没有起到牵引突破的作用，反而应当上调目标难度，而非视作目标管理成功的标志。", "knowledge_point": "OKR挑战性目标", "sort_order": 0}, {"id": 299, "module_code": "performance", "chapter_id": 20, "category": "exam", "qtype": "judge", "stem": "绩效面谈中，主管应多用“工作态度不端正”“责任心差”这类概括性评价，以便让员工快速认识到自身问题。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "该说法错误。绩效面谈应基于具体事实，遵循“对事不对人”的原则，可采用 STAR 法（情境—任务—行为—结果）还原关键事件，用具体事例和数据说明问题，避免“总是”“从不”等绝对化表述和贴标签式评价。笼统指责容易引发员工的防御与抵触情绪，无助于问题改进。正确做法是与员工共同分析差距原因，确认改进方向，并制定明确、可执行的改进计划（必要时启动 PIP 绩效改进计划）和后续辅导安排。", "knowledge_point": "STAR反馈", "sort_order": 0}, {"id": 253, "module_code": "performance", "chapter_id": 18, "category": "exam", "qtype": "single", "stem": "莱茵科技销售团队用 KPI、产品团队用 OKR，最根本的原因是？", "options": [{"key": "A", "text": "销售团队不如产品团队重要"}, {"key": "B", "text": "两类工作的性质不同：结果明确、重复性工作适合 KPI 保底线，创新探索性工作适合 OKR 拉增长"}, {"key": "C", "text": "刘姐不会用 OKR"}, {"key": "D", "text": "KPI 比 OKR 更先进"}], "answer": ["B"], "explanation": "工具要匹配工作性质。KPI 承诺制、与薪酬挂钩，适合可标准化衡量的岗位；OKR 挑战制、重对齐牵引，适合创新探索岗位。", "knowledge_point": "KPI与OKR适用场景", "sort_order": 1}, {"id": 254, "module_code": "performance", "chapter_id": 18, "category": "exam", "qtype": "multiple", "stem": "依据 SMART 原则，一个好的绩效目标应当具备哪些特征？", "options": [{"key": "A", "text": "具体明确（Specific）"}, {"key": "B", "text": "可衡量（Measurable）"}, {"key": "C", "text": "有挑战但可实现（Achievable）"}, {"key": "D", "text": "有明确时限（Time-bound）"}], "answer": ["A", "B", "C", "D"], "explanation": "SMART 五要素还包括相关（Relevant）：目标须与组织目标一致。模糊、无时限、不可衡量的目标无法被评估和验收。", "knowledge_point": "SMART原则", "sort_order": 2}, {"id": 256, "module_code": "performance", "chapter_id": 19, "category": "exam", "qtype": "single", "stem": "关于 360 度评估的使用，下列做法最合理的是？", "options": [{"key": "A", "text": "直接作为薪酬分配的唯一依据"}, {"key": "B", "text": "用于员工发展与领导力反馈，并与薪酬决策适当脱钩"}, {"key": "C", "text": "完全取代直接上级评估"}, {"key": "D", "text": "只在销售岗位使用"}], "answer": ["B"], "explanation": "多源反馈能揭示单一视角的盲区，适合发展目的；若与薪酬强挂钩，人际关系会污染反馈真实性，故实践中常与薪酬脱钩。", "knowledge_point": "360度评估", "sort_order": 4}, {"id": 257, "module_code": "performance", "chapter_id": 19, "category": "exam", "qtype": "multiple", "stem": "在绩效评估中，可能导致评分失真的评分者误差包括？", "options": [{"key": "A", "text": "晕轮效应"}, {"key": "B", "text": "近因效应"}, {"key": "C", "text": "居中趋势"}, {"key": "D", "text": "过宽或过严倾向"}], "answer": ["A", "B", "C", "D"], "explanation": "四类误差都会让评分偏离真实绩效，需要通过基于事实依据的评估、校准会、等级比例控制等流程机制来抑制。", "knowledge_point": "评分者误差", "sort_order": 5}, {"id": 258, "module_code": "performance", "chapter_id": 19, "category": "exam", "qtype": "single", "stem": "评分校准会（Calibration Meeting）的核心价值在于？", "options": [{"key": "A", "text": "让所有部门的分数统一提高"}, {"key": "B", "text": "统一跨部门评分标准、控制等级分布，消除评分者的主观偏差"}, {"key": "C", "text": "减少 HR 的工作量"}, {"key": "D", "text": "强制末位淘汰"}], "answer": ["B"], "explanation": "校准会通过集体讨论评分依据、统一各等级标准与比例上限，解决“同样水平在不同部门分数差异大”的公平性问题。", "knowledge_point": "绩效校准", "sort_order": 6}, {"id": 259, "module_code": "performance", "chapter_id": 20, "category": "exam", "qtype": "multiple", "stem": "一场合格的绩效面谈应该做到哪些？", "options": [{"key": "A", "text": "事前准备事实依据与关键事件"}, {"key": "B", "text": "对事不对人，先肯定后改进"}, {"key": "C", "text": "单方面宣布结果，不给员工发言机会"}, {"key": "D", "text": "面谈后形成改进计划并定期跟进"}], "answer": ["A", "B", "D"], "explanation": "面谈三阶段（前、中、后）都不可少：准备事实、双向沟通、跟进改进。C 是一言堂，会引发抵触，属于面谈禁忌。", "knowledge_point": "绩效面谈流程", "sort_order": 7}, {"id": 260, "module_code": "performance", "chapter_id": 20, "category": "exam", "qtype": "judge", "stem": "PIP（绩效改进计划）不仅是帮助员工改进的工具，也是后续调岗或解除劳动合同时的合规程序依据。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "PIP 明确差距、目标、支持与跟进记录，既给员工改进机会，也为组织保留程序证据，是绩效与劳动合规的衔接点。", "knowledge_point": "绩效改进计划（PIP）", "sort_order": 8}, {"id": 284, "module_code": "performance", "chapter_id": 18, "category": "exam", "qtype": "single", "stem": "关于 OKR 与 KPI 两种目标管理工具的比较，下列说法正确的是（　）。", "options": [{"key": "A", "text": "OKR 强调“做什么”，KPI 强调“做得怎么样”，二者定位完全相同，可以互相替代"}, {"key": "B", "text": "KPI 通常与薪酬激励强挂钩，而 OKR 更强调挑战性目标，一般不与薪酬直接强挂钩"}, {"key": "C", "text": "OKR 只适合研发创新型岗位，KPI 只适合生产操作型岗位，两者不可混用"}, {"key": "D", "text": "OKR 一旦设定，整个考核周期内不得复盘调整，KPI 则可以随时修改"}], "answer": ["B"], "explanation": "KPI（关键绩效指标）侧重对既定结果的衡量与考核，通常与绩效系数、薪酬激励强挂钩；OKR（目标与关键结果）侧重方向牵引与挑战性目标，关键结果需可量化，但一般不与薪酬直接强挂钩，以免员工因追求高挑战目标未达成而受罚。A 错误：OKR 与 KPI 定位不同（前者牵引方向与挑战，后者衡量结果与问责），不能完全替代，实践中常结合使用。C 错误：OKR 更适合不确定性高、需要创新的岗位，KPI 更适合目标稳定、结果可量化的岗位，但并非绝对割裂。D 错误：OKR 强调周期内定期复盘并据环境调整，而非一经设定不可变更。", "knowledge_point": "OKR与KPI区别", "sort_order": 9}, {"id": 285, "module_code": "performance", "chapter_id": 19, "category": "exam", "qtype": "single", "stem": "某公司对员工绩效等级实行强制分布（如“优秀≤20%、合格约70%、待改进≥10%”），并准备对连续两次被评为“待改进”的员工以“末位淘汰”为由解除劳动合同。从绩效管理角度，下列说法正确的是（　）。", "options": [{"key": "A", "text": "强制分布违背绩效管理“激励与发展”的初衷，企业应当一律废除"}, {"key": "B", "text": "只要考核结果客观公正，企业就可以随时以排名末位为由辞退员工"}, {"key": "C", "text": "强制分布需配套绩效校准与申诉机制，“排名末位”不等于“不胜任”，直接以末位为由解除劳动合同存在违法风险"}, {"key": "D", "text": "强制分布的等级比例一经确定，就必须逐年保持不变"}], "answer": ["C"], "explanation": "强制分布可以防止考核趋中化、宽大化，但必须以客观的评价标准和公平的过程为前提，通常需要绩效校准会议统一尺度，并建立申诉渠道保障员工权利。关键是“末位”不等于“不胜任”：劳动合同法规定解除劳动合同的法定情形是“不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作”，而绩效排名末位仅反映相对排序，直接以末位为由解除合同可能被认定为违法解除。A 错误：强制分布虽有争议，但并非“一律应废除”，关键是配套机制。B 错误：辞退必须符合法定解除条件与程序。D 错误：分布比例属于管理工具，可随组织经营状况动态调整，不必固定不变。", "knowledge_point": "强制分布与绩效等级", "sort_order": 10}, {"id": 286, "module_code": "performance", "chapter_id": 19, "category": "exam", "qtype": "multiple", "stem": "关于 360 度绩效评估，下列说法正确的有（　）。", "options": [{"key": "A", "text": "评价者通常包括上级、同事、下属、客户以及员工本人，信息来源多元"}, {"key": "B", "text": "360 度评估结果客观性最强，应直接作为员工定薪定级的唯一依据"}, {"key": "C", "text": "评估可能受人际关系影响而失真，应实行匿名作答并合理选择评价者"}, {"key": "D", "text": "360 度评估更适合用于员工发展性反馈，不宜单独作为薪酬决策依据"}], "answer": ["A", "C", "D"], "explanation": "360 度评估从上级、同事、下属、客户和自评等多来源收集反馈，信息更全面（A 正确）。由于涉及人际互动，评价容易受亲疏关系、晕轮效应等影响，通常需要匿名作答并慎重选择与被评价者工作关联密切的评价者（C 正确）。正因为其主观性较强，360 度评估更常用于发现盲点、促进发展的发展性反馈，若单独用于薪酬决策可能引发公平性争议（D 正确）。B 错误：360 度评估并非客观性最强的工具，也不应作为定薪定级的唯一依据，薪酬决策通常以 KPI 等客观结果为主、多方反馈为辅。", "knowledge_point": "360度评估", "sort_order": 11}, {"id": 287, "module_code": "performance", "chapter_id": 19, "category": "exam", "qtype": "multiple", "stem": "关于绩效校准会议（calibration meeting），下列说法正确的有（　）。", "options": [{"key": "A", "text": "由各部门主管共同评审员工绩效结果，进行横向比较，以减少部门间评价标准宽严不一的问题"}, {"key": "B", "text": "校准工作的重点是核对考核数据是否录入准确，而不是讨论评价尺度的一致性"}, {"key": "C", "text": "校准有助于纠正“宽大化”“趋中化”“晕轮效应”等评价偏差"}, {"key": "D", "text": "校准时应围绕争议员工的绩效事实与证据展开讨论，而非针对其性格或私人关系"}], "answer": ["A", "C", "D"], "explanation": "绩效校准的核心是让不同部门的主管坐在一起，对员工的绩效等级进行横向比较与调整，统一评价尺度和标准（A 正确），从而纠正宽大化、趋中化、晕轮效应等常见评价偏差（C 正确）。讨论必须基于可验证的绩效事实、数据和事例，就事论事，避免对个人性格、背景或人际关系的主观评判（D 正确）。B 错误：数据录入核对属于流程性检查，校准会议的重点恰恰是评价尺度和结果的一致性，而非简单的数据复核。", "knowledge_point": "绩效校准", "sort_order": 12}, {"id": 261, "module_code": "performance", "chapter_id": 18, "category": "exam_case", "qtype": "single", "stem": "【案例】莱茵科技经营会上，王总要求“把绩效立起来”。林晓先组织战略解码明确产品线战略，再为销售团队设 KPI、为产品团队设 OKR。这一做法体现了什么管理思想？", "options": [{"key": "A", "text": "评估工具应与岗位工作性质匹配，并服务于组织战略对齐"}, {"key": "B", "text": "每个部门自行定目标即可，无需对齐"}, {"key": "C", "text": "绩效只考核结果，不关注过程与创新"}, {"key": "D", "text": "目标设定与公司战略无关"}], "answer": ["A"], "explanation": "先战略解码、再按工作性质选择工具（销售 KPI、产品 OKR），正是绩效管理“从战略到目标、从目标到考核”的系统化设计。", "knowledge_point": "战略对齐与工具选择", "sort_order": 100}, {"id": 262, "module_code": "performance", "chapter_id": 19, "category": "exam_case", "qtype": "single", "stem": "【案例】季度评估后，莱茵科技出现“同样水平的员工在销售部 92 分、产品部 74 分”的现象，林晓组织评分校准会统一等级定义与比例上限。该做法的核心价值是？", "options": [{"key": "A", "text": "提高员工的平均分"}, {"key": "B", "text": "保证评估的公平性与跨部门可比性"}, {"key": "C", "text": "减少 HR 的工作量"}, {"key": "D", "text": "让评分者打分更轻松"}], "answer": ["B"], "explanation": "校准会统一标准与等级分布，使不同部门的评分可比较、更公平，消除“看部门不看人”的偏差，是评估公信力的制度保障。", "knowledge_point": "绩效校准", "sort_order": 101}, {"id": 263, "module_code": "performance", "chapter_id": 20, "category": "exam_case", "qtype": "single", "stem": "【案例】硬件工程师小周对 C 级评估不满、情绪激动，林晓调出评审记录逐条解释扣分依据，双方对齐改进点并制定跟进计划。这体现了绩效面谈的什么原则？", "options": [{"key": "A", "text": "以事实为依据、尊重员工、聚焦改进"}, {"key": "B", "text": "员工必须无条件接受评估结果"}, {"key": "C", "text": "评估结果不需要与员工沟通"}, {"key": "D", "text": "面谈应以批评和惩罚为主"}], "answer": ["A"], "explanation": "用记录的事实说话、允许员工表达、共同制定改进计划，是绩效面谈“对事不对人、聚焦未来”原则的完整落地。", "knowledge_point": "绩效面谈与STAR反馈", "sort_order": 102}, {"id": 17, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "OKR 中的 O 代表什么？", "options": [{"key": "A", "text": "Output（产出）"}, {"key": "B", "text": "Objective（目标）"}, {"key": "C", "text": "Operation（运营）"}, {"key": "D", "text": "Option（选项）"}], "answer": ["B"], "explanation": "OKR = Objectives and Key Results，O 是定性的、有挑战性的目标，KR 是衡量目标达成的关键结果。", "knowledge_point": "", "sort_order": 0}, {"id": 18, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "KPI 考核设计的核心原则是什么？", "options": [{"key": "A", "text": "指标越多越全面"}, {"key": "B", "text": "指标可量化、可衡量、与战略对齐"}, {"key": "C", "text": "指标只考核结果不看过程"}, {"key": "D", "text": "指标每年固定不变"}], "answer": ["B"], "explanation": "KPI 应遵循 SMART 原则且与组织战略对齐，聚焦关键少数指标，而非越多越好。", "knowledge_point": "", "sort_order": 1}, {"id": 19, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "绩效面谈中，管理者最应该注意的是什么？", "options": [{"key": "A", "text": "只谈缺点不谈优点"}, {"key": "B", "text": "单向宣布结果"}, {"key": "C", "text": "双向沟通，聚焦事实与改进"}, {"key": "D", "text": "只谈薪资不谈绩效"}], "answer": ["C"], "explanation": "绩效面谈的核心是双向沟通：基于事实反馈、共同分析差距、制定改进计划。", "knowledge_point": "", "sort_order": 2}, {"id": 20, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "360 度评估通常包含哪些评价来源？", "options": [{"key": "A", "text": "上级评价"}, {"key": "B", "text": "同事（平级）评价"}, {"key": "C", "text": "下属评价"}, {"key": "D", "text": "客户与自我评价"}], "answer": ["A", "B", "C", "D"], "explanation": "360 度评估从上级、同事、下属、客户及自我多个维度收集反馈，更全面客观。", "knowledge_point": "", "sort_order": 3}, {"id": 21, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "judge", "stem": "绩效管理只是 HR 部门的事，业务部门只需在年底填一次评分表。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "绩效管理是直线管理者日常管理的一部分，贯穿目标设定、过程辅导、评估反馈全周期。", "knowledge_point": "", "sort_order": 4}, {"id": 22, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "SMART 原则中，M 代表什么？", "options": [{"key": "A", "text": "Meaningful（有意义）"}, {"key": "B", "text": "Measurable（可衡量）"}, {"key": "C", "text": "Manageable（可管理）"}, {"key": "D", "text": "Motivating（激励性）"}], "answer": ["B"], "explanation": "SMART = Specific（具体）、Measurable（可衡量）、Achievable（可实现）、Relevant（相关）、Time-bound（有时限）。", "knowledge_point": "", "sort_order": 5}, {"id": 23, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "绩效辅导最合适的时机是？", "options": [{"key": "A", "text": "只在年底考核时"}, {"key": "B", "text": "在绩效周期过程中持续进行"}, {"key": "C", "text": "只在员工犯错时"}, {"key": "D", "text": "只在员工提出时"}], "answer": ["B"], "explanation": "绩效辅导应贯穿整个绩效周期，及时反馈、及时纠偏，而非集中在考核时点。", "knowledge_point": "", "sort_order": 6}, {"id": 24, "module_code": "performance", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "绩效评估结果通常用于哪些方面？", "options": [{"key": "A", "text": "薪酬调整与奖金分配"}, {"key": "B", "text": "晋升与岗位调整"}, {"key": "C", "text": "培训需求识别"}, {"key": "D", "text": "绩效改进计划"}], "answer": ["A", "B", "C", "D"], "explanation": "绩效结果广泛用于薪酬、晋升、培训与发展、改进计划等，实现激励与发展的双重目的。", "knowledge_point": "", "sort_order": 7}, {"id": 231, "module_code": "performance", "chapter_id": 18, "category": "practice", "qtype": "single", "stem": "关于 KPI 与 OKR 的本质区别，下列说法正确的是？", "options": [{"key": "A", "text": "KPI 是定性目标，OKR 是量化指标"}, {"key": "B", "text": "KPI 侧重衡量与考核，OKR 侧重对齐与牵引"}, {"key": "C", "text": "KPI 与 OKR 完全等同，只是叫法不同"}, {"key": "D", "text": "OKR 必须与薪酬直接挂钩"}], "answer": ["B"], "explanation": "KPI 是把战略分解为可量化指标，用于衡量与考核（保底线）；OKR 由定性目标（O）和量化关键结果（KR）组成，用于对齐方向、牵引挑战（拉增长）。二者目的不同，不能混为一谈。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 0}, {"id": 238, "module_code": "performance", "chapter_id": 19, "category": "practice", "qtype": "single", "stem": "关于 360 度评估，下列说法正确的是？", "options": [{"key": "A", "text": "最适合作为薪酬分配的唯一依据"}, {"key": "B", "text": "最适合用于员工发展、领导力反馈等发展目的"}, {"key": "C", "text": "可以完全取代直接上级评估"}, {"key": "D", "text": "只能由外部客户打分"}], "answer": ["B"], "explanation": "360 度评估汇集上级、同事、下属、客户与自评等多源反馈，用于发展目的最有效；直接用于薪酬晋升容易被关系污染，实践中通常与薪酬脱钩。", "knowledge_point": "绩效评估流程设计", "sort_order": 0}, {"id": 245, "module_code": "performance", "chapter_id": 20, "category": "practice", "qtype": "single", "stem": "绩效面谈最核心的目的是？", "options": [{"key": "A", "text": "向员工宣布奖惩结果并让其签字"}, {"key": "B", "text": "就评估结果达成共识、分析原因并共同制定改进计划"}, {"key": "C", "text": "收集员工的晋升材料"}, {"key": "D", "text": "为辞退员工找理由"}], "answer": ["B"], "explanation": "面谈的意义在于沟通结果、对齐认知、聚焦未来改进。只宣布结果而无共识与改进计划，评估就失去了闭环价值。", "knowledge_point": "绩效面谈与反馈改进", "sort_order": 0}, {"id": 232, "module_code": "performance", "chapter_id": 18, "category": "practice", "qtype": "multiple", "stem": "下列目标中，符合 SMART 原则的有？", "options": [{"key": "A", "text": "提升手表产品质量"}, {"key": "B", "text": "Q3 内将手表典型场景续航从 3 天提升到 5 天"}, {"key": "C", "text": "尽快提升用户满意度"}, {"key": "D", "text": "通过优化功耗方案，在 9 月底前将典型场景续航提升到 5 天，且不降低屏幕亮度"}], "answer": ["B", "D"], "explanation": "B 具体、可衡量、有明确时限；D 在 B 的基础上补充了达成路径与约束，完整满足 SMART。A、C 缺乏可衡量的标准与时限，属于模糊目标。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 1}, {"id": 239, "module_code": "performance", "chapter_id": 19, "category": "practice", "qtype": "multiple", "stem": "下列属于常见评分者误差的有？", "options": [{"key": "A", "text": "晕轮效应"}, {"key": "B", "text": "近因效应"}, {"key": "C", "text": "居中趋势"}, {"key": "D", "text": "过宽或过严倾向"}], "answer": ["A", "B", "C", "D"], "explanation": "晕轮效应（以偏概全）、近因效应（只记最近表现）、居中趋势（都打中间分）、过宽/过严倾向（好人分或严苛分）都会扭曲评分，需要靠流程机制抑制。", "knowledge_point": "绩效评估流程设计", "sort_order": 1}, {"id": 246, "module_code": "performance", "chapter_id": 20, "category": "practice", "qtype": "multiple", "stem": "STAR 反馈法包含哪些要素？", "options": [{"key": "A", "text": "Situation 情境"}, {"key": "B", "text": "Task 任务"}, {"key": "C", "text": "Action 行为"}, {"key": "D", "text": "Result 结果"}], "answer": ["A", "B", "C", "D"], "explanation": "STAR 即情境、任务、行为、结果四要素，用于描述具体行为事实，让反馈具体可信而不流于人身评价。", "knowledge_point": "绩效面谈与反馈改进", "sort_order": 1}, {"id": 233, "module_code": "performance", "chapter_id": 18, "category": "practice", "qtype": "judge", "stem": "OKR 中的 O（目标）是定性的、鼓舞人心的方向，KR（关键结果）则是衡量 O 达成情况的可量化结果。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "这是 OKR 的标准结构：O 回答“去哪里”，KR 回答“怎么证明到了”，KR 必须可量化。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 2}, {"id": 240, "module_code": "performance", "chapter_id": 19, "category": "practice", "qtype": "judge", "stem": "绩效评估只是绩效管理中的一个环节，绩效管理还包括目标设定、过程辅导、反馈面谈与改进等，二者不能等同。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "绩效管理是“目标—辅导—评估—反馈改进”的持续闭环，绩效评估只是其中的评估环节，切忌以“打分”代替“管理”。", "knowledge_point": "绩效评估流程设计", "sort_order": 2}, {"id": 247, "module_code": "performance", "chapter_id": 20, "category": "practice", "qtype": "judge", "stem": "绩效面谈应当“对事不对人”，聚焦具体行为及其影响，而不是评价员工的性格与人格。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "批评行为而不否定人，是面谈的基本准则。“对事不对人”能减少抵触，把讨论引向改进而非争辩。", "knowledge_point": "绩效面谈与反馈改进", "sort_order": 2}, {"id": 234, "module_code": "performance", "chapter_id": 18, "category": "practice", "qtype": "single", "stem": "目标管理（MBO）最早由哪位管理学家在《管理的实践》中提出？", "options": [{"key": "A", "text": "彼得·德鲁克"}, {"key": "B", "text": "加里·德斯勒"}, {"key": "C", "text": "戴维·尤里奇"}, {"key": "D", "text": "杨国安"}], "answer": ["A"], "explanation": "德鲁克 1954 年在《管理的实践》中提出目标管理，主张“有了目标才能确定每个人的工作”，是 KPI 与 OKR 的共同思想源头。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 3}, {"id": 241, "module_code": "performance", "chapter_id": 19, "category": "practice", "qtype": "single", "stem": "评分校准会（Calibration Meeting）的主要目的是？", "options": [{"key": "A", "text": "把各部门分数统一提高"}, {"key": "B", "text": "统一跨部门评分标准、控制等级比例、消除主观偏差"}, {"key": "C", "text": "替代员工自评环节"}, {"key": "D", "text": "强制淘汰末位员工"}], "answer": ["B"], "explanation": "校准会由各部门负责人与 HR 一起讨论评分依据，统一各等级标准与比例上限，解决“同样水平不同部门分数差很多”的公平性问题。", "knowledge_point": "绩效评估流程设计", "sort_order": 3}, {"id": 248, "module_code": "performance", "chapter_id": 20, "category": "practice", "qtype": "single", "stem": "关于绩效改进计划（PIP），正确的做法是？", "options": [{"key": "A", "text": "口头警告后直接辞退员工"}, {"key": "B", "text": "明确差距、改进目标与时间表，提供资源支持并定期跟进评估"}, {"key": "C", "text": "只针对新入职员工"}, {"key": "D", "text": "无需员工确认与参与"}], "answer": ["B"], "explanation": "PIP 是结构化改进方案：差距、目标与时间表、资源支持、定期跟进四要素缺一不可；它既是帮助员工的工具，也是后续合规处理的程序依据。", "knowledge_point": "绩效面谈与反馈改进", "sort_order": 3}, {"id": 235, "module_code": "performance", "chapter_id": 18, "category": "practice", "qtype": "multiple", "stem": "平衡计分卡从哪些维度把战略分解为可衡量的指标？", "options": [{"key": "A", "text": "财务"}, {"key": "B", "text": "客户"}, {"key": "C", "text": "内部流程"}, {"key": "D", "text": "学习与成长"}], "answer": ["A", "B", "C", "D"], "explanation": "平衡计分卡包含财务、客户、内部流程、学习与成长四个维度，是 KPI 战略分解的经典框架。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 4}, {"id": 242, "module_code": "performance", "chapter_id": 19, "category": "practice", "qtype": "single", "stem": "关于绩效评估的评估主体，下列说法正确的是？", "options": [{"key": "A", "text": "直接上级通常最了解下属绩效，是评估主体"}, {"key": "B", "text": "评估只能由 HR 部门完成"}, {"key": "C", "text": "同事评价一定比上级准确"}, {"key": "D", "text": "员工自评没有任何价值"}], "answer": ["A"], "explanation": "直接上级最了解下属的日常表现与目标达成情况，是评估主体；HR 负责组织流程，同事与自评是补充视角，都有各自局限。", "knowledge_point": "绩效评估流程设计", "sort_order": 4}, {"id": 249, "module_code": "performance", "chapter_id": 20, "category": "practice", "qtype": "single", "stem": "GROW 辅导模型的四个步骤，正确顺序是？", "options": [{"key": "A", "text": "Goal → Reality → Options → Will"}, {"key": "B", "text": "Goal → Options → Reality → Will"}, {"key": "C", "text": "Reality → Goal → Will → Options"}, {"key": "D", "text": "Options → Goal → Reality → Will"}], "answer": ["A"], "explanation": "GROW 依次为 Goal（目标）、Reality（现状）、Options（方案）、Will（行动意愿），通过提问引导员工自己找到答案。", "knowledge_point": "绩效面谈与反馈改进", "sort_order": 4}, {"id": 267, "module_code": "performance", "chapter_id": 18, "category": "practice", "qtype": "multiple", "stem": "根据杨三角\"员工思维\"维度，提升员工对绩效体系的认同可以采取哪些做法？", "options": [{"key": "A", "text": "目标由管理者与员工共同设定"}, {"key": "B", "text": "评分规则与数据来源事先透明"}, {"key": "C", "text": "绩效结果与激励晋升的联动公开一致"}, {"key": "D", "text": "绩效结果严格保密，仅管理者可见"}], "answer": ["A", "B", "C"], "explanation": "共担目标、过程透明、应用一致是建立绩效认同的关键；保密反而滋生猜疑。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 5}, {"id": 236, "module_code": "performance", "chapter_id": 18, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技智能手表产品线组建完成后，王总要求“把绩效立起来”。产品总监陈工反对用销售额考核产品团队，理由是创新需要长期打磨。如果你是林晓，最合理的做法是？", "options": [{"key": "A", "text": "坚持全公司统一用销售额 KPI 考核，保证标准一致"}, {"key": "B", "text": "产品团队改用 OKR 承接创新目标，KR 可量化且不与奖金直接强挂钩，销售团队保留 KPI"}, {"key": "C", "text": "取消产品团队的绩效考核"}, {"key": "D", "text": "让产品团队自行定目标，公司不审核"}], "answer": ["B"], "explanation": "创新探索性工作适合 OKR：用可量化 KR 承接方向，不与奖金强挂钩才能鼓励挑战；销售等结果明确岗位用 KPI 保底线。A 会用短期销售数字扭曲创新；C、D 等于放弃管理。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 100}, {"id": 243, "module_code": "performance", "chapter_id": 19, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技季度评估后，同样水平的员工在销售部得 92 分、在产品部只有 74 分，员工质疑“不公平”。如果你是林晓，最合适的做法是？", "options": [{"key": "A", "text": "统一把两边的分数改成 85 分"}, {"key": "B", "text": "组织评分校准会，让各部门带着评分依据对齐标准、统一等级定义与比例上限"}, {"key": "C", "text": "请 CEO 亲自为每位员工打分"}, {"key": "D", "text": "取消本季度评估"}], "answer": ["B"], "explanation": "校准会是解决跨部门标准不一致的标准机制：讨论评分依据、统一标准与比例，让“一把尺子量到底”。A 是拍脑袋抹平，C、D 回避了问题。", "knowledge_point": "绩效评估流程设计", "sort_order": 100}, {"id": 250, "module_code": "performance", "chapter_id": 20, "category": "practice_case", "qtype": "single", "stem": "【案例】刘姐把销售团队评估结果直接群发到工作群，一名业绩靠后的老销售当众发火。如果你是林晓，首先应该？", "options": [{"key": "A", "text": "忽略员工情绪，继续群发通报"}, {"key": "B", "text": "立即纠正：评估结果应一对一保密沟通，并安排正式绩效面谈"}, {"key": "C", "text": "让刘姐在群里再解释一遍"}, {"key": "D", "text": "直接辞退该员工以儆效尤"}], "answer": ["B"], "explanation": "评估结果是敏感信息，必须一对一沟通。群发会激化矛盾、损害信任；正确的做法是纠正流程并安排保密面谈，接住员工情绪。", "knowledge_point": "绩效面谈与反馈改进", "sort_order": 100}, {"id": 237, "module_code": "performance", "chapter_id": 18, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓收集各部门目标时发现，销售团队要“销量与回款”，产品团队要“长期创新体验”，两份目标互相冲突。这一问题的本质是？", "options": [{"key": "A", "text": "员工工作不努力"}, {"key": "B", "text": "目标没有与公司战略对齐，且缺少统一的设定与协同机制"}, {"key": "C", "text": "绩效考核周期太长"}, {"key": "D", "text": "公司奖金预算不足"}], "answer": ["B"], "explanation": "目标冲突源于战略没有解码、部门各自为战。解决之道是先澄清战略（战略解码），再通过 KPI/OKR 与 SMART 让目标对齐公司方向。", "knowledge_point": "KPI 与 OKR 目标设定", "sort_order": 101}, {"id": 244, "module_code": "performance", "chapter_id": 19, "category": "practice_case", "qtype": "single", "stem": "【案例】刘姐凭印象五分钟打完分且分数普遍偏高，陈工认为工程师的工作“没法量化”。这暴露出的核心问题是？", "options": [{"key": "A", "text": "员工不配合评估"}, {"key": "B", "text": "评估缺少客观的事实依据与统一的评分标准"}, {"key": "C", "text": "评估周期太短"}, {"key": "D", "text": "评估结果没有用于奖金分配"}], "answer": ["B"], "explanation": "凭印象打分与“无法量化”都是缺乏标准与事实依据的表现。对策是锚定目标与关键事件作为评分依据，并通过校准会统一标准。", "knowledge_point": "绩效评估流程设计", "sort_order": 101}, {"id": 251, "module_code": "performance", "chapter_id": 20, "category": "practice_case", "qtype": "single", "stem": "【案例】陈工约谈工程师时只说“最近表现一般，继续加油”，工程师不知道具体哪里需要改进。这体现了？", "options": [{"key": "A", "text": "反馈空泛，缺乏具体事实，没有使用 STAR 方法"}, {"key": "B", "text": "工程师能力太差"}, {"key": "C", "text": "绩效评估本身没有意义"}, {"key": "D", "text": "绩效面谈应该取消"}], "answer": ["A"], "explanation": "“表现一般”是空泛评价，没有情境、任务、行为、结果的具体描述，员工无法据此改进。这正是 STAR 反馈法要解决的问题。", "knowledge_point": "绩效面谈与反馈改进", "sort_order": 101}, {"id": 123, "module_code": "compensation", "chapter_id": 6, "category": "exam", "qtype": "single", "stem": "某公司对关键研发岗采用 P75 领先策略、对行政支持岗采用 P50 跟随策略，这种安排属于？", "options": [{"key": "A", "text": "全面领先策略"}, {"key": "B", "text": "混合薪酬策略"}, {"key": "C", "text": "全面跟随策略"}, {"key": "D", "text": "滞后策略"}], "answer": ["B"], "explanation": "对不同岗位采用不同市场定位，属于混合策略：关键岗位领先以吸引核心人才，一般岗位跟随以控制成本，是成长型企业的常见选择。", "knowledge_point": "薪酬水平策略", "sort_order": 0}, {"id": 294, "module_code": "compensation", "chapter_id": 7, "category": "exam", "qtype": "judge", "stem": "岗位价值评估衡量的是岗位本身所承担的责任与任职要求，任职者的绩效与能力差异不属于岗位评估的范畴。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "正确。岗位评估依据岗位说明书衡量岗位的相对价值；任职者的绩效与能力差异属于个体公平范畴，在薪酬区间内的定位环节解决。", "knowledge_point": "岗位价值评估", "sort_order": 0}, {"id": 295, "module_code": "compensation", "chapter_id": 8, "category": "exam", "qtype": "judge", "stem": "弹性福利（自助式福利）制度下，只要福利预算总额固定，员工就可以在预算内自由选择任何福利项目，无需企业提供可选项目清单。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "该说法错误。弹性福利（自助式福利）是指企业在一定福利总额和可选项目范围内，允许员工根据自身需求在福利“菜单”中自主组合福利项目；其“自助”是有限度的——企业必须设计并公布可选福利项目清单、为各项目标注价格（点数），同时控制整体福利成本，员工并非可以完全自由地选择任何项目。此外，法定强制性福利（五险一金）属于必须依法足额缴纳的项目，不纳入员工可自主选择的弹性范围。弹性福利的价值在于满足员工多样化需求、提升福利感知价值，但仍需兼顾成本可控与法定合规。", "knowledge_point": "弹性福利", "sort_order": 0}, {"id": 124, "module_code": "compensation", "chapter_id": 6, "category": "exam", "qtype": "single", "stem": "关于薪酬带宽设计，下列说法正确的是？", "options": [{"key": "A", "text": "所有岗位等级都应使用相同带宽"}, {"key": "B", "text": "通常岗位等级越高，带宽越宽"}, {"key": "C", "text": "带宽越窄越能体现激励"}, {"key": "D", "text": "带宽由员工个人绩效决定"}], "answer": ["B"], "explanation": "高层级岗位个人能力差异对组织影响更大，需要更大的带宽容纳差异，因此经验上等级越高带宽越宽；带宽是结构参数，由设计决定，而非个人绩效。", "knowledge_point": "薪酬带宽", "sort_order": 1}, {"id": 125, "module_code": "compensation", "chapter_id": 6, "category": "exam", "qtype": "multiple", "stem": "宽带薪酬（broadbanding）的典型特点包括（ ）。", "options": [{"key": "A", "text": "薪酬等级数量少、跨度大"}, {"key": "B", "text": "弱化行政层级，鼓励横向技能发展"}, {"key": "C", "text": "适合扁平化组织"}, {"key": "D", "text": "完全取消固定薪酬"}], "answer": ["A", "B", "C"], "explanation": "宽带薪酬把多个等级合并为少数大跨度带宽，弱化层级、鼓励轮岗与技能成长，适合扁平化组织；它并不取消固定薪酬，只是压缩等级数量。", "knowledge_point": "宽带薪酬", "sort_order": 2}, {"id": 127, "module_code": "compensation", "chapter_id": 7, "category": "exam", "qtype": "single", "stem": "与简单的排序法相比，因素计点法的主要优势是？", "options": [{"key": "A", "text": "实施更快、成本更低"}, {"key": "B", "text": "评估标准客观量化、结果可解释、可复现"}, {"key": "C", "text": "无需岗位说明书"}, {"key": "D", "text": "只适用于 50 人以下的小公司"}], "answer": ["B"], "explanation": "因素计点法以统一付酬要素和权重打分，标准透明、可解释可复现，能减少主观争论；缺点是前期设计成本较高，且结果与岗位说明书质量强相关。", "knowledge_point": "因素计点法", "sort_order": 4}, {"id": 128, "module_code": "compensation", "chapter_id": 7, "category": "exam", "qtype": "multiple", "stem": "影响公司薪酬水平决策的外部市场因素包括（ ）。", "options": [{"key": "A", "text": "行业整体薪酬水平"}, {"key": "B", "text": "地区生活成本与人才供需"}, {"key": "C", "text": "竞争对手的薪酬政策"}, {"key": "D", "text": "员工个人的涨薪要求"}], "answer": ["A", "B", "C"], "explanation": "行业水平、地区生活成本、人才供需与竞争对手政策共同构成外部市场约束；员工个人要求属于内部因素，且不能作为定薪依据。", "knowledge_point": "薪酬调查", "sort_order": 5}, {"id": 129, "module_code": "compensation", "chapter_id": 7, "category": "exam", "qtype": "single", "stem": "某岗位市场薪酬 P50 为 10000 元，公司采用跟随策略，则该岗位薪酬等级的中点值通常设定为？", "options": [{"key": "A", "text": "7000 元"}, {"key": "B", "text": "10000 元"}, {"key": "C", "text": "13000 元"}, {"key": "D", "text": "15000 元"}], "answer": ["B"], "explanation": "跟随策略下薪酬中点值通常对齐市场 P50（10000 元）；对齐 P75 才是领先策略，对应更高水平。", "knowledge_point": "薪酬分位", "sort_order": 6}, {"id": 130, "module_code": "compensation", "chapter_id": 8, "category": "exam", "qtype": "judge", "stem": "弹性福利制度下，员工选择的补充项目可以灵活组合，但法定福利仍须依法足额缴纳。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "正确。弹性福利是在法定福利之上的补充设计，法定福利具有强制性，任何情况下都不可替代、不可减免。", "knowledge_point": "弹性福利", "sort_order": 7}, {"id": 131, "module_code": "compensation", "chapter_id": 8, "category": "exam", "qtype": "multiple", "stem": "依据世界薪酬协会（WorldatWork）的总报酬模型，总报酬的构成要素包括（ ）。", "options": [{"key": "A", "text": "薪酬与福利"}, {"key": "B", "text": "工作生活平衡"}, {"key": "C", "text": "绩效与认可"}, {"key": "D", "text": "发展与职业机会"}], "answer": ["A", "B", "C", "D"], "explanation": "总报酬模型包含薪酬、福利、工作生活平衡、绩效与认可、发展与职业机会五大要素，提示留人应打“组合拳”，而非只靠现金。", "knowledge_point": "总报酬模型", "sort_order": 8}, {"id": 269, "module_code": "compensation", "chapter_id": 6, "category": "exam", "qtype": "single", "stem": "某企业为鼓励员工走专业/技能发展通道，将原有 12 个薪酬等级压缩为 5 个薪酬宽带，并把每一等级的薪酬变动范围（带宽）由 ±20% 扩大为 ±60%。关于该宽带薪酬改革的说法，正确的是（　）。", "options": [{"key": "A", "text": "宽带薪酬下员工只有晋升到更高职级才能加薪，会进一步强化“官本位”导向"}, {"key": "B", "text": "带宽扩大使员工在同一职级内即可凭借能力和绩效提升获得加薪，弱化对职位晋升的依赖"}, {"key": "C", "text": "带宽扩大意味着每个薪酬等级的上限被压缩、加薪空间变小"}, {"key": "D", "text": "宽带薪酬会显著增加外部薪酬调查的成本，因此不适用于大型企业"}], "answer": ["B"], "explanation": "宽带薪酬通过压缩薪酬等级数量、拉大带宽（每一等级的薪酬变动范围），使员工在同一职级内也能随能力、技能与绩效的提升获得薪酬增长，从而弱化“只有晋升职级才能加薪”的官本位倾向，支持员工横向流动和专业/技能发展（B 正确）。A 错误：依赖晋升加薪恰恰是传统窄带薪酬的特点，宽带薪酬正是为打破这一局面。C 错误：带宽扩大意味着同级薪酬浮动空间和上限提高，而非压缩。D 错误：宽带薪酬与外部薪酬调查成本之间没有必然联系，实施宽带薪酬时同样需要做市场对标。", "knowledge_point": "宽带薪酬", "sort_order": 9}, {"id": 270, "module_code": "compensation", "chapter_id": 7, "category": "exam", "qtype": "single", "stem": "某公司采用因素计点法开展岗位价值评估。以下做法符合该方法原理的是（　）。", "options": [{"key": "A", "text": "允许各岗位根据自身特色自行确定评价因素，以保证评估结果体现岗位差异"}, {"key": "B", "text": "确定统一的付酬因素并划分等级、赋予权重和点数，用同一套标准对所有岗位打分，依据总点数排出岗位价值序列"}, {"key": "C", "text": "由被评估岗位的员工本人对所在岗位打分，以提升员工的参与感和认可度"}, {"key": "D", "text": "将评估得到的总点数直接用于计算员工个人的绩效工资"}], "answer": ["B"], "explanation": "因素计点法（计点法/点值法）的核心是先确定统一的付酬因素（如技能、责任、努力程度、工作条件等），为各因素划分等级并赋予权重和点数，再用同一套因素定义、等级标准对所有岗位打分并汇总总点数，据以排出岗位相对价值序列、划分岗位工资等级（B 正确）。评价因素和评分标准必须统一、可比，不能由各岗位自定（A 错误），也不能由被评估岗位的员工本人打分（C 错误），通常由经过培训的评估委员会按统一尺度评定。岗位评估的对象是“岗位”而非“个人”，其结果用于确定岗位工资等级，不直接决定个人绩效工资（D 错误）。", "knowledge_point": "因素计点法", "sort_order": 10}, {"id": 271, "module_code": "compensation", "chapter_id": 7, "category": "exam", "qtype": "single", "stem": "某公司薪酬策略定位为“市场跟随偏上”，即整体保持市场中上水平以增强对优秀人才的吸引力。在进行外部薪酬调查数据分析时，该公司最应重点关注以下哪个分位值（　）。", "options": [{"key": "A", "text": "P10（市场中偏低水平）"}, {"key": "B", "text": "P25（市场中低水平）"}, {"key": "C", "text": "P50（市场中位数水平）"}, {"key": "D", "text": "P75（市场中上水平）"}], "answer": ["D"], "explanation": "薪酬调查通常用分位值描述市场薪酬分布：P50 表示市场中位数（有 50% 的样本薪酬低于该值），P25/P10 表示市场偏低水平，P75 表示市场中上水平（有 75% 的样本薪酬低于该值）。薪酬策略若定位“跟随”，一般参考 P50；定位“滞后/成本领先”，参考 P25 或 P10；定位“中上/领先”，则需参考 P75 及以上。本题公司定位为市场中上水平以增强人才吸引力，故应重点关注 P75。同时应注意选取规模、行业、地域、岗位可比的对标样本，否则分位数据会失真。", "knowledge_point": "薪酬分位", "sort_order": 11}, {"id": 272, "module_code": "compensation", "chapter_id": 8, "category": "exam", "qtype": "multiple", "stem": "下列激励方式中，属于长期激励、与公司长期价值（业绩或股价）绑定的有（　）。", "options": [{"key": "A", "text": "股票期权"}, {"key": "B", "text": "限制性股票"}, {"key": "C", "text": "季度绩效奖金"}, {"key": "D", "text": "员工持股计划（ESOP）"}], "answer": ["A", "B", "D"], "explanation": "长期激励将员工利益与公司长期价值绑定，通常以股权类工具实现：股票期权赋予员工在未来一定期限内按约定价格购买公司股票的权利，限制性股票规定员工须满足服务期限或业绩条件后才能解锁归属，员工持股计划（ESOP）让员工通过持有公司股份分享长期增值收益——三者均与公司长期业绩或股价挂钩，行权/归属期一般跨越多个年度，有助于绑定核心人才、抑制短期行为（A、B、D 正确）。季度绩效奖金与当季业绩直接挂钩，属于短期激励（C 错误）。", "knowledge_point": "长期激励", "sort_order": 12}, {"id": 132, "module_code": "compensation", "chapter_id": 6, "category": "exam_case", "qtype": "single", "stem": "【案例】张磊离职前表示，竞对给的不只是高薪，还有明确的期权和成长通道。林晓向王总建议先梳理薪酬结构、再谈加薪。这说明林晓认识到了什么？", "options": [{"key": "A", "text": "高薪是留人的唯一手段"}, {"key": "B", "text": "员工流失往往源于薪酬结构、成长通道与激励组合的综合性问题，加薪只是短期手段"}, {"key": "C", "text": "只要降低考核标准就能留人"}, {"key": "D", "text": "竞业协议比薪酬体系更重要"}], "answer": ["B"], "explanation": "案例指向“薪酬结构不透明 + 缺长期激励 + 成长通道不明”的复合问题。林晓的做法体现了战略性薪酬思维：先解决结构与机制，再谈水平。", "knowledge_point": "战略性薪酬", "sort_order": 100}, {"id": 133, "module_code": "compensation", "chapter_id": 7, "category": "exam_case", "qtype": "single", "stem": "【案例】林晓组织的岗位评估委员会用因素计点法完成评估后，陈工和刘姐均认可结果。这一结果之所以能被接受，最主要的原因是？", "options": [{"key": "A", "text": "分数由王总亲自确定"}, {"key": "B", "text": "使用统一、客观的评估要素与权重，过程透明、结果可解释"}, {"key": "C", "text": "分数按部门人数平均分配"}, {"key": "D", "text": "评估依据是员工的个人业绩"}], "answer": ["B"], "explanation": "因素计点法用统一要素与权重打分，参与评估的各部门代表共同校准口径，结果客观可解释，因此能减少主观争吵；评估对象是岗位而非个人业绩。", "knowledge_point": "因素计点法", "sort_order": 101}, {"id": 134, "module_code": "compensation", "chapter_id": 8, "category": "exam_case", "qtype": "single", "stem": "【案例】半年后，莱茵科技通过“福利积分制 + 虚拟股权 + 技术论坛与荣誉评选”的组合，把人才流失率从 18% 降到 9%。这一结果最直接验证了？", "options": [{"key": "A", "text": "福利预算越高，流失率必然越低"}, {"key": "B", "text": "总报酬模型——现金、福利、长期激励、认可与成长协同作用才能真正留人"}, {"key": "C", "text": "只要涨工资就能解决一切留人问题"}, {"key": "D", "text": "弹性福利只能用于大企业"}], "answer": ["B"], "explanation": "莱茵科技同时动用了弹性福利（福利维度）、虚拟股权（长期激励）、论坛与荣誉（认可与成长维度），符合总报酬模型的组合逻辑，验证了“留人是组合拳”。", "knowledge_point": "总报酬模型", "sort_order": 102}, {"id": 25, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "薪酬结构中「固定薪酬」的主要作用是什么？", "options": [{"key": "A", "text": "激励短期业绩"}, {"key": "B", "text": "保障基本生活、吸引与稳定人才"}, {"key": "C", "text": "惩罚表现不佳者"}, {"key": "D", "text": "完全取代浮动薪酬"}], "answer": ["B"], "explanation": "固定薪酬（基本工资）保障员工基本生活，提供可预期的收入，是吸引和保留人才的基础。", "knowledge_point": "", "sort_order": 0}, {"id": 26, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "岗位价值评估（如海氏评估法）的目的是什么？", "options": [{"key": "A", "text": "评价员工的绩效表现"}, {"key": "B", "text": "确定岗位之间的相对价值，为定薪提供依据"}, {"key": "C", "text": "测算公司的利润"}, {"key": "D", "text": "确定招聘渠道"}], "answer": ["B"], "explanation": "岗位价值评估衡量岗位在组织中的相对贡献与价值，是建立内部公平薪酬体系的基础。", "knowledge_point": "", "sort_order": 1}, {"id": 27, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "进行外部薪酬调研时，最重要的数据来源是？", "options": [{"key": "A", "text": "同行业、同地区、同规模企业的薪酬数据"}, {"key": "B", "text": "本公司历史数据"}, {"key": "C", "text": "员工自报收入"}, {"key": "D", "text": "招聘网站的岗位描述"}], "answer": ["A"], "explanation": "外部薪酬调研应聚焦可比市场（行业、地区、规模、岗位），保证数据具有外部竞争性参考价值。", "knowledge_point": "", "sort_order": 2}, {"id": 28, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "下列哪些属于法定的员工福利？", "options": [{"key": "A", "text": "基本养老保险"}, {"key": "B", "text": "基本医疗保险"}, {"key": "C", "text": "住房公积金"}, {"key": "D", "text": "商业补充医疗保险"}], "answer": ["A", "B", "C"], "explanation": "五险一金（养老、医疗、失业、工伤、生育保险 + 住房公积金）为法定福利；商业保险属于企业自主福利。", "knowledge_point": "", "sort_order": 3}, {"id": 29, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "judge", "stem": "宽带薪酬是指用较少的薪酬等级、较宽的薪酬区间来替代传统多等级的薪酬结构。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "宽带薪酬以少等级宽幅度的结构适应扁平化组织，鼓励员工横向发展与能力提升。", "knowledge_point": "", "sort_order": 4}, {"id": 30, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "薪酬调研中选择对标岗位的原则是？", "options": [{"key": "A", "text": "岗位职责相似、具有可比性"}, {"key": "B", "text": "岗位名称相同即可"}, {"key": "C", "text": "部门相同即可"}, {"key": "D", "text": "薪资相同即可"}], "answer": ["A"], "explanation": "对标岗位应以职责相似性和可比性为准，不能只看岗位名称或部门。", "knowledge_point": "", "sort_order": 5}, {"id": 31, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "年终奖在薪酬管理中的性质通常是？", "options": [{"key": "A", "text": "法定的强制性福利"}, {"key": "B", "text": "企业自主决定的激励性薪酬"}, {"key": "C", "text": "基本工资的一部分"}, {"key": "D", "text": "社保缴费基数"}], "answer": ["B"], "explanation": "年终奖属于企业自主决定的激励性薪酬（除非劳动合同或制度明确约定），不是法定强制福利。", "knowledge_point": "", "sort_order": 6}, {"id": 32, "module_code": "compensation", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "影响企业薪酬水平的外部因素包括？", "options": [{"key": "A", "text": "劳动力市场供求状况"}, {"key": "B", "text": "同地区同行业薪酬水平"}, {"key": "C", "text": "国家法律法规（如最低工资）"}, {"key": "D", "text": "员工个人学历"}], "answer": ["A", "B", "C"], "explanation": "市场供求、地区行业水平、法规（最低工资/社保）是外部因素；员工学历属于内部因素。", "knowledge_point": "", "sort_order": 7}, {"id": 102, "module_code": "compensation", "chapter_id": 6, "category": "practice", "qtype": "single", "stem": "下列薪酬项目中，属于浮动薪酬的是？", "options": [{"key": "A", "text": "基本工资"}, {"key": "B", "text": "岗位工资"}, {"key": "C", "text": "销售提成"}, {"key": "D", "text": "交通补贴"}], "answer": ["C"], "explanation": "浮动薪酬随绩效结果波动，销售提成与业绩直接挂钩；基本工资、岗位工资属于固定薪酬，交通补贴属于福利性津贴。", "knowledge_point": "薪酬结构设计", "sort_order": 0}, {"id": 109, "module_code": "compensation", "chapter_id": 7, "category": "practice", "qtype": "single", "stem": "岗位价值评估的对象是？", "options": [{"key": "A", "text": "岗位上任职者的工作表现"}, {"key": "B", "text": "岗位本身所承担的责任与要求"}, {"key": "C", "text": "任职者的学历和工龄"}, {"key": "D", "text": "部门的业绩排名"}], "answer": ["B"], "explanation": "岗位价值评估评估的是“岗位”而非“岗位上的人”，依据岗位说明书比较岗位的相对价值；任职者的表现由绩效管理解决。", "knowledge_point": "岗位价值评估与薪酬调查", "sort_order": 0}, {"id": 116, "module_code": "compensation", "chapter_id": 8, "category": "practice", "qtype": "single", "stem": "下列属于法定福利的是？", "options": [{"key": "A", "text": "补充商业保险"}, {"key": "B", "text": "五险一金"}, {"key": "C", "text": "弹性福利积分"}, {"key": "D", "text": "股票期权"}], "answer": ["B"], "explanation": "法定福利是国家强制要求企业提供的福利，核心是“五险一金”；补充商业保险、弹性福利、期权均属于企业自主设计的补充性福利。", "knowledge_point": "福利体系与激励设计", "sort_order": 0}, {"id": 103, "module_code": "compensation", "chapter_id": 6, "category": "practice", "qtype": "single", "stem": "薪酬带宽（pay range）指的是？", "options": [{"key": "A", "text": "公司年度薪酬预算总额"}, {"key": "B", "text": "同一薪酬等级内薪酬最低值与最高值之间的区间"}, {"key": "C", "text": "相邻两个薪酬等级中点值的差额"}, {"key": "D", "text": "市场薪酬水平的波动幅度"}], "answer": ["B"], "explanation": "薪酬带宽是同一薪酬等级内最低值与最高值之间的区间，常用最高值÷最低值衡量；相邻等级中点值的差额称为级差，两者含义不同。", "knowledge_point": "薪酬结构设计", "sort_order": 1}, {"id": 110, "module_code": "compensation", "chapter_id": 7, "category": "practice", "qtype": "single", "stem": "因素计点法给岗位打分的基本流程是？", "options": [{"key": "A", "text": "直接按市场薪酬倒推分数"}, {"key": "B", "text": "选取付酬要素，按权重分配点数，逐项打分求和"}, {"key": "C", "text": "按部门人数分配分数"}, {"key": "D", "text": "由总经理直接确定分数"}], "answer": ["B"], "explanation": "因素计点法先选取知识技能、责任、解决问题等付酬要素，按重要程度分配权重与点数，再逐项打分求和，总分决定岗位等级，客观且可解释。", "knowledge_point": "岗位价值评估与薪酬调查", "sort_order": 1}, {"id": 117, "module_code": "compensation", "chapter_id": 8, "category": "practice", "qtype": "single", "stem": "下列社保险种中，由企业全额缴纳的是？", "options": [{"key": "A", "text": "养老保险"}, {"key": "B", "text": "医疗保险"}, {"key": "C", "text": "工伤保险"}, {"key": "D", "text": "失业保险"}], "answer": ["C"], "explanation": "工伤保险由企业全额缴纳；养老、医疗、失业保险与住房公积金由企业和个人按比例共同缴纳。", "knowledge_point": "福利体系与激励设计", "sort_order": 1}, {"id": 104, "module_code": "compensation", "chapter_id": 6, "category": "practice", "qtype": "multiple", "stem": "薪酬结构设计应遵循的原则包括（ ）。", "options": [{"key": "A", "text": "保障性"}, {"key": "B", "text": "激励性"}, {"key": "C", "text": "公平性"}, {"key": "D", "text": "经济性"}], "answer": ["A", "B", "C", "D"], "explanation": "薪酬结构设计需兼顾保障性、激励性、公平性与经济性，同时满足合法性要求——只保不激是“大锅饭”，只激不保会透支信任。", "knowledge_point": "薪酬结构设计", "sort_order": 2}, {"id": 111, "module_code": "compensation", "chapter_id": 7, "category": "practice", "qtype": "single", "stem": "海氏评估法的三大评估要素是？", "options": [{"key": "A", "text": "学历、工龄、职称"}, {"key": "B", "text": "技能水平、解决问题的能力、承担的责任"}, {"key": "C", "text": "知识、体力、工作环境"}, {"key": "D", "text": "绩效、能力、态度"}], "answer": ["B"], "explanation": "海氏评估法（Hay Guide Chart）选取技能水平、解决问题的能力和承担的责任三个要素，分别套用量表打分后加权汇总，适合管理与专业岗位评估。", "knowledge_point": "岗位价值评估与薪酬调查", "sort_order": 2}, {"id": 118, "module_code": "compensation", "chapter_id": 8, "category": "practice", "qtype": "judge", "stem": "弹性福利允许员工自由选择项目组合，因此可以用来替代法定福利。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "错误。法定福利具有强制性，不可被弹性项目替代；弹性福利是在法定福利之外的补充，且预算总额通常封顶。", "knowledge_point": "福利体系与激励设计", "sort_order": 2}, {"id": 105, "module_code": "compensation", "chapter_id": 6, "category": "practice", "qtype": "judge", "stem": "销售岗位的浮动薪酬比例通常应低于研发岗位，以保证收入稳定。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "错误。浮动比例应与岗位性质匹配：销售岗业绩可衡量性强，浮动比例通常较高（可达 50% 以上）；研发岗收入宜相对稳定，浮动比例一般较低（20%～30%）。", "knowledge_point": "薪酬结构设计", "sort_order": 3}, {"id": 112, "module_code": "compensation", "chapter_id": 7, "category": "practice", "qtype": "judge", "stem": "P75 分位表示市场上 75% 的同类岗位薪酬高于该数值。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "错误。P75 表示有 75% 的样本低于该值、仅 25% 高于该值，属于市场较高水平；P50 才是市场中位值。", "knowledge_point": "岗位价值评估与薪酬调查", "sort_order": 3}, {"id": 119, "module_code": "compensation", "chapter_id": 8, "category": "practice", "qtype": "multiple", "stem": "下列属于长期激励形式的有（ ）。", "options": [{"key": "A", "text": "股票期权"}, {"key": "B", "text": "限制性股票"}, {"key": "C", "text": "虚拟股权（分红权）"}, {"key": "D", "text": "年终奖"}], "answer": ["A", "B", "C"], "explanation": "长期激励覆盖三年以上周期，把员工利益与公司长期发展绑定，包括期权、限制性股票、虚拟股权、利润分享等；年终奖属于短期浮动薪酬。", "knowledge_point": "福利体系与激励设计", "sort_order": 3}, {"id": 106, "module_code": "compensation", "chapter_id": 6, "category": "practice", "qtype": "single", "stem": "依据亚当斯公平理论，员工将自己的投入产出比与市场上同类岗位人员的回报比较，这体现的是？", "options": [{"key": "A", "text": "内部公平"}, {"key": "B", "text": "外部公平"}, {"key": "C", "text": "个体公平"}, {"key": "D", "text": "程序公平"}], "answer": ["B"], "explanation": "与外部市场同行比较产生“外部公平”感知；与组织内同事比较是“内部公平”；与自己过去的投入产出比比较是“个体公平”。", "knowledge_point": "薪酬结构设计", "sort_order": 4}, {"id": 113, "module_code": "compensation", "chapter_id": 7, "category": "practice", "qtype": "multiple", "stem": "外部薪酬调查的数据来源通常包括（ ）。", "options": [{"key": "A", "text": "专业咨询机构的薪酬报告"}, {"key": "B", "text": "招聘平台的薪资数据"}, {"key": "C", "text": "同行企业 HR 之间的数据交换"}, {"key": "D", "text": "员工个人的薪资期望"}], "answer": ["A", "B", "C"], "explanation": "薪酬调查采集的是客观的市场数据，来源包括咨询报告、招聘平台、同行交换、猎头反馈、政府指导价位等；员工个人期望属于内部诉求，不是市场数据来源。", "knowledge_point": "岗位价值评估与薪酬调查", "sort_order": 4}, {"id": 120, "module_code": "compensation", "chapter_id": 8, "category": "practice", "qtype": "single", "stem": "依据赫茨伯格双因素理论，工资、福利、工作条件属于？", "options": [{"key": "A", "text": "激励因素"}, {"key": "B", "text": "保健因素"}, {"key": "C", "text": "成就因素"}, {"key": "D", "text": "成长因素"}], "answer": ["B"], "explanation": "保健因素（工资、福利、工作条件等）不具备会引起不满，具备也只消除不满而不带来满意；成就感、认可、成长等激励因素才是驱动投入的真正引擎。", "knowledge_point": "福利体系与激励设计", "sort_order": 4}, {"id": 264, "module_code": "compensation", "chapter_id": 6, "category": "practice", "qtype": "judge", "stem": "薪酬体系设计应首先回答\"组织要什么行为、我们奖励什么\"，让薪酬成为传递战略信号的工具，而非单纯的成本支出。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "尤里奇战略伙伴视角：薪酬是战略执行抓手，设计前应明确战略所需行为，让薪酬投资驱动正确行为。", "knowledge_point": "薪酬结构设计", "sort_order": 5}, {"id": 265, "module_code": "compensation", "chapter_id": 8, "category": "practice", "qtype": "single", "stem": "根据杨三角理论，薪酬激励设计主要影响组织能力的哪个维度？", "options": [{"key": "A", "text": "员工能力（会不会）"}, {"key": "B", "text": "员工思维（愿不愿）"}, {"key": "C", "text": "员工治理（机制与制度）"}, {"key": "D", "text": "员工规模"}], "answer": ["B"], "explanation": "杨三角三支柱：员工思维解决\"愿不愿\"——激励与认同直接影响员工意愿。", "knowledge_point": "福利体系与激励设计", "sort_order": 5}, {"id": 107, "module_code": "compensation", "chapter_id": 6, "category": "practice_case", "qtype": "single", "stem": "【案例】张磊离职后，林晓与他面谈，发现他除了不满薪资水平，更在意“薪酬结构里看不到明确的上升通道”。结合本章知识，林晓最应该做的是？", "options": [{"key": "A", "text": "立即给张磊加薪 40% 挽留"}, {"key": "B", "text": "梳理薪酬结构，明确固定/浮动构成与调薪机制，让员工看到涨薪路径"}, {"key": "C", "text": "把所有研发工程师工资统一到同一数额"}, {"key": "D", "text": "要求张磊签竞业协议"}], "answer": ["B"], "explanation": "案例揭示的是薪酬结构不透明、缺少上升通道的结构性问题。加薪挽留只能解一时之急，且会引发内部不公平；应通过优化薪酬结构、明确调薪机制从根本上解决。", "knowledge_point": "薪酬结构设计", "sort_order": 100}, {"id": 114, "module_code": "compensation", "chapter_id": 7, "category": "practice_case", "qtype": "single", "stem": "【案例】陈工认为研发岗最值钱、刘姐认为销售岗最值钱，两人争执不下，王总让林晓“拿数据说话”。林晓最合理的做法是？", "options": [{"key": "A", "text": "由王总拍板决定谁的岗位值钱"}, {"key": "B", "text": "组织跨部门岗位评估委员会，用因素计点法按统一标准评估各岗位价值"}, {"key": "C", "text": "按各部门业绩高低直接排序"}, {"key": "D", "text": "按工龄长短确定岗位等级"}], "answer": ["B"], "explanation": "岗位价值必须用统一、客观的评估方法衡量。跨部门评估委员会用因素计点法打分，能避免主观争论、让结果可解释；“老板拍板”或“按业绩/工龄”都偏离了岗位价值评估的本意。", "knowledge_point": "岗位价值评估与薪酬调查", "sort_order": 100}, {"id": 121, "module_code": "compensation", "chapter_id": 8, "category": "practice_case", "qtype": "single", "stem": "【案例】员工满意度调研显示，30% 的年轻员工觉得公司福利“像老年套餐”，而硬件工程师最想要的“加班打车报销”并不在福利清单里。结合本章知识，林晓应该？", "options": [{"key": "A", "text": "取消所有福利，把钱折算进工资"}, {"key": "B", "text": "在预算内重构福利为弹性福利积分制，让员工按需自选"}, {"key": "C", "text": "维持现状，福利毕竟是额外的"}, {"key": "D", "text": "只给研发部门单独发福利"}], "answer": ["B"], "explanation": "案例反映的是福利供给与员工需求错位。弹性福利把选择权交给员工、按需组合，能显著提升福利感知度，且预算总额封顶、成本可控；取消福利或差别化对待都不合适。", "knowledge_point": "福利体系与激励设计", "sort_order": 100}, {"id": 108, "module_code": "compensation", "chapter_id": 6, "category": "practice_case", "qtype": "single", "stem": "【案例】王总要求林晓“先别急着加薪”，林晓与王总确认公司战略为“扩张期、产品差异化”后，将薪酬策略定为“关键岗位领先、支持岗位跟随”。这种做法的核心依据是？", "options": [{"key": "A", "text": "成本最低原则"}, {"key": "B", "text": "战略性薪酬——薪酬策略应与公司战略对齐"}, {"key": "C", "text": "平均主义原则"}, {"key": "D", "text": "行业惯例，所有公司都这么做"}], "answer": ["B"], "explanation": "战略性薪酬强调薪酬体系从公司战略出发：差异化战略下关键人才（研发）值得以领先策略投入，非关键岗位用跟随策略控制成本，即“混合策略”。", "knowledge_point": "薪酬结构设计", "sort_order": 101}, {"id": 115, "module_code": "compensation", "chapter_id": 7, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓发现公司工资大多是“入职时谈出来的”，同岗不同酬、岗位间价值倒挂。为建立内部公平与外部公平，林晓先后做了岗位评估和市场薪酬调查。下列说法正确的是？", "options": [{"key": "A", "text": "岗位评估解决外部公平，薪酬调查解决内部公平"}, {"key": "B", "text": "岗位评估解决内部公平，薪酬调查解决外部公平"}, {"key": "C", "text": "二者都只解决内部公平"}, {"key": "D", "text": "薪酬调查属于法定要求，与公平无关"}], "answer": ["B"], "explanation": "岗位价值评估通过统一标准建立岗位等级序列，解决内部公平；薪酬调查对标外部市场数据，解决外部公平；两者结合才能画出科学的薪酬曲线。", "knowledge_point": "岗位价值评估与薪酬调查", "sort_order": 101}, {"id": 122, "module_code": "compensation", "chapter_id": 8, "category": "practice_case", "qtype": "single", "stem": "【案例】为对抗竞对挖角，林晓为研发骨干设计了归属期三年的虚拟股权方案，同时建立技术论坛与“硬件之星”评选。这套组合体现的核心理念是？", "options": [{"key": "A", "text": "只靠股权激励就能解决留人问题"}, {"key": "B", "text": "用总报酬组合拳——现金之外的长期激励与非物质激励共同发力"}, {"key": "C", "text": "福利预算越大越好"}, {"key": "D", "text": "股权激励无需设定条件"}], "answer": ["B"], "explanation": "总报酬模型提示留人是“组合拳”：虚拟股权属长期激励，把核心人才与公司长期绑定；技术论坛与荣誉评选属非物质激励，满足成长与认可需求，二者协同发力。", "knowledge_point": "福利体系与激励设计", "sort_order": 101}, {"id": 156, "module_code": "employee-relations", "chapter_id": 9, "category": "exam", "qtype": "single", "stem": "关于员工生命周期管理，下列说法最准确的是？", "options": [{"key": "A", "text": "生命周期管理只关注离职环节"}, {"key": "B", "text": "每个生命周期触点都会影响员工与组织的心理契约，其中入职与离职是心理契约最敏感、最容易受损的时点"}, {"key": "C", "text": "员工生命周期管理属于薪酬模块的职责"}, {"key": "D", "text": "员工生命周期仅包含入职与离职两个环节"}], "answer": ["B"], "explanation": "生命周期覆盖吸引到离职的全触点，每个触点都塑造心理契约；入职期承诺与体验的落差、离职期的体验直接影响信任与口碑，是特别敏感的时点。", "knowledge_point": "员工生命周期", "sort_order": 0}, {"id": 296, "module_code": "employee-relations", "chapter_id": 10, "category": "exam", "qtype": "judge", "stem": "Google“亚里士多德项目”对团队的研究显示，高绩效团队的首要决定因素是成员整体能力，心理安全感的作用相对有限。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "该研究最重要的发现是心理安全感——成员敢于表达不同意见而不担心受罚——是高绩效团队的第一要素，而非成员能力。", "knowledge_point": "心理安全感", "sort_order": 0}, {"id": 297, "module_code": "employee-relations", "chapter_id": 11, "category": "exam", "qtype": "judge", "stem": "员工正式提交离职申请，通常说明其已经过慎重考虑、去意已决，此时 HR 应尽快为其办理离职手续，继续挽留只会耽误双方的时间。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "该说法错误。员工提出离职往往是其决策链条的“最后一环”，此前大多经历过犹豫和观望期，而许多离职动因（如工作内容、发展空间、与直接上级的关系）都是可以改善的。对核心人才而言，提交离职申请的窗口期恰恰是挽留的黄金时机：HR 应通过面谈了解真实原因，评估员工的可挽留性与挽留成本，必要时请直属上级或更高层级介入挽留；即使挽留失败，规范的离职面谈与手续办理同样不可省略——离职员工的体验与口碑直接塑造组织的雇主品牌，影响在职员工士气与后续招聘。因此“放弃挽留、立即办手续”的做法是错误的。", "knowledge_point": "挽留时机", "sort_order": 0}, {"id": 157, "module_code": "employee-relations", "chapter_id": 9, "category": "exam", "qtype": "multiple", "stem": "关于入职引导与试用期管理的衔接，下列做法正确的有？", "options": [{"key": "A", "text": "入职引导结束后管理即告结束，无需后续跟进"}, {"key": "B", "text": "试用期目标应在入职初期由主管与新人共同设定"}, {"key": "C", "text": "在 30 天、60 天等节点安排正式反馈"}, {"key": "D", "text": "转正评估基于事先明确、双方认可的标准"}], "answer": ["B", "C", "D"], "explanation": "入职引导与试用期管理是一段连续旅程，目标前置、节点反馈、标准透明缺一不可；\"引导完就放手\"是常见误区。", "knowledge_point": "试用期管理", "sort_order": 1}, {"id": 158, "module_code": "employee-relations", "chapter_id": 9, "category": "exam", "qtype": "judge", "stem": "心理契约虽未成文，但入职引导、试用期反馈等真实体验会持续塑造它；组织承诺与员工体验落差过大，会导致新人快速流失。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "心理契约是员工主观建构的相互期望，靠日常体验持续塑造；入职期落差是新人流失的深层原因之一。", "knowledge_point": "心理契约", "sort_order": 2}, {"id": 159, "module_code": "employee-relations", "chapter_id": 10, "category": "exam", "qtype": "single", "stem": "关于敬业度与业务结果的关系，盖洛普等研究通常支持的观点是？", "options": [{"key": "A", "text": "敬业度与业务结果无关"}, {"key": "B", "text": "敬业度较高的团队往往在效率、质量、留任等指标上表现更好"}, {"key": "C", "text": "只有提高薪酬才能提升敬业度"}, {"key": "D", "text": "敬业度等同于员工出勤率"}], "answer": ["B"], "explanation": "多项研究显示敬业度（认同与投入）与效率、质量、留任等业务指标正相关；薪酬属于保健因素，不能单独决定敬业度。", "knowledge_point": "敬业度", "sort_order": 3}, {"id": 160, "module_code": "employee-relations", "chapter_id": 10, "category": "exam", "qtype": "multiple", "stem": "处理冲突的完整步骤通常包括？", "options": [{"key": "A", "text": "冷静介入，分别了解事实，不偏听偏信"}, {"key": "B", "text": "识别冲突类型与根源"}, {"key": "C", "text": "情绪安抚与分别沟通"}, {"key": "D", "text": "促成基于共同目标的协商，并跟进执行"}], "answer": ["A", "B", "C", "D"], "explanation": "冲突处理是\"了解事实→识别根源→安抚情绪→协商共识→跟进落地\"的闭环，缺一环都可能复发。", "knowledge_point": "冲突处理", "sort_order": 4}, {"id": 162, "module_code": "employee-relations", "chapter_id": 11, "category": "exam", "qtype": "single", "stem": "在下列哪种情境下，员工最可能说出真实的离职原因？", "options": [{"key": "A", "text": "直属主管在场的公开谈话"}, {"key": "B", "text": "私密、中立、承诺保密且不评判的谈话"}, {"key": "C", "text": "在离职手续办理大厅当众询问"}, {"key": "D", "text": "带着挽留目的的薪酬谈判"}], "answer": ["B"], "explanation": "真实原因依赖安全感：私密环境、中立身份、保密承诺、不评判的态度才能降低员工的防御与顾虑。", "knowledge_point": "离职面谈", "sort_order": 6}, {"id": 163, "module_code": "employee-relations", "chapter_id": 11, "category": "exam", "qtype": "multiple", "stem": "关于离职挽留与离职数据分析，下列说法正确的有？", "options": [{"key": "A", "text": "挽留前应先评估员工价值与离职原因的可解决性"}, {"key": "B", "text": "\"为留而留\"开出破坏内部公平的特殊条件会埋下隐患"}, {"key": "C", "text": "离职原因应结构化记录，并定期按岗位、司龄、部门维度分析"}, {"key": "D", "text": "只要加薪就能挽留所有核心员工"}], "answer": ["A", "B", "C"], "explanation": "挽留需先评估价值与原因可解决性，破坏公平的挽留伤害整体；离职数据要结构化、多维度分析；薪酬并非万能原因。", "knowledge_point": "离职挽留与离职数据分析", "sort_order": 7}, {"id": 274, "module_code": "employee-relations", "chapter_id": 9, "category": "exam", "qtype": "single", "stem": "某公司为压缩用人成本，将新员工入职引导压缩为半天“制度与流程讲解”，随后三个月内试用期员工流失率明显上升。从员工关系管理的角度看，最直接的原因在于？", "options": [{"key": "A", "text": "入职引导压缩导致薪酬核算出错，员工因欠薪离职"}, {"key": "B", "text": "入职引导承担组织社会化功能，被弱化后新员工难以完成从“外部人”到“内部人”的转变，心理契约受损，融入感与留任意愿下降"}, {"key": "C", "text": "入职引导属于培训模块职责，与员工关系管理无关，流失率上升应归因于招聘标准下降"}, {"key": "D", "text": "试用期流失由外部劳动力市场环境决定，与入职引导无因果关系"}], "answer": ["B"], "explanation": "入职引导（Onboarding）的核心功能是组织社会化——帮助新员工建立角色认知、人际网络与组织认同，实现从“外部人”到“内部人”的转变。压缩为单一的制度讲解会弱化这一功能，使新人对职责、团队与组织缺乏清晰预期和归属感；而入职期正是心理契约（员工对组织承诺的感知与自身期望之间的默契）最敏感、最容易受损的时点，预期落差会直接表现为融入慢、试用期流失。A 将流失归因于薪酬核算错误缺乏题干依据；C 混淆职责归属；D 否定内因、把流失完全归因于外部环境，均不准确。", "knowledge_point": "入职引导", "sort_order": 8}, {"id": 275, "module_code": "employee-relations", "chapter_id": 10, "category": "exam", "qtype": "single", "stem": "某次员工满意度调查显示综合满意度高达 92%，但同期敬业度调查结果却明显偏低。关于这一现象，下列解释最准确的是？", "options": [{"key": "A", "text": "两份调查必然有一份失真，应以满意度结果为准"}, {"key": "B", "text": "满意度衡量员工对报酬、环境等现有条件的满意程度，敬业度衡量员工对工作的认同、投入与承诺，两者是不同构念，员工可以“满意但不投入”，出现背离属正常现象"}, {"key": "C", "text": "满意度高说明员工必然积极投入工作，敬业度偏低只能归因于统计口径错误"}, {"key": "D", "text": "满意度与敬业度是同一概念的两个名称，数据不可能背离"}], "answer": ["B"], "explanation": "满意度（satisfaction）与敬业度（engagement）是两个不同层次的构念：满意度是员工对现有条件（薪酬、工作环境、人际关系等）的“态度评价”，偏向后验性的满足感；敬业度则是员工在认知、情感、行为上对工作的投入，以及对组织目标和价值的认同与承诺，具有更强的前瞻性与行为指向。“满意但不投入”并不矛盾——员工完全可能对现状满意，却缺乏工作激情、发展意愿与目标认同。因此满意度高而敬业度低是可能出现的现象，应分别设计测量工具和干预策略，而不能相互替代或简单以一方否定另一方。", "knowledge_point": "满意度与敬业度", "sort_order": 9}, {"id": 276, "module_code": "employee-relations", "chapter_id": 10, "category": "exam", "qtype": "multiple", "stem": "两名团队成员因项目分工与责任归属发生激烈争执，互不相让。作为 HR，你介入处理时应采取的做法包括？", "options": [{"key": "A", "text": "分别单独倾听双方陈述，避免只听一面之词"}, {"key": "B", "text": "引导双方就事论事，聚焦问题与事实本身而非人身攻击"}, {"key": "C", "text": "为“杀一儆百”，在部门例会上当众批评过错一方"}, {"key": "D", "text": "引导双方共同界定问题、探讨并商定可执行的解决方案"}, {"key": "E", "text": "直接依据职位高低判定责任归属，无需听取基层员工意见"}], "answer": ["A", "B", "D"], "explanation": "处理员工冲突应遵循“先倾听、后判断，就事论事、共同求解”的原则：分别单独了解双方立场，可以避免信息偏听、还原事实全貌（A）；把讨论锚定在问题与事实而非人的对错上，可防止冲突升级为人身对立，保护工作关系（B）；冲突双方共同参与问题界定与方案制定，方案更贴近实际、更容易被执行和接受（D）。当众批评会当众损伤当事人尊严，激化矛盾、破坏团队信任（C 错误）；以职位高低定对错有失公允，会抑制真实表达、加剧积怨（E 错误）。", "knowledge_point": "冲突处理", "sort_order": 10}, {"id": 277, "module_code": "employee-relations", "chapter_id": 11, "category": "exam", "qtype": "multiple", "stem": "关于离职面谈的实施要点，下列做法正确的有？", "options": [{"key": "A", "text": "选择私密、安静且不受打扰的场所，让员工感到安全、愿意说真话"}, {"key": "B", "text": "面谈前查阅员工档案、绩效记录与近期沟通记录，带着背景信息提问"}, {"key": "C", "text": "对员工提出的批评意见当场逐条反驳，坚决维护公司立场"}, {"key": "D", "text": "面谈中反复追问员工下家去向等个人隐私，用于判断其忠诚度"}, {"key": "E", "text": "面谈结束后将共性问题整理成改进清单，反馈并跟进相关部门落实"}], "answer": ["A", "B", "E"], "explanation": "离职面谈的目的在于获取真实、有价值的反馈以推动组织改进：私密安静、不被打扰的环境能降低员工顾虑，使其愿意坦露真实离职原因（A）；事前了解其档案、绩效与近期沟通情况，提问才能有的放矢、提高信息质量（B）；面谈成果应形成改进闭环，把共性问题反馈给相关部门并跟进整改，真正发挥面谈的管理价值（E）。当场逐条反驳会使面谈陷入对抗，员工从此闭口不言，组织将失去真实信息（C 错误）；追问下家去向等隐私既侵犯员工合法权益，也偏离了面谈改进管理的初衷（D 错误）。", "knowledge_point": "离职面谈", "sort_order": 11}, {"id": 164, "module_code": "employee-relations", "chapter_id": 11, "category": "exam_case", "qtype": "single", "stem": "【案例】莱茵科技研发核心岗位主动离职率从 5% 升至 12%，林晓怀疑与跨部门协作和成长空间有关。要系统验证这一判断，最恰当的做法是？", "options": [{"key": "A", "text": "直接宣布全员加薪以稳定人心"}, {"key": "B", "text": "对离职员工逐一开展结构化离职面谈，并结合留任访谈与匿名调研交叉验证"}, {"key": "C", "text": "让各部门主管自行调查后口头汇报"}, {"key": "D", "text": "忽略数据波动，仅安抚 CEO 情绪"}], "answer": ["B"], "explanation": "验证组织级判断需要系统数据：结构化面谈获取原因、留任访谈与匿名调研交叉验证，才能避免个别失真样本与主管主观汇报的偏差。", "knowledge_point": "离职数据分析", "sort_order": 100}, {"id": 165, "module_code": "employee-relations", "chapter_id": 10, "category": "exam_case", "qtype": "single", "stem": "【案例】陈工与刘姐因交付时间分歧升级为部门对立，林晓决定介入。下列做法中她最不应该采取的是？", "options": [{"key": "A", "text": "分别访谈双方，了解各自事实与立场"}, {"key": "B", "text": "组织\"事实对齐会\"，聚焦数据与共同目标"}, {"key": "C", "text": "在全员会上公开判定刘姐错误，以儆效尤"}, {"key": "D", "text": "推动建立跨部门例会机制，固化沟通"}], "answer": ["C"], "explanation": "当众判定一方错误会激化关系冲突、损害当事人尊严，让\"任务冲突\"恶化成\"关系冲突\"，是冲突处理的大忌。", "knowledge_point": "冲突处理", "sort_order": 101}, {"id": 166, "module_code": "employee-relations", "chapter_id": 11, "category": "exam_case", "qtype": "single", "stem": "【案例】一位高级硬件工程师提出离职，林晓评估其属核心人才、离职主因\"成长空间\"部分可解决，通过给予新项目主导角色挽留成功；同时推动公司建立技术晋升通道。这一系列做法体现的员工关系理念是？", "options": [{"key": "A", "text": "以惩罚手段阻止员工离职"}, {"key": "B", "text": "把员工当作可随时替换的一次性资源"}, {"key": "C", "text": "既在个体层面针对真实原因挽留，又在组织层面通过机制改进预防流失"}, {"key": "D", "text": "只注重离职面谈的形式与话术"}], "answer": ["C"], "explanation": "林晓的做法是\"个体挽留 + 组织改进\"双轨：对个体给针对性方案，对组织建预防机制，这正是员工关系管理\"管住流失、改进组织\"的价值所在。", "knowledge_point": "离职挽留与组织改进", "sort_order": 102}, {"id": 33, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "员工入职管理的第一步通常是？", "options": [{"key": "A", "text": "发放录用通知（Offer）"}, {"key": "B", "text": "安排座位"}, {"key": "C", "text": "签订劳动合同"}, {"key": "D", "text": "加入工作群"}], "answer": ["A"], "explanation": "入职管理始于录用沟通与 Offer 发放，随后完成背景核验、入职手续办理与入职引导。", "knowledge_point": "", "sort_order": 0}, {"id": 34, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "员工关系管理的核心目标是什么？", "options": [{"key": "A", "text": "让员工无条件服从管理"}, {"key": "B", "text": "建立和谐的劳动关系，提升员工敬业度"}, {"key": "C", "text": "尽可能降低用工成本"}, {"key": "D", "text": "减少所有员工交流"}], "answer": ["B"], "explanation": "员工关系管理以建立和谐劳动关系、提升信任与敬业度、预防劳动争议为核心目标。", "knowledge_point": "", "sort_order": 1}, {"id": 35, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "处理员工冲突时，第一步应该做什么？", "options": [{"key": "A", "text": "立即处罚当事人"}, {"key": "B", "text": "倾听双方陈述，了解事实全貌"}, {"key": "C", "text": "让冲突自行平息"}, {"key": "D", "text": "公开批评"}], "answer": ["B"], "explanation": "处理冲突应先倾听、收集事实，避免先入为主，再寻找共同利益点进行调解。", "knowledge_point": "", "sort_order": 2}, {"id": 36, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "离职面谈的主要目的是什么？", "options": [{"key": "A", "text": "挽留每一位离职员工"}, {"key": "B", "text": "了解离职原因，改进管理，降低流失"}, {"key": "C", "text": "办理离职手续"}, {"key": "D", "text": "评估员工绩效"}], "answer": ["B"], "explanation": "离职面谈的核心价值在于获取真实离职原因与组织反馈，推动管理改进，同时维护雇主品牌。", "knowledge_point": "", "sort_order": 3}, {"id": 37, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "试用期员工提出离职，一般需提前几天通知用人单位？", "options": [{"key": "A", "text": "1 天"}, {"key": "B", "text": "3 天"}, {"key": "C", "text": "7 天"}, {"key": "D", "text": "30 天"}], "answer": ["B"], "explanation": "《劳动合同法》规定，试用期内劳动者提前 3 日通知用人单位即可解除劳动合同。", "knowledge_point": "", "sort_order": 4}, {"id": 38, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "新员工入职第一天，最重要的环节是？", "options": [{"key": "A", "text": "入职引导（Orientation）"}, {"key": "B", "text": "直接分配大量工作"}, {"key": "C", "text": "立即参加考核"}, {"key": "D", "text": "签署离职协议"}], "answer": ["A"], "explanation": "入职引导帮助新员工了解公司文化、制度与岗位，是提高留存率和融入速度的关键。", "knowledge_point": "", "sort_order": 5}, {"id": 39, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "处理员工投诉时应遵循哪些原则？", "options": [{"key": "A", "text": "保密原则"}, {"key": "B", "text": "及时响应"}, {"key": "C", "text": "公平公正"}, {"key": "D", "text": "公开批评当事人"}], "answer": ["A", "B", "C"], "explanation": "员工投诉处理应保密、及时、公平公正；公开批评会激化矛盾并侵犯员工权益。", "knowledge_point": "", "sort_order": 6}, {"id": 40, "module_code": "employee-relations", "chapter_id": null, "category": "placement", "qtype": "judge", "stem": "员工手册经民主程序制定并公示后，可以作为劳动合同的附件约束双方权利义务。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "经民主程序制定并向员工公示告知的员工手册具有约束力，可作为劳动争议处理的依据。", "knowledge_point": "", "sort_order": 7}, {"id": 135, "module_code": "employee-relations", "chapter_id": 9, "category": "practice", "qtype": "single", "stem": "关于入职引导（Orientation），下列说法正确的是？", "options": [{"key": "A", "text": "入职引导只在入职第一天进行，之后不再需要"}, {"key": "B", "text": "入职引导应覆盖组织层面（文化制度）与岗位层面（职责资源），并分阶段推进"}, {"key": "C", "text": "入职引导属于培训模块的职责，与员工关系管理无关"}, {"key": "D", "text": "入职引导以单向宣讲为主，不需要互动"}], "answer": ["B"], "explanation": "入职引导的目标是完成\"信息、连接、承诺\"三件事，需要覆盖组织、岗位、人际三个层面，并分\"第一天/第一周/第一个月\"推进；只做一天、只讲 PPT 是常见误区。", "knowledge_point": "员工入职与全生命周期管理", "sort_order": 0}, {"id": 142, "module_code": "employee-relations", "chapter_id": 10, "category": "practice", "qtype": "single", "stem": "关于员工满意度与敬业度，下列说法正确的是？", "options": [{"key": "A", "text": "满意度就是敬业度，二者含义相同"}, {"key": "B", "text": "满意度高必然意味着员工敬业"}, {"key": "C", "text": "敬业度指员工在情感与认知上认同组织、愿意付出额外努力，与业务结果关联更强"}, {"key": "D", "text": "敬业度主要依靠提高薪酬来实现"}], "answer": ["C"], "explanation": "满意度针对工作条件（保健因素），敬业度针对认同与投入（激励因素）；满意度高不等于敬业，敬业度与业务结果关联更强。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 0}, {"id": 149, "module_code": "employee-relations", "chapter_id": 11, "category": "practice", "qtype": "single", "stem": "核心员工离职的总成本中，最容易被组织低估的是？", "options": [{"key": "A", "text": "招聘重置成本"}, {"key": "B", "text": "培训投入成本"}, {"key": "C", "text": "隐性成本（业务中断、知识流失、团队士气受损）"}, {"key": "D", "text": "离职补偿金"}], "answer": ["C"], "explanation": "显性成本易于核算，而业务中断、知识流失、士气影响等隐性成本往往数倍于显性成本，最容易被低估。", "knowledge_point": "离职管理与离职面谈", "sort_order": 0}, {"id": 136, "module_code": "employee-relations", "chapter_id": 9, "category": "practice", "qtype": "multiple", "stem": "一套完整的入职流程通常包含以下哪些环节？", "options": [{"key": "A", "text": "入职前的准备（工位、电脑、账号、欢迎信息）"}, {"key": "B", "text": "第一天的组织与岗位介绍"}, {"key": "C", "text": "试用期关键节点的目标设定与反馈"}, {"key": "D", "text": "入职引导效果的跟进与评估"}], "answer": ["A", "B", "C", "D"], "explanation": "入职流程是贯穿入职前、第一天、第一周与整个试用期的旅程，准备、介绍、目标设定、反馈与评估缺一不可。", "knowledge_point": "员工入职与全生命周期管理", "sort_order": 1}, {"id": 143, "module_code": "employee-relations", "chapter_id": 10, "category": "practice", "qtype": "multiple", "stem": "按托马斯-基尔曼冲突处理模式，冲突处理的五种策略包括？", "options": [{"key": "A", "text": "竞争"}, {"key": "B", "text": "协作"}, {"key": "C", "text": "妥协"}, {"key": "D", "text": "回避"}, {"key": "E", "text": "迁就"}], "answer": ["A", "B", "C", "D", "E"], "explanation": "五种策略按\"坚持自我程度 × 合作他人程度\"划分，分别适用不同情境，没有绝对最优，需按情境选择。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 1}, {"id": 150, "module_code": "employee-relations", "chapter_id": 11, "category": "practice", "qtype": "multiple", "stem": "关于离职面谈，下列技巧正确的有？", "options": [{"key": "A", "text": "选择私密、安静的环境，并向员工承诺保密"}, {"key": "B", "text": "多使用开放式提问，让员工先说"}, {"key": "C", "text": "对员工陈述的离职原因不评判、不反驳"}, {"key": "D", "text": "由直属主管当面进行批评教育，帮助员工改正"}], "answer": ["A", "B", "C"], "explanation": "面谈要中立、保密、倾听、不评判；由直属主管当面批评会压制真话，违背面谈\"获取真实原因\"的目的。", "knowledge_point": "离职管理与离职面谈", "sort_order": 1}, {"id": 137, "module_code": "employee-relations", "chapter_id": 9, "category": "practice", "qtype": "judge", "stem": "心理契约是员工与组织之间未成文的相互期望。入职体验是心理契约形成的关键期，入职引导做得好可以增强新员工对组织的信任与承诺。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "心理契约基于员工的主观感知，入职期是它形成最敏感的窗口，良好的入职体验能奠定信任基础，体验落差过大则会导致承诺受损。", "knowledge_point": "员工入职与全生命周期管理", "sort_order": 2}, {"id": 144, "module_code": "employee-relations", "chapter_id": 10, "category": "practice", "qtype": "judge", "stem": "任务冲突指成员对工作内容或方案看法不同，适度的任务冲突经过有效管理可以提升决策质量；而关系冲突通常对团队有害，需要及时干预。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "任务冲突聚焦\"事\"，可激发更好的方案；关系冲突聚焦\"人\"，消耗信任与协作，一般应及时处理。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 2}, {"id": 151, "module_code": "employee-relations", "chapter_id": 11, "category": "practice", "qtype": "judge", "stem": "离职面谈的主要目的不是说服员工留下，而是获取真实离职原因、为组织改进提供依据；挽留只是离职管理中的一个环节。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "离职面谈是\"组织诊断\"工具，重点是获取真实原因并结构化分析、推动改进；挽留发生在面谈之前或之中，但不是唯一目的。", "knowledge_point": "离职管理与离职面谈", "sort_order": 2}, {"id": 138, "module_code": "employee-relations", "chapter_id": 9, "category": "practice", "qtype": "single", "stem": "员工生命周期通常依次包括哪几个阶段？", "options": [{"key": "A", "text": "吸引→招聘→入职→发展→保留→离职"}, {"key": "B", "text": "招聘→培训→绩效→薪酬→晋升"}, {"key": "C", "text": "入职→试用→转正→加薪→升职"}, {"key": "D", "text": "面试→录用→培训→考核→淘汰"}], "answer": ["A"], "explanation": "员工生命周期以雇佣关系全程为视角：吸引、招聘、入职、发展、保留、离职。每个触点都会影响员工与组织的心理契约。", "knowledge_point": "员工入职与全生命周期管理", "sort_order": 3}, {"id": 145, "module_code": "employee-relations", "chapter_id": 10, "category": "practice", "qtype": "single", "stem": "处理跨部门冲突时，HR 最恰当的第一步是？", "options": [{"key": "A", "text": "在会议上当场判定谁对谁错"}, {"key": "B", "text": "分别与各方单独沟通，了解各自的事实与立场"}, {"key": "C", "text": "直接上报 CEO，由高层裁决"}, {"key": "D", "text": "召开全员大会公开讨论"}], "answer": ["B"], "explanation": "处理冲突的第一步是\"冷静介入、还原事实\"，分别访谈可以避免偏听偏信；当众判定或公开讨论会激化情绪、伤害当事人。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 3}, {"id": 152, "module_code": "employee-relations", "chapter_id": 11, "category": "practice", "qtype": "single", "stem": "面对核心员工提出离职，正确的挽留评估顺序是？", "options": [{"key": "A", "text": "先加薪，再问原因"}, {"key": "B", "text": "先评估挽留价值（绩效与可替代性），再分析离职原因是否可解决，最后给出针对性方案"}, {"key": "C", "text": "无条件满足员工提出的所有条件"}, {"key": "D", "text": "立即批准离职，不做任何挽留"}], "answer": ["B"], "explanation": "挽留要先判断\"值不值得留\"（价值），再判断\"能不能留住\"（原因可解决性），最后给针对原因的方案；加薪万能或无条件满足都会破坏公平。", "knowledge_point": "离职管理与离职面谈", "sort_order": 3}, {"id": 139, "module_code": "employee-relations", "chapter_id": 9, "category": "practice", "qtype": "multiple", "stem": "关于试用期管理，下列做法正确的有？", "options": [{"key": "A", "text": "入职初期由直属主管与新人共同设定清晰的试用期目标"}, {"key": "B", "text": "在 30 天、60 天等节点安排正式反馈"}, {"key": "C", "text": "转正标准提前明确并让新人知晓"}, {"key": "D", "text": "试用期管理完全交给用人部门，HR 无需参与"}], "answer": ["A", "B", "C"], "explanation": "试用期管理的核心是\"目标前置、节点反馈、标准透明\"，HR 需要跟进全流程；完全放养会导致标准不清、反馈缺失。", "knowledge_point": "员工入职与全生命周期管理", "sort_order": 4}, {"id": 146, "module_code": "employee-relations", "chapter_id": 10, "category": "practice", "qtype": "multiple", "stem": "关于坦诚文化（如《奈飞文化手册》所倡导的理念），下列说法正确的有？", "options": [{"key": "A", "text": "坦诚沟通以高信任与高人才密度为前提"}, {"key": "B", "text": "坦诚意味着可以对员工的人格进行批评"}, {"key": "C", "text": "坦诚应\"对事不对人\"，区分事实与观点"}, {"key": "D", "text": "坦诚文化的落地需要组织提供心理安全感"}], "answer": ["A", "C", "D"], "explanation": "坦诚是\"基于事实与善意的直言\"，对事不对人；批评人格、人身攻击不是坦诚，是粗暴。坦诚需要信任、人才密度与心理安全感支撑。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 4}, {"id": 153, "module_code": "employee-relations", "chapter_id": 11, "category": "practice", "qtype": "multiple", "stem": "关于留任访谈（Stay Interview）与离职面谈，下列说法正确的有？", "options": [{"key": "A", "text": "留任访谈面向在职员工，用于提前发现流失风险"}, {"key": "B", "text": "离职面谈是事后视角，存在员工不说真话的局限"}, {"key": "C", "text": "两者应相互结合，并与匿名调研、绩效数据交叉验证"}, {"key": "D", "text": "留任访谈只需开展一次即可长期有效"}], "answer": ["A", "B", "C"], "explanation": "留任访谈是事前预警、离职面谈是事后复盘，二者互补并需交叉验证；留任访谈应定期开展，一次访谈不能一劳永逸。", "knowledge_point": "离职管理与离职面谈", "sort_order": 4}, {"id": 266, "module_code": "employee-relations", "chapter_id": 10, "category": "practice", "qtype": "judge", "stem": "从杨三角视角看，员工关系管理既要建设员工思维层面的认同感（文化沟通），也要建设员工治理层面的机制（申诉、反馈、对齐制度），两者缺一不可。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "杨三角员工思维+员工治理双支柱：认同靠文化沟通，秩序靠机制制度。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 5}, {"id": 140, "module_code": "employee-relations", "chapter_id": 9, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技扩张至 300 人后，销售部两名新人在试用期内主动离职，反馈\"入职第一周不知道找谁、不知道自己该干什么\"。从员工关系视角看，这一现象最本质的原因是？", "options": [{"key": "A", "text": "新人能力不足，无法胜任岗位"}, {"key": "B", "text": "入职体验粗糙导致心理契约受损，新人缺乏归属感与方向感"}, {"key": "C", "text": "公司薪酬缺乏竞争力"}, {"key": "D", "text": "新人不能接受公司文化"}], "answer": ["B"], "explanation": "案例中的反馈指向入职引导缺失（无人连接、无目标指引），这直接伤害入职期形成的心理契约，是最本质的原因；能力、薪酬、文化在题干中均无证据。", "knowledge_point": "员工入职与全生命周期管理", "sort_order": 100}, {"id": 147, "module_code": "employee-relations", "chapter_id": 10, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技产品总监陈工与销售总监刘姐因智能手表交付时间在会议上针锋相对：刘姐已向渠道商承诺上市时间，陈工认为测试未过关、强行上市会砸口碑。从冲突类型看，这主要属于？", "options": [{"key": "A", "text": "关系冲突"}, {"key": "B", "text": "任务冲突"}, {"key": "C", "text": "过程冲突"}, {"key": "D", "text": "情绪冲突"}], "answer": ["B"], "explanation": "分歧聚焦\"何时上市\"这一工作方案与决策本身，属于任务冲突（对工作内容看法不同），可通过对齐事实来管理，而非人际对立。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 100}, {"id": 154, "module_code": "employee-relations", "chapter_id": 11, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技一位高级硬件工程师提出离职，面谈中先说原因是\"薪酬涨 40%\"，林晓追问后才发现真实原因是产品方向反复、成长见顶。这一过程说明了什么？", "options": [{"key": "A", "text": "员工给出的第一个原因往往就是全部原因"}, {"key": "B", "text": "表面原因与深层原因可能不同，需要开放式追问挖掘真实原因"}, {"key": "C", "text": "薪酬是员工离职的唯一原因"}, {"key": "D", "text": "离职面谈应由直属主管主导并进行追问"}], "answer": ["B"], "explanation": "员工常先给出\"安全\"的表面原因，面谈者需要通过开放式追问与不评判的态度挖掘深层原因；这正体现离职面谈的技巧价值。", "knowledge_point": "离职管理与离职面谈", "sort_order": 100}, {"id": 141, "module_code": "employee-relations", "chapter_id": 9, "category": "practice_case", "qtype": "single", "stem": "【案例】针对新人融入困难，林晓为每位新人安排了非直属的\"入职伙伴\"，并在入职第一周由主管与新人共同设定试用期目标。这两项措施分别主要解决了什么问题？", "options": [{"key": "A", "text": "前者解决\"不知道找谁\"的人际连接问题，后者解决试用期方向与标准不清的问题"}, {"key": "B", "text": "前者解决转正审批问题，后者解决薪酬谈判问题"}, {"key": "C", "text": "前者解决办公设备问题，后者解决绩效评分问题"}, {"key": "D", "text": "前者解决离职面谈问题，后者解决跨部门冲突问题"}], "answer": ["A"], "explanation": "入职伙伴对应入职引导的\"人际层面连接\"，共同设定目标对应\"试用期目标前置\"，正好对症\"不知道找谁、不知道干什么\"两个反馈。", "knowledge_point": "员工入职与全生命周期管理", "sort_order": 101}, {"id": 148, "module_code": "employee-relations", "chapter_id": 10, "category": "practice_case", "qtype": "single", "stem": "【案例】为化解陈工与刘姐的分歧，林晓建议王总召开\"事实对齐会\"，要求双方只摆数据、共同确定决策标准。这一做法体现了冲突处理的哪一关键原则？", "options": [{"key": "A", "text": "快速站队，支持更有资历的一方"}, {"key": "B", "text": "把立场之争转化为基于事实与共同目标的问题解决"}, {"key": "C", "text": "回避冲突，等待问题自然平息"}, {"key": "D", "text": "通过人事调整强制解决"}], "answer": ["B"], "explanation": "\"只摆数据、聚焦共同目标\"正是把立场之争转化为基于事实的协商，是处理任务冲突的有效方式；站队、回避、人事调整都会留下隐患。", "knowledge_point": "员工沟通与冲突处理", "sort_order": 101}, {"id": 155, "module_code": "employee-relations", "chapter_id": 11, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓将离职原因结构化分析后发现\"成长空间\"与\"跨部门协作\"排在薪酬之前，推动公司建立技术晋升通道并固化跨部门对齐机制。半年后研发主动离职率回落。这体现了离职管理的哪种价值？", "options": [{"key": "A", "text": "通过离职数据分析推动组织改进，把离职管理变成组织优化的输入"}, {"key": "B", "text": "通过威慑手段阻止员工离职"}, {"key": "C", "text": "通过提高离职补偿降低流失率"}, {"key": "D", "text": "通过减少招聘来控制成本"}], "answer": ["A"], "explanation": "离职数据的价值在于发现\"组织可控制原因\"并推动机制改进，从而预防更多流失；威慑、补偿、减招都不是问题的解。", "knowledge_point": "离职管理与离职面谈", "sort_order": 101}, {"id": 220, "module_code": "training", "chapter_id": 15, "category": "exam", "qtype": "single", "stem": "培训需求分析的三层模型中，“分析组织战略与资源是否支持培训”属于哪一层？", "options": [{"key": "A", "text": "组织层"}, {"key": "B", "text": "任务层"}, {"key": "C", "text": "个人层"}, {"key": "D", "text": "结果层"}], "answer": ["A"], "explanation": "组织层回答“要不要培训、值不值得投”，看战略、资源与组织绩效；任务层看岗位要求，个人层看员工差距。", "knowledge_point": "三层需求分析", "sort_order": 0}, {"id": 300, "module_code": "training", "chapter_id": 16, "category": "exam", "qtype": "judge", "stem": "在线培训灵活、成本低，适合承载复杂技能演练等实操类培训内容。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "在线培训适合知识类标准化内容，但复杂技能演练、态度塑造与岗位实践（721 法则中占 70%）无法被在线形式替代，应组合使用。", "knowledge_point": "培训形式选择", "sort_order": 0}, {"id": 221, "module_code": "training", "chapter_id": 15, "category": "exam", "qtype": "multiple", "stem": "下列关于培训需求调研方法的说法，正确的有（多选）？", "options": [{"key": "A", "text": "访谈能获取深层信息，但耗时较长"}, {"key": "B", "text": "问卷适合大范围收集，但设计不当容易失真"}, {"key": "C", "text": "观察法适合技能类岗位的差距识别"}, {"key": "D", "text": "绩效数据分析只能用于组织层，不能用于个人层"}], "answer": ["A", "B", "C"], "explanation": "绩效数据分析既能看组织整体短板（组织层），也能定位到具体个人（个人层），D 说法错误。调研方法通常组合使用、交叉验证。", "knowledge_point": "需求调研方法", "sort_order": 1}, {"id": 222, "module_code": "training", "chapter_id": 15, "category": "exam", "qtype": "judge", "stem": "需求分析中发现绩效差距后，应直接判定为培训需求。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "必须先“归因”：差距可能源于流程、激励、工具等非能力因素。只有确认是能力不足，才构成培训需求。直接判定是“培训万能论”的典型误区。", "knowledge_point": "绩效差距归因", "sort_order": 2}, {"id": 223, "module_code": "training", "chapter_id": 16, "category": "exam", "qtype": "single", "stem": "“培训结束后两周内，能独立完成开发板电源调试且返工率低于 5%”这一目标表述，体现了培训目标三要素中的？", "options": [{"key": "A", "text": "只有条件，没有行为与标准"}, {"key": "B", "text": "条件、行为、标准三者兼备"}, {"key": "C", "text": "只描述了态度"}, {"key": "D", "text": "与业务目标无关"}], "answer": ["B"], "explanation": "“培训结束后两周内”是条件，“独立完成电源调试”是行为，“返工率低于 5%”是标准。规范的培训目标正是这样可观察、可衡量。", "knowledge_point": "培训目标三要素", "sort_order": 3}, {"id": 224, "module_code": "training", "chapter_id": 16, "category": "exam", "qtype": "multiple", "stem": "柯氏四级评估模型的四个层次包括（多选）？", "options": [{"key": "A", "text": "反应层"}, {"key": "B", "text": "学习层"}, {"key": "C", "text": "行为层"}, {"key": "D", "text": "结果层"}], "answer": ["A", "B", "C", "D"], "explanation": "反应层（满意度）、学习层（知识技能）、行为层（工作行为）、结果层（业务结果）层层递进。从结果层倒推设计，评估才最有说服力。", "knowledge_point": "柯氏四级评估", "sort_order": 4}, {"id": 226, "module_code": "training", "chapter_id": 17, "category": "exam", "qtype": "single", "stem": "继任者评估中，“学习敏锐度”主要反映的是？", "options": [{"key": "A", "text": "过去绩效"}, {"key": "B", "text": "发展潜力"}, {"key": "C", "text": "工作年限"}, {"key": "D", "text": "年龄"}], "answer": ["B"], "explanation": "学习敏锐度指能否快速从经验中学习并适应新情境，是“潜力”维度的核心考察指标；绩效维度看的是过去的结果。", "knowledge_point": "九宫格人才盘点", "sort_order": 6}, {"id": 227, "module_code": "training", "chapter_id": 17, "category": "exam", "qtype": "single", "stem": "企业为资深工程师设置“高级工程师→主任工程师→技术专家”的专业晋升路线，同时保留管理通道，这属于？", "options": [{"key": "A", "text": "单一管理通道"}, {"key": "B", "text": "双通道职业发展"}, {"key": "C", "text": "轮岗制度"}, {"key": "D", "text": "继任计划"}], "answer": ["B"], "explanation": "双通道让技术人才不必挤管理独木桥也能晋升，是留住专家型人才、建设专业人才梯队的核心机制。", "knowledge_point": "双通道职业发展", "sort_order": 7}, {"id": 289, "module_code": "training", "chapter_id": 15, "category": "exam", "qtype": "single", "stem": "某制造企业导入智能制造系统后，一线班组长的工作职责由“单纯生产执行”变为“生产执行＋设备数据监控＋异常响应协调”，岗位说明书与作业标准随之重写。此时，培训需求分析应优先聚焦哪一层次？", "options": [{"key": "A", "text": "组织层——重新评估企业战略是否需要调整"}, {"key": "B", "text": "任务层——重新界定岗位职责与完成工作所需的知识技能"}, {"key": "C", "text": "个人层——盘点全体员工的年龄与司龄结构"}, {"key": "D", "text": "资源层——核算培训场地与预算是否充足"}], "answer": ["B"], "explanation": "三层需求分析中：组织层回答“要不要培训、培训是否支撑战略”，个人层回答“谁需要培训、缺多少”，而任务层回答“培训什么”，即岗位职责与完成工作所需的知识、技能、标准。岗位职责因技术升级发生根本性改变，属于典型的任务层分析场景；个人层分析应在岗位标准明确之后，用来锁定具体有差距的人。", "knowledge_point": "三层需求分析", "sort_order": 8}, {"id": 290, "module_code": "training", "chapter_id": 16, "category": "exam", "qtype": "single", "stem": "某公司依据“721”学习法则设计年度培养方案。下列安排中，最符合该法则理念的是？", "options": [{"key": "A", "text": "将70%的培训预算投入外聘讲师的集中课堂授课"}, {"key": "B", "text": "为学员安排挑战性项目任务，并指定上级在日常工作中给予及时反馈与辅导"}, {"key": "C", "text": "以线上视频自学为主，占全部学习时间的70%"}, {"key": "D", "text": "以案例研讨和沙盘演练等正式课程为主，辅以自学资料"}], "answer": ["B"], "explanation": "“721”学习法则指出，员工能力提升约70%来自在岗实践与挑战性任务的经验学习，约20%来自他人（上级、导师、同事）的反馈与辅导，仅约10%来自正式课堂学习。选项B同时体现“在岗历练（70%）＋他人辅导反馈（20%）”，最符合法则理念；A、C、D都把重心放在正式学习或自学上，与法则比例相悖。", "knowledge_point": "721法则", "sort_order": 9}, {"id": 291, "module_code": "training", "chapter_id": 16, "category": "exam", "qtype": "single", "stem": "某公司用“培训项目实施前后，销售部门季度人均签单额与客户续约率的变化”来衡量一次销售技能培训的效果。按照柯克帕特里克四级评估模型，这种做法属于哪一层次的评估？", "options": [{"key": "A", "text": "反应层——学员对培训内容与讲师的满意度"}, {"key": "B", "text": "学习层——学员对知识技能的掌握程度"}, {"key": "C", "text": "行为层——学员训后工作行为是否发生改变"}, {"key": "D", "text": "结果层——培训对组织经营指标产生的实际影响"}], "answer": ["D"], "explanation": "柯氏四级评估由低到高依次为：反应层（满意度）、学习层（知识技能掌握）、行为层（训后行为迁移）、结果层（对组织绩效与经营成果的影响）。人均签单额、续约率属于组织经营结果指标，因此属于结果层评估。注意区分：行为层看的是“行为是否变了”，结果层看的是“经营结果是否变了”，本题指标指向后者。", "knowledge_point": "柯氏四级评估", "sort_order": 10}, {"id": 292, "module_code": "training", "chapter_id": 17, "category": "exam", "qtype": "multiple", "stem": "某公司以“绩效×潜力”双维度开展人才盘点，形成九宫格。下列关于九宫格应用的说法，正确的有（多选）？", "options": [{"key": "A", "text": "高绩效高潜力员工是重点保留与加速培养对象，应纳入关键岗位继任候选池"}, {"key": "B", "text": "绩效高但潜力偏低的员工，应尽快安排到关键管理岗位接受历练"}, {"key": "C", "text": "潜力高但绩效偏低的员工，应通过岗位调整、辅导与激励找出原因并激发其发挥"}, {"key": "D", "text": "九宫格只能用于管理序列盘点，不适用于专业技术人才"}], "answer": ["A", "C"], "explanation": "九宫格以绩效与潜力两个维度交叉定位人才：高绩效高潜力（明星员工）是组织重点保留与加速培养、优先纳入继任计划的对象，A正确；高绩效低潜力的员工适合在现有专业领域深耕成为专家骨干，而非盲目推向关键管理岗位，B错误；高潜力低绩效者往往存在放错岗位、动机或辅导不足等问题，应分析原因并通过辅导、轮岗、激励激发其潜力，C正确；九宫格同样适用于专业技术人才的盘点与发展，D错误。", "knowledge_point": "九宫格人才盘点", "sort_order": 11}, {"id": 293, "module_code": "training", "chapter_id": 17, "category": "exam", "qtype": "judge", "stem": "在继任计划中，为关键岗位候选人配备的导师，其主要职责是对候选人的培养过程进行考核并作出淘汰决定。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "本题错误。导师制的核心定位是“传帮带”：经验传承、技能传授、职业发展辅导与心理支持，帮助候选人加速成长；而考核、评估与淘汰属于绩效管理职能，应由直线经理和人力资源部门依据绩效评估体系完成。若让导师同时承担考核淘汰职责，会造成角色冲突，使候选人不敢暴露真实困难，导师辅导反而流于形式。", "knowledge_point": "导师制", "sort_order": 12}, {"id": 228, "module_code": "training", "chapter_id": 15, "category": "exam_case", "qtype": "single", "stem": "【案例】王总要求莱茵科技“赶紧培训”，但林晓坚持先做三层需求分析再制定方案。下列最能说明她这样做价值的是？", "options": [{"key": "A", "text": "让流程显得更专业"}, {"key": "B", "text": "确保培训针对真实绩效差距、避免资源浪费，并让目标可衡量、可追溯业务结果"}, {"key": "C", "text": "拖延培训进度"}, {"key": "D", "text": "满足赵姐的指导要求"}], "answer": ["B"], "explanation": "需求分析的价值在于让培训“有的放矢”：组织层对齐战略、任务层明确标准、个人层锁定人群，培训目标和评估才有依据，钱才花在刀刃上。", "knowledge_point": "三层需求分析", "sort_order": 100}, {"id": 229, "module_code": "training", "chapter_id": 16, "category": "exam_case", "qtype": "multiple", "stem": "【案例】林晓为硬件工程师设计“面授集训 + 6 周在岗带教”，为销售设计“在线微课 + 例会复盘”。这一方案主要体现了（多选）？", "options": [{"key": "A", "text": "721 学习法则下以在岗实践为主的混合式设计"}, {"key": "B", "text": "根据人群特点选择差异化培训形式"}, {"key": "C", "text": "只重视正式课堂培训"}, {"key": "D", "text": "从业务目标反推培训目标与评估方式"}], "answer": ["A", "B", "D"], "explanation": "方案按人群特点组合了面授、在线与在岗形式，并以在岗实践为主体（721 法则），同时每一类都有可衡量目标与四级评估。C 与方案事实相反。", "knowledge_point": "721法则", "sort_order": 101}, {"id": 230, "module_code": "training", "chapter_id": 17, "category": "exam_case", "qtype": "single", "stem": "【案例】老周休假期间，其高潜继任者顺利顶替技术支撑工作，产品线未中断。这说明莱茵科技已经具备？", "options": [{"key": "A", "text": "充足的培训预算"}, {"key": "B", "text": "有效的人才梯队与继任机制，关键岗位风险可控"}, {"key": "C", "text": "永不缺人的招聘能力"}, {"key": "D", "text": "无需再关注人员流失"}], "answer": ["B"], "explanation": "这正是继任计划与人才梯队建设要达成的结果：关键岗位有准备度达标的继任者，人员波动不影响业务连续性。", "knowledge_point": "继任计划", "sort_order": 102}, {"id": 41, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "培训需求分析通常包含哪三个层面？", "options": [{"key": "A", "text": "组织层面"}, {"key": "B", "text": "任务（岗位）层面"}, {"key": "C", "text": "个人层面"}, {"key": "D", "text": "竞争对手层面"}], "answer": ["A", "B", "C"], "explanation": "经典的三层需求分析模型：组织分析（战略与资源）、任务分析（岗位胜任要求）、个人分析（能力差距）。", "knowledge_point": "", "sort_order": 0}, {"id": 42, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "柯氏四级培训评估模型中，第一级评估是什么？", "options": [{"key": "A", "text": "学习层（学到什么）"}, {"key": "B", "text": "行为层（应用如何）"}, {"key": "C", "text": "反应层（学员满意度）"}, {"key": "D", "text": "结果层（业务成果）"}], "answer": ["C"], "explanation": "柯氏模型四级：反应层（满意度）→ 学习层（知识技能）→ 行为层（行为改变）→ 结果层（业务结果）。", "knowledge_point": "", "sort_order": 1}, {"id": 43, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "人才梯队建设的核心是什么？", "options": [{"key": "A", "text": "不断招聘外部高管"}, {"key": "B", "text": "识别关键岗位继任者并持续培养"}, {"key": "C", "text": "给所有人同等晋升机会"}, {"key": "D", "text": "只关注高层岗位"}], "answer": ["B"], "explanation": "人才梯队建设聚焦关键岗位的继任计划，通过识别潜力人才、制定培养路径确保组织人才供给。", "knowledge_point": "", "sort_order": 2}, {"id": 44, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "「721 学习法则」中，70% 的学习来自哪里？", "options": [{"key": "A", "text": "课堂培训"}, {"key": "B", "text": "工作实践与经验"}, {"key": "C", "text": "导师辅导"}, {"key": "D", "text": "自学阅读"}], "answer": ["B"], "explanation": "721 法则：70% 来自工作实践、20% 来自他人辅导反馈、10% 来自正式培训。", "knowledge_point": "", "sort_order": 3}, {"id": 45, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "制定年度培训计划前，首先应该做什么？", "options": [{"key": "A", "text": "预订培训场地"}, {"key": "B", "text": "开展培训需求调研与分析"}, {"key": "C", "text": "选择培训讲师"}, {"key": "D", "text": "确定培训预算"}], "answer": ["B"], "explanation": "培训计划应始于需求分析：明确组织战略所需能力与现状差距，再规划课程、资源与预算。", "knowledge_point": "", "sort_order": 4}, {"id": 46, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "按国家规定，企业职工教育经费一般按工资总额的多少比例提取？", "options": [{"key": "A", "text": "1.5%~2.5%"}, {"key": "B", "text": "0.5%~1%"}, {"key": "C", "text": "5%~10%"}, {"key": "D", "text": "无规定"}], "answer": ["A"], "explanation": "《职业教育法》等规定企业应按工资总额的一定比例（一般 1.5%~2.5%）提取职工教育经费。", "knowledge_point": "", "sort_order": 5}, {"id": 47, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "single", "stem": "培训课程设计的第一步是？", "options": [{"key": "A", "text": "明确培训目标与学习成果"}, {"key": "B", "text": "选择培训场地"}, {"key": "C", "text": "制作PPT课件"}, {"key": "D", "text": "发布培训通知"}], "answer": ["A"], "explanation": "课程设计应先明确培训目标（期望的行为改变与学习成果），再设计内容、形式与评估。", "knowledge_point": "", "sort_order": 6}, {"id": 48, "module_code": "training", "chapter_id": null, "category": "placement", "qtype": "multiple", "stem": "继任计划（Succession Planning）的关键步骤包括？", "options": [{"key": "A", "text": "识别关键岗位"}, {"key": "B", "text": "评估继任人选的潜力与准备度"}, {"key": "C", "text": "制定个人发展计划并持续培养"}, {"key": "D", "text": "只看员工司龄长短"}], "answer": ["A", "B", "C"], "explanation": "继任计划围绕关键岗位识别、人选评估与发展培养展开；司龄不是继任资格的唯一依据。", "knowledge_point": "", "sort_order": 7}, {"id": 199, "module_code": "training", "chapter_id": 15, "category": "practice", "qtype": "single", "stem": "培训需求分析（TNA）的直接目的是什么？", "options": [{"key": "A", "text": "丰富员工福利，提升员工满意度"}, {"key": "B", "text": "找出实际绩效与期望绩效之间的差距，并判断能否通过培训弥补"}, {"key": "C", "text": "完成公司年度培训指标"}, {"key": "D", "text": "满足业务领导的临时要求"}], "answer": ["B"], "explanation": "培训需求分析的本质是诊断绩效差距并判断其成因是否属于“员工能力不足”，据此决定要不要培训、培训什么。选项 A、C、D 都偏离了需求分析的目的。", "knowledge_point": "培训需求分析", "sort_order": 0}, {"id": 206, "module_code": "training", "chapter_id": 16, "category": "practice", "qtype": "single", "stem": "柯氏四级评估中，考察“学员回到岗位后工作行为是否发生改变”的是哪一层？", "options": [{"key": "A", "text": "反应层"}, {"key": "B", "text": "学习层"}, {"key": "C", "text": "行为层"}, {"key": "D", "text": "结果层"}], "answer": ["C"], "explanation": "反应层看学员满意度，学习层看知识技能是否掌握，行为层看工作行为是否改变，结果层看业务结果（如良率、效率、销售额）是否改善。", "knowledge_point": "培训计划与实施", "sort_order": 0}, {"id": 213, "module_code": "training", "chapter_id": 17, "category": "practice", "qtype": "single", "stem": "识别关键岗位时，最核心的判断标准是？", "options": [{"key": "A", "text": "岗位薪资最高"}, {"key": "B", "text": "岗位一旦空缺或由不胜任者占据，将对组织战略与业务产生重大影响"}, {"key": "C", "text": "岗位人数最多"}, {"key": "D", "text": "领导最关注"}], "answer": ["B"], "explanation": "关键岗位看的是战略影响度、可替代性与人员风险，与薪资高低、人数多少没有必然关系。", "knowledge_point": "人才梯队与继任计划", "sort_order": 0}, {"id": 200, "module_code": "training", "chapter_id": 15, "category": "practice", "qtype": "multiple", "stem": "下列属于组织层面培训需求分析内容的有（多选）？", "options": [{"key": "A", "text": "组织战略目标与业务方向"}, {"key": "B", "text": "组织可投入的培训资源与预算"}, {"key": "C", "text": "岗位说明书中的职责要求"}, {"key": "D", "text": "组织绩效数据反映的整体能力短板"}], "answer": ["A", "B", "D"], "explanation": "组织层分析看战略、资源与组织绩效；岗位说明书中的职责要求属于任务层分析的内容，故 C 不选。", "knowledge_point": "培训需求分析", "sort_order": 1}, {"id": 207, "module_code": "training", "chapter_id": 16, "category": "practice", "qtype": "multiple", "stem": "下列关于培训形式的说法，正确的有（多选）？", "options": [{"key": "A", "text": "在线培训适合标准化知识类内容，可规模化覆盖"}, {"key": "B", "text": "面授互动性强，适合复杂技能演练"}, {"key": "C", "text": "在岗培训无需任何设计，交给老员工即可"}, {"key": "D", "text": "成熟体系通常将三种形式组合使用，以在岗实践为主"}], "answer": ["A", "B", "D"], "explanation": "在岗培训同样需要设计：明确目标、流程与带教人标准，否则质量不稳定。C 说法错误，故不选。", "knowledge_point": "培训计划与实施", "sort_order": 1}, {"id": 214, "module_code": "training", "chapter_id": 17, "category": "practice", "qtype": "multiple", "stem": "继任者评估通常考察的维度包括（多选）？", "options": [{"key": "A", "text": "历史绩效表现"}, {"key": "B", "text": "发展潜力（如学习敏锐度、成就动机）"}, {"key": "C", "text": "在当前岗位的工作年限"}, {"key": "D", "text": "价值观与任职资格的匹配度"}], "answer": ["A", "B", "D"], "explanation": "继任者评估用“绩效 × 潜力”两个维度：绩效看过去，潜力看未来，并结合价值观与能力标准。工作年限不等于胜任力，C 不选。", "knowledge_point": "人才梯队与继任计划", "sort_order": 1}, {"id": 201, "module_code": "training", "chapter_id": 15, "category": "practice", "qtype": "judge", "stem": "只要员工绩效不达标，就一定是培训需求。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "绩效差距可能源于流程不顺、激励不足、工具落后等多重因素。必须先做“归因”，确认差距源于能力不足，才能判定为培训需求。这是需求分析中最关键的一步。", "knowledge_point": "培训需求分析", "sort_order": 2}, {"id": 208, "module_code": "training", "chapter_id": 16, "category": "practice", "qtype": "judge", "stem": "培训目标应当尽量用“可观察、可衡量”的行为来表述。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "规范的培训目标包含条件、行为、标准三要素，例如“两周内独立完成电源调试且返工率低于 5%”，这样才可考核、可追踪。", "knowledge_point": "培训计划与实施", "sort_order": 2}, {"id": 215, "module_code": "training", "chapter_id": 17, "category": "practice", "qtype": "judge", "stem": "继任计划等同于向继任者承诺一定会提拔。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "继任计划是“准备度管理”——管理继任者与目标岗位之间的差距并持续培养，而不是提拔承诺。提前承诺反而可能引发组织问题。", "knowledge_point": "人才梯队与继任计划", "sort_order": 2}, {"id": 202, "module_code": "training", "chapter_id": 15, "category": "practice", "qtype": "single", "stem": "在培训需求分析中，“做好硬件工程师这份工作需要掌握哪些知识与技能”属于哪一层分析？", "options": [{"key": "A", "text": "组织层"}, {"key": "B", "text": "任务层"}, {"key": "C", "text": "个人层"}, {"key": "D", "text": "结果层"}], "answer": ["B"], "explanation": "任务层分析聚焦岗位本身的要求——完成工作所需的知识、技能与标准；组织层看战略与资源，个人层看员工现状与岗位标准之间的差距。", "knowledge_point": "培训需求分析", "sort_order": 3}, {"id": 209, "module_code": "training", "chapter_id": 16, "category": "practice", "qtype": "single", "stem": "按照 721 学习法则，占 70% 的员工能力提升来源是？", "options": [{"key": "A", "text": "正式课堂培训"}, {"key": "B", "text": "在岗实践"}, {"key": "C", "text": "导师辅导"}, {"key": "D", "text": "自我阅读"}], "answer": ["B"], "explanation": "721 法则：70% 来自在岗实践、20% 来自向他人学习、10% 来自正式培训。导师辅导属于 20% 的部分。", "knowledge_point": "培训计划与实施", "sort_order": 3}, {"id": 216, "module_code": "training", "chapter_id": 17, "category": "practice", "qtype": "single", "stem": "莱茵科技为硬件工程师设置“工程师→高级工程师→主任工程师→技术专家”的晋升路径，这体现了？", "options": [{"key": "A", "text": "单一管理通道"}, {"key": "B", "text": "双通道职业发展"}, {"key": "C", "text": "导师制"}, {"key": "D", "text": "轮岗制度"}], "answer": ["B"], "explanation": "专业通道与管理通道并行即“双通道”，让不擅长或不愿做管理的技术人才也能通过专业路线晋升，避免人才流失。", "knowledge_point": "人才梯队与继任计划", "sort_order": 3}, {"id": 203, "module_code": "training", "chapter_id": 15, "category": "practice", "qtype": "judge", "stem": "721 学习法则认为，员工能力提升的主要来源是正式的课堂培训。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "721 法则指约 70% 的学习来自在岗实践、20% 来自向他人学习（导师与反馈）、只有 10% 来自正式课堂培训。正式培训占比最小，在岗实践才是主渠道。", "knowledge_point": "培训需求分析", "sort_order": 4}, {"id": 210, "module_code": "training", "chapter_id": 16, "category": "practice", "qtype": "judge", "stem": "学员对培训的满意度很高，就说明培训达到了目标。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["B"], "explanation": "满意度属于柯氏评估的反应层，只说明“现场体验好”，不能证明知识掌握了（学习层）、行为变了（行为层）、业务结果改善了（结果层）。", "knowledge_point": "培训计划与实施", "sort_order": 4}, {"id": 217, "module_code": "training", "chapter_id": 17, "category": "practice", "qtype": "judge", "stem": "导师制是一种长期的职业发展关系，重在经验传承与职业引导，不同于短期技能带教。", "options": [{"key": "A", "text": "正确"}, {"key": "B", "text": "错误"}], "answer": ["A"], "explanation": "导师制覆盖职业发展、经验传承与组织洞察，关系长期；技能带教侧重短期内把具体技能教会，二者定位不同。", "knowledge_point": "人才梯队与继任计划", "sort_order": 4}, {"id": 268, "module_code": "training", "chapter_id": 17, "category": "practice", "qtype": "single", "stem": "根据《联盟》观点，企业为员工提供培训与发展机会，本质上是？", "options": [{"key": "A", "text": "公司单方面的成本投入"}, {"key": "B", "text": "双方共同投资的联盟契约——公司获得能力贡献，员工获得成长"}, {"key": "C", "text": "法律强制义务"}, {"key": "D", "text": "纯福利性质"}], "answer": ["B"], "explanation": "联盟任期制：发展投资是公司与员工的双向契约，员工发展提高保留率与贡献。", "knowledge_point": "人才梯队与继任计划", "sort_order": 5}, {"id": 204, "module_code": "training", "chapter_id": 15, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技硬件工程师新人平均需要 6 个月才能独立负责项目，陈工认为“新人不会调传感器”。林晓用三层模型分析后，下列判断最合理的是？", "options": [{"key": "A", "text": "直接给新人安排传感器课程，越快越好"}, {"key": "B", "text": "先做任务层分析明确岗位标准，再测评个人差距，确认差距是否源于能力不足"}, {"key": "C", "text": "把新人全部辞退，重新招聘有经验的人"}, {"key": "D", "text": "跳过分析，直接组织全员培训"}], "answer": ["B"], "explanation": "陈工的说法只是“印象式归因”。正确做法是先以任务层明确岗位标准，再用个人层测评锁定差距，并确认差距成因是能力不足才安排培训，避免培训资源浪费。", "knowledge_point": "培训需求分析", "sort_order": 100}, {"id": 211, "module_code": "training", "chapter_id": 16, "category": "practice_case", "qtype": "single", "stem": "【案例】莱茵科技 60 名销售分布在全国各地，集中面授的差旅成本极高。林晓为销售设计培训时，最合适的选择是？", "options": [{"key": "A", "text": "全国强制集中面授两周"}, {"key": "B", "text": "在线微课学习 + 话术演练打卡 + 销售例会复盘，以在岗应用为主"}, {"key": "C", "text": "取消销售培训，节省成本"}, {"key": "D", "text": "只发学习资料，不做任何跟进"}], "answer": ["B"], "explanation": "结合 721 法则与成本考量，销售类内容适合用在线微课完成知识传递，再通过例会复盘和话术演练实现“在岗应用”，比大规模面授更经济有效。", "knowledge_point": "培训计划与实施", "sort_order": 100}, {"id": 218, "module_code": "training", "chapter_id": 17, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓为产品总监陈工筛选出高潜继任者小孟，安排她牵头一条新产品线的全流程，并由陈工担任导师。这体现了继任计划中的哪些做法？", "options": [{"key": "A", "text": "只做名单管理，不安排发展行动"}, {"key": "B", "text": "项目历练（70%）+ 导师辅导（20%）的发展组合"}, {"key": "C", "text": "直接向小孟承诺总监职位"}, {"key": "D", "text": "用外部猎头招聘替代内部培养"}], "answer": ["B"], "explanation": "牵头新产品全流程是在岗实践（70%），陈工担任导师属于辅导反馈（20%），这是继任者培养的典型做法。继任计划是准备度管理，不是提拔承诺。", "knowledge_point": "人才梯队与继任计划", "sort_order": 100}, {"id": 205, "module_code": "training", "chapter_id": 15, "category": "practice_case", "qtype": "single", "stem": "【案例】销售总监刘姐反映新人“讲不清新品功能”，要求立刻安排话术培训。林晓最应该先做什么？", "options": [{"key": "A", "text": "马上安排话术课程，第一时间响应业务需求"}, {"key": "B", "text": "先做需求分析，确认问题到底是能力问题、产品资料问题还是激励问题"}, {"key": "C", "text": "认为销售问题与 HR 无关，不予理会"}, {"key": "D", "text": "直接更换销售团队"}], "answer": ["B"], "explanation": "培训不是万金油。“讲不清功能”可能源于培训不足，也可能源于产品资料不清晰、话术没人把关等原因。先归因再决策，正是需求分析的价值所在。", "knowledge_point": "培训需求分析", "sort_order": 101}, {"id": 212, "module_code": "training", "chapter_id": 16, "category": "practice_case", "qtype": "single", "stem": "【案例】林晓要证明“新人硬件工程师培训有效”，下列哪一项证据最能打动王总？", "options": [{"key": "A", "text": "培训现场的照片和学员点赞"}, {"key": "B", "text": "学员满意度问卷平均 4.8 分"}, {"key": "C", "text": "培训后 4 个月，新人独立上手周期从 6 个月缩短到 4 个月，调试通过率达标"}, {"key": "D", "text": "讲师授课水平高"}], "answer": ["C"], "explanation": "最能说明价值的是柯氏评估的结果层证据——业务结果实实在在改善。满意度（反应层）与讲师评价都停留在体验层面，说服力有限。", "knowledge_point": "培训计划与实施", "sort_order": 101}, {"id": 219, "module_code": "training", "chapter_id": 17, "category": "practice_case", "qtype": "single", "stem": "【案例】资深工程师老周休长假三周，他的高潜继任者顺利顶替了技术支撑工作，产品线没有中断。这说明？", "options": [{"key": "A", "text": "老周的工作并不重要"}, {"key": "B", "text": "继任计划有效降低了关键岗位的人员风险，保障了业务连续性"}, {"key": "C", "text": "公司运气好"}, {"key": "D", "text": "培训预算充足"}], "answer": ["B"], "explanation": "继任计划的直接价值就是降低关键岗位“一人走、业务塌”的风险：有准备度达标的继任者，人员波动才不会影响业务运转。", "knowledge_point": "人才梯队与继任计划", "sort_order": 101}]}